declare
 payload jsonb := $correcciones36${"patches": [{"numero": "Q001", "id": "4416d7b5-88c5-4401-88e7-c316d94de0b8", "decision": "approve", "motivo": "Se confirma el nuevo criterio en el corpus y se reemplaza el objetivo anterior. Antecedente: Complementaria: objeto general de la Ley, sin objetivo operativo directo del temario. Diferenciación: Q021 y Q029 tratan normas técnicas; este caso decide sobre prestaciones accesorias y ciclo de vida. Excepciones y condiciones: La obligación es evaluar y se circunscribe a bienes y obras; no impone contratación conjunta automática.", "objetivo": "Evaluar prestaciones accesorias considerando el ciclo de vida del activo.", "evidencia": [{"chunkId": "4d7d9d61-2f43-4e5f-ac1b-af1f2b069308", "chunk_index": 50, "article": "44", "quote": "44.4. Asimismo, en el caso de bienes y obras, se evalúa la necesidad de contar con prestaciones accesorias como el mantenimiento y la operación, considerando el ciclo de vida del activo."}], "input": {"id": "4416d7b5-88c5-4401-88e7-c316d94de0b8", "revision": 1, "prompt": "Una entidad prepara la compra de bombas de agua que requerirán operación y mantenimiento durante su vida útil. El área usuaria propone analizar únicamente el suministro inicial. ¿Qué corresponde al elaborar el requerimiento?", "options": [{"id": "A", "text": "Evaluar la necesidad de incorporar operación y mantenimiento considerando el ciclo de vida del activo."}, {"id": "B", "text": "Excluir el mantenimiento hasta después de recibir los bienes."}, {"id": "C", "text": "Incluir obligatoriamente toda operación y mantenimiento en un solo contrato, sin evaluación."}, {"id": "D", "text": "Dejar la evaluación del ciclo de vida exclusivamente a los proveedores al presentar ofertas."}], "correctOption": "A", "explanation": "El numeral 44.4 dispone que, para bienes y obras, se evalúe la necesidad de prestaciones accesorias como mantenimiento y operación considerando el ciclo de vida del activo. Debe realizarse esa evaluación; su resultado no equivale a una inclusión automática de todas las prestaciones en un único contrato.", "regime": "32069", "topic": "Requerimiento, estrategia y mercado", "competency": "Actuaciones preparatorias", "difficulty": "intermediate", "curriculumVersion": "oece-2025-04-25", "competencyCode": "1", "subcompetencyCode": "1.2", "cognitiveLevel": "apply", "optionRationales": {"A": "El numeral 44.4 exige evaluar la necesidad de prestaciones accesorias atendiendo al ciclo de vida.", "B": "Postergar el análisis omite una evaluación que corresponde al preparar el requerimiento.", "C": "La norma exige evaluar la necesidad; no ordena contratar siempre todas las prestaciones juntas.", "D": "La evaluación corresponde a la entidad al elaborar el requerimiento y no se traslada a las ofertas."}, "reviewChecks": {"unambiguous": true, "distractors": true, "conditions": true, "exceptions": true, "sources": true}, "sourceCutoff": "2026-10-29", "origin": "manual", "sources": [{"documentId": "8371bce1-f773-4ad8-8efa-1266276ae4ec", "chunkId": "4d7d9d61-2f43-4e5f-ac1b-af1f2b069308", "title": "Reglamento de la Ley N.° 32069 — texto actualizado al 09.01.2026", "article": "44", "pageStart": 24, "pageEnd": 25, "quote": "44.4. Asimismo, en el caso de bienes y obras, se evalúa la necesidad de contar con prestaciones accesorias como el mantenimiento y la operación, considerando el ciclo de vida del activo.", "version": "Texto actualizado al 09.01.2026", "sha256": "0ebe95b3e05661b80f73c060d6e6ce8dd17621ce34af9277c688dd67e5d99830"}], "status": "published", "reviewBasis": "Revisión asistida por IA el15/11/2026 por encargo y autorización expresa del administrador. Se confirma el nuevo criterio en el corpus y se reemplaza el objetivo anterior. Antecedente: Complementaria: objeto general de la Ley, sin objetivo operativo directo del temario. Diferenciación: Q021 y Q029 tratan normas técnicas; este caso decide sobre prestaciones accesorias y ciclo de vida. Excepciones y condiciones: La obligación es evaluar y se circunscribe a bienes y obras; no impone contratación conjunta automática. Objetivo: Evaluar prestaciones accesorias considerando el ciclo de vida del activo.. Evidencia: art. 44, chunk 50. Sin certificación oficial OECE ni revisión humana independiente; se conserva el corte documental declarado.", "confirmReview": true}, "estadoAnterior": "draft"}, {"numero": "Q002", "id": "ef1ce938-6b62-4d3e-8dac-9b854e8cfebe", "decision": "approve", "motivo": "Se confirma el nuevo criterio en el corpus y se reemplaza el objetivo anterior. Antecedente: Complementaria: finalidad general de la Ley sin aplicación concreta a una subcompetencia. Diferenciación: Frente a Q026, sobre alcance normativo de la intervención de la DEC, se decide una restricción concreta de marca y su excepción. Excepciones y condiciones: Se examinó la excepción de compatibilización: alegar compatibilidad no equivale a obtener la aprobación requerida.", "objetivo": "Resolver una exigencia de marca sin compatibilización aprobada.", "evidencia": [{"chunkId": "4d7d9d61-2f43-4e5f-ac1b-af1f2b069308", "chunk_index": 50, "article": "44", "quote": "44.6. El requerimiento no incluye exigencias desproporcionadas e innecesarias que limiten la concurrencia o favorezcan a determinado proveedor ni hace referencia a procedencia, fabricante, marca, patente, origen o tipos de producción, ni descripción que or iente la contratación hacia ellos, salvo que la autoridad de la gestión administrativa haya aprobado el correspondiente proceso de compatibilización del requerimiento, conforme a las disposiciones que establezca la DGA mediante directiva."}], "input": {"id": "ef1ce938-6b62-4d3e-8dac-9b854e8cfebe", "revision": 1, "prompt": "El requerimiento de equipos exige una marca determinada. Se alega compatibilidad con equipos existentes, pero no se ha aprobado el proceso de compatibilización por la autoridad de la gestión administrativa. ¿Cómo debe tratarse la exigencia?", "options": [{"id": "A", "text": "Mantenerla con una cotización del fabricante que sustituya la aprobación."}, {"id": "B", "text": "Mantenerla si el área usuaria declara preferencia por esa marca."}, {"id": "C", "text": "Corregir la referencia a marca; la excepción exige el proceso de compatibilización aprobado."}, {"id": "D", "text": "Conservarla si cotizan dos distribuidores de la misma marca."}], "correctOption": "C", "explanation": "El numeral 44.6 prohíbe orientar el requerimiento hacia una marca, salvo aprobación del correspondiente proceso de compatibilización por la autoridad de la gestión administrativa conforme a las disposiciones de la DGA. La mera compatibilidad invocada no permite conservar esa referencia sin la aprobación exigida.", "regime": "32069", "topic": "Requerimiento, estrategia y mercado", "competency": "Actuaciones preparatorias", "difficulty": "intermediate", "curriculumVersion": "oece-2025-04-25", "competencyCode": "1", "subcompetencyCode": "1.2", "cognitiveLevel": "apply", "optionRationales": {"A": "La cotización acredita una oferta comercial y no sustituye la aprobación del proceso de compatibilización.", "B": "La preferencia del área usuaria no constituye la excepción prevista por el numeral 44.6.", "C": "La excepción a la prohibición de orientar hacia una marca exige el proceso de compatibilización aprobado.", "D": "La pluralidad de distribuidores no subsana la falta de aprobación de compatibilización."}, "reviewChecks": {"unambiguous": true, "distractors": true, "conditions": true, "exceptions": true, "sources": true}, "sourceCutoff": "2026-10-29", "origin": "manual", "sources": [{"documentId": "8371bce1-f773-4ad8-8efa-1266276ae4ec", "chunkId": "4d7d9d61-2f43-4e5f-ac1b-af1f2b069308", "title": "Reglamento de la Ley N.° 32069 — texto actualizado al 09.01.2026", "article": "44", "pageStart": 24, "pageEnd": 25, "quote": "44.6. El requerimiento no incluye exigencias desproporcionadas e innecesarias que limiten la concurrencia o favorezcan a determinado proveedor ni hace referencia a procedencia, fabricante, marca, patente, origen o tipos de producción, ni descripción que or iente la contratación hacia ellos, salvo que la autoridad de la gestión administrativa haya aprobado el correspondiente proceso de compatibilización del requerimiento, conforme a las disposiciones que establezca la DGA mediante directiva.", "version": "Texto actualizado al 09.01.2026", "sha256": "0ebe95b3e05661b80f73c060d6e6ce8dd17621ce34af9277c688dd67e5d99830"}], "status": "published", "reviewBasis": "Revisión asistida por IA el15/11/2026 por encargo y autorización expresa del administrador. Se confirma el nuevo criterio en el corpus y se reemplaza el objetivo anterior. Antecedente: Complementaria: finalidad general de la Ley sin aplicación concreta a una subcompetencia. Diferenciación: Frente a Q026, sobre alcance normativo de la intervención de la DEC, se decide una restricción concreta de marca y su excepción. Excepciones y condiciones: Se examinó la excepción de compatibilización: alegar compatibilidad no equivale a obtener la aprobación requerida. Objetivo: Resolver una exigencia de marca sin compatibilización aprobada.. Evidencia: art. 44, chunk 50. Sin certificación oficial OECE ni revisión humana independiente; se conserva el corte documental declarado.", "confirmReview": true}, "estadoAnterior": "draft"}, {"numero": "Q003", "id": "51338217-e209-41a6-81a2-d25abba9b73f", "decision": "approve", "motivo": "Se confirma el nuevo criterio en el corpus y se reemplaza el objetivo anterior. Antecedente: Complementaria: ámbito general de aplicación, sin correspondencia directa demostrada. Diferenciación: Difiere de Q012, sobre alternativas de los evaluadores ante objeción fundada en selección: aquí se evalúa una objeción preparatoria sin riesgo. Excepciones y condiciones: Se preserva la objeción por riesgo sustantivo; no se afirma aceptación obligatoria de toda propuesta de la DEC.", "objetivo": "Juzgar la admisibilidad de objeción del área usuaria por simple preferencia de redacción.", "evidencia": [{"chunkId": "88817114-d891-44f7-b8a0-802a9b1247a4", "chunk_index": 51, "article": "44", "quote": "44.8. El área usuaria puede objetar la modificación del requerimiento propuesto por la DEC sólo cuando exista el riesgo de que no se satisfaga su necesidad y no se cumpla la finalidad pública de la contratación."}], "input": {"id": "51338217-e209-41a6-81a2-d25abba9b73f", "revision": 1, "prompt": "La DEC propone durante las actuaciones preparatorias modificar el requerimiento. El área usuaria reconoce que la propuesta satisface su necesidad y finalidad pública, pero quiere objetarla solo porque prefiere su redacción original. ¿Es admisible ese fundamento según el numeral 44.8?", "options": [{"id": "A", "text": "Sí, cualquier diferencia de redacción habilita la objeción."}, {"id": "B", "text": "Sí, la DEC no puede proponer cambios en actuaciones preparatorias."}, {"id": "C", "text": "No; el área usuaria nunca puede objetar las modificaciones de la DEC."}, {"id": "D", "text": "No; la objeción requiere riesgo de no satisfacer la necesidad y de no cumplir la finalidad pública."}], "correctOption": "D", "explanation": "El numeral 44.8 permite objetar la modificación propuesta por la DEC solo cuando exista riesgo de que no se satisfaga la necesidad y no se cumpla la finalidad pública. La preferencia por la redacción anterior, cuando se reconoce que la propuesta satisface ambas, no cumple esa condición.", "regime": "32069", "topic": "Requerimiento, estrategia y mercado", "competency": "Actuaciones preparatorias", "difficulty": "intermediate", "curriculumVersion": "oece-2025-04-25", "competencyCode": "1", "subcompetencyCode": "1.2", "cognitiveLevel": "apply", "optionRationales": {"A": "La preferencia de redacción no configura el riesgo sustantivo exigido por el numeral 44.8.", "B": "El régimen permite propuestas de modificación durante actuaciones preparatorias; no hay incompetencia absoluta.", "C": "Sí existe posibilidad de objeción cuando se presenta el riesgo sustantivo previsto por la norma.", "D": "Sin el riesgo indicado, falta el fundamento sustantivo que la norma exige para objetar."}, "reviewChecks": {"unambiguous": true, "distractors": true, "conditions": true, "exceptions": true, "sources": true}, "sourceCutoff": "2026-10-29", "origin": "manual", "sources": [{"documentId": "8371bce1-f773-4ad8-8efa-1266276ae4ec", "chunkId": "88817114-d891-44f7-b8a0-802a9b1247a4", "title": "Reglamento de la Ley N.° 32069 — texto actualizado al 09.01.2026", "article": "44", "pageStart": 24, "pageEnd": 25, "quote": "44.8. El área usuaria puede objetar la modificación del requerimiento propuesto por la DEC sólo cuando exista el riesgo de que no se satisfaga su necesidad y no se cumpla la finalidad pública de la contratación.", "version": "Texto actualizado al 09.01.2026", "sha256": "0ebe95b3e05661b80f73c060d6e6ce8dd17621ce34af9277c688dd67e5d99830"}], "status": "published", "reviewBasis": "Revisión asistida por IA el15/11/2026 por encargo y autorización expresa del administrador. Se confirma el nuevo criterio en el corpus y se reemplaza el objetivo anterior. Antecedente: Complementaria: ámbito general de aplicación, sin correspondencia directa demostrada. Diferenciación: Difiere de Q012, sobre alternativas de los evaluadores ante objeción fundada en selección: aquí se evalúa una objeción preparatoria sin riesgo. Excepciones y condiciones: Se preserva la objeción por riesgo sustantivo; no se afirma aceptación obligatoria de toda propuesta de la DEC. Objetivo: Juzgar la admisibilidad de objeción del área usuaria por simple preferencia de redacción.. Evidencia: art. 44, chunk 51. Sin certificación oficial OECE ni revisión humana independiente; se conserva el corte documental declarado.", "confirmReview": true}, "estadoAnterior": "draft"}, {"numero": "Q004", "id": "8f8fdeb6-315a-4437-80f6-72c7386759d6", "decision": "approve", "motivo": "Se confirma el nuevo criterio en el corpus y se reemplaza el objetivo anterior. Antecedente: Complementaria: sujeción legal general de contratos menores, sin actuación específica del temario. Diferenciación: No replica Q229, que exige expediente técnico en solo construcción; se determina el objeto de prestaciones mixtas. Excepciones y condiciones: El mayor costo no se aplica mecánicamente: se declara comprobado el respeto a la naturaleza de la contratación.", "objetivo": "Determinar el objeto de prestaciones mixtas por mayor costo respetando su naturaleza.", "evidencia": [{"chunkId": "88817114-d891-44f7-b8a0-802a9b1247a4", "chunk_index": 51, "article": "44", "quote": "44.10. El objeto del requerimiento se determina en función a la naturaleza de la contratación. En el caso de contrataciones que involucren diversos tipos de prestaciones, el objeto se determina en función a la prestación que represente el mayor costo, siem pre que no desvirtúe la naturaleza de la contratación."}], "input": {"id": "8f8fdeb6-315a-4437-80f6-72c7386759d6", "revision": 1, "prompt": "Una contratación combina bienes por S/180 000 y servicios por S/70 000. La entidad comprueba que tomar la prestación de mayor costo no desvirtúa la naturaleza de la contratación. ¿Qué criterio corresponde para determinar su objeto?", "options": [{"id": "A", "text": "La prestación de bienes, por su mayor costo y respetarse la naturaleza de la contratación."}, {"id": "B", "text": "La prestación que demande más horas, aunque tenga menor costo."}, {"id": "C", "text": "La preferencia de la unidad que elaboró primero sus documentos."}, {"id": "D", "text": "La prestación de menor costo para simplificar el procedimiento."}], "correctOption": "A", "explanation": "El numeral 44.10 determina el objeto según la naturaleza de la contratación. Cuando existen diversos tipos de prestaciones, se atiende a la de mayor costo siempre que no se desvirtúe esa naturaleza. Los bienes cuestan S/180 000 frente a S/70 000 de servicios y el límite ha sido verificado.", "regime": "32069", "topic": "Requerimiento, estrategia y mercado", "competency": "Actuaciones preparatorias", "difficulty": "intermediate", "curriculumVersion": "oece-2025-04-25", "competencyCode": "1", "subcompetencyCode": "1.2", "cognitiveLevel": "apply", "optionRationales": {"A": "Los bienes tienen mayor costo y el supuesto satisface el límite de no desvirtuar la naturaleza.", "B": "Las horas de trabajo no sustituyen el criterio de mayor costo para prestaciones diversas.", "C": "La prioridad de elaboración no determina el objeto de una contratación con prestaciones diversas.", "D": "Elegir la prestación menor para simplificar contradice el criterio establecido por el numeral 44.10."}, "reviewChecks": {"unambiguous": true, "distractors": true, "conditions": true, "exceptions": true, "sources": true}, "sourceCutoff": "2026-10-29", "origin": "manual", "sources": [{"documentId": "8371bce1-f773-4ad8-8efa-1266276ae4ec", "chunkId": "88817114-d891-44f7-b8a0-802a9b1247a4", "title": "Reglamento de la Ley N.° 32069 — texto actualizado al 09.01.2026", "article": "44", "pageStart": 24, "pageEnd": 25, "quote": "44.10. El objeto del requerimiento se determina en función a la naturaleza de la contratación. En el caso de contrataciones que involucren diversos tipos de prestaciones, el objeto se determina en función a la prestación que represente el mayor costo, siem pre que no desvirtúe la naturaleza de la contratación.", "version": "Texto actualizado al 09.01.2026", "sha256": "0ebe95b3e05661b80f73c060d6e6ce8dd17621ce34af9277c688dd67e5d99830"}], "status": "published", "reviewBasis": "Revisión asistida por IA el15/11/2026 por encargo y autorización expresa del administrador. Se confirma el nuevo criterio en el corpus y se reemplaza el objetivo anterior. Antecedente: Complementaria: sujeción legal general de contratos menores, sin actuación específica del temario. Diferenciación: No replica Q229, que exige expediente técnico en solo construcción; se determina el objeto de prestaciones mixtas. Excepciones y condiciones: El mayor costo no se aplica mecánicamente: se declara comprobado el respeto a la naturaleza de la contratación. Objetivo: Determinar el objeto de prestaciones mixtas por mayor costo respetando su naturaleza.. Evidencia: art. 44, chunk 51. Sin certificación oficial OECE ni revisión humana independiente; se conserva el corte documental declarado.", "confirmReview": true}, "estadoAnterior": "draft"}, {"numero": "Q036", "id": "d13c44ee-2841-4f24-bc82-82d640b7211e", "decision": "approve", "motivo": "Se confirma el nuevo criterio en el corpus y se reemplaza el objetivo anterior. Antecedente: Complementaria: política de profesionalización, distinta de los tipos y perfiles de evaluadores. Diferenciación: Q116 identifica una fuente histórica pública; este caso decide sobre protección de datos no públicos. Excepciones y condiciones: La regla protege información no pública; no se impone reserva indiscriminada sobre toda la interacción.", "objetivo": "Proteger información no pública conocida indirectamente en la interacción con el mercado.", "evidencia": [{"chunkId": "3e8aa2d8-bb3e-416b-b8b4-9bf6cca0070e", "chunk_index": 55, "article": "47", "quote": "47.2. La entidad contratante guarda confidencialidad respecto de toda información, datos o documentación que no sea de acceso público, a la que tenga acceso directa o indirectamente como consecuencia del desarrollo de la interacción con el mercado, conform e a la normativa de la materia."}], "input": {"id": "d13c44ee-2841-4f24-bc82-82d640b7211e", "revision": 2, "prompt": "Durante la interacción con el mercado, la entidad recibe indirectamente una estructura de costos de un proveedor que no es de acceso público. Otro proveedor pide copia para preparar comentarios. ¿Qué actuación exige el numeral 47.2?", "options": [{"id": "A", "text": "Entregarla porque toda información de interacción se vuelve pública automáticamente."}, {"id": "B", "text": "Guardar confidencialidad conforme a la normativa de la materia, aunque el acceso haya sido indirecto."}, {"id": "C", "text": "Divulgarla eliminando el nombre, sin revisar la normativa de confidencialidad."}, {"id": "D", "text": "Compartirla solo con proveedores que hayan presentado cotización."}], "correctOption": "B", "explanation": "El numeral 47.2 exige guardar confidencialidad respecto de información, datos o documentación no públicos conocidos directa o indirectamente como consecuencia de la interacción con el mercado. El acceso indirecto no elimina ese deber, que se aplica conforme a la normativa de la materia.", "regime": "32069", "topic": "Requerimiento, estrategia y mercado", "competency": "Actuaciones preparatorias", "difficulty": "intermediate", "curriculumVersion": "oece-2025-04-25", "competencyCode": "1", "subcompetencyCode": "1.2", "cognitiveLevel": "apply", "optionRationales": {"A": "La interacción no transforma automáticamente documentos no públicos en información de acceso público.", "B": "La protección comprende información no pública conocida directa o indirectamente por la interacción.", "C": "Eliminar el nombre no sustituye por sí solo el deber de confidencialidad según la normativa aplicable.", "D": "La presentación de cotizaciones no otorga excepción general para acceder a datos no públicos ajenos."}, "reviewChecks": {"unambiguous": true, "distractors": true, "conditions": true, "exceptions": true, "sources": true}, "sourceCutoff": "2026-10-29", "origin": "IA:gemini:gemini-2.5-flash:lote:89e558f0-10ed-49e1-acb2-bbdb5486d65e", "sources": [{"documentId": "8371bce1-f773-4ad8-8efa-1266276ae4ec", "chunkId": "3e8aa2d8-bb3e-416b-b8b4-9bf6cca0070e", "title": "Reglamento de la Ley N.° 32069 — texto actualizado al 09.01.2026", "article": "47", "pageStart": 27, "pageEnd": 27, "quote": "47.2. La entidad contratante guarda confidencialidad respecto de toda información, datos o documentación que no sea de acceso público, a la que tenga acceso directa o indirectamente como consecuencia del desarrollo de la interacción con el mercado, conform e a la normativa de la materia.", "version": "Texto actualizado al 09.01.2026", "sha256": "0ebe95b3e05661b80f73c060d6e6ce8dd17621ce34af9277c688dd67e5d99830"}], "status": "published", "reviewBasis": "Revisión asistida por IA el15/11/2026 por encargo y autorización expresa del administrador. Se confirma el nuevo criterio en el corpus y se reemplaza el objetivo anterior. Antecedente: Complementaria: política de profesionalización, distinta de los tipos y perfiles de evaluadores. Diferenciación: Q116 identifica una fuente histórica pública; este caso decide sobre protección de datos no públicos. Excepciones y condiciones: La regla protege información no pública; no se impone reserva indiscriminada sobre toda la interacción. Objetivo: Proteger información no pública conocida indirectamente en la interacción con el mercado.. Evidencia: art. 47, chunk 55. Sin certificación oficial OECE ni revisión humana independiente; se conserva el corte documental declarado.", "confirmReview": true}, "estadoAnterior": "draft"}, {"numero": "Q037", "id": "9d252bae-187a-490e-ba73-497472b23613", "decision": "approve", "motivo": "Se confirma el nuevo criterio en el corpus y se reemplaza el objetivo anterior. Antecedente: Complementaria: supervisión de profesionalización, distinta de funciones operativas de DEC y evaluadores. Diferenciación: Q116 identifica una fuente permitida; aquí se verifica el mínimo necesario para clasificar la indagación avanzada. Excepciones y condiciones: El caso define una sola fuente; no se supone que cada dato dentro del historial constituye otra fuente.", "objetivo": "Comprobar el mínimo de fuentes para una indagación avanzada.", "evidencia": [{"chunkId": "059e3aeb-6b60-416a-a044-abcfeee25863", "chunk_index": 56, "article": "48", "quote": "48.3. La indagación puede ser básica o avanzada. Para la indagación básica se utilizan como mínimo una fuente de información, mientras que para la indagación avanzada se utilizan dos o más fuentes."}], "input": {"id": "9d252bae-187a-490e-ba73-497472b23613", "revision": 2, "prompt": "La DEC usa únicamente el historial de contratos de su entidad como una sola fuente de información, sin incorporar otra, y pretende clasificar su indagación como avanzada. ¿Qué debe corregir?", "options": [{"id": "A", "text": "Basta denominarla avanzada si el historial contiene varios importes."}, {"id": "B", "text": "Debe reemplazar el historial por una sola cotización, con lo que se vuelve avanzada."}, {"id": "C", "text": "Debe incorporar al menos una segunda fuente de información para cumplir el mínimo de la indagación avanzada."}, {"id": "D", "text": "Debe usar necesariamente cuatro fuentes de información para que sea avanzada."}], "correctOption": "C", "explanation": "El numeral 48.3 exige al menos una fuente para la indagación básica y dos o más para la avanzada. Como el caso define expresamente una sola fuente, debe incorporarse al menos otra para sostener la clasificación avanzada.", "regime": "32069", "topic": "Requerimiento, estrategia y mercado", "competency": "Actuaciones preparatorias", "difficulty": "intermediate", "curriculumVersion": "oece-2025-04-25", "competencyCode": "1", "subcompetencyCode": "1.2", "cognitiveLevel": "apply", "optionRationales": {"A": "Varios importes dentro de la única fuente definida en el supuesto no satisfacen el mínimo de dos fuentes.", "B": "Reemplazar una fuente por otra única mantiene el incumplimiento del mínimo normativo de dos.", "C": "La indagación avanzada requiere dos o más fuentes; una sola no satisface ese mínimo.", "D": "El numeral 48.3 exige dos o más fuentes, no un mínimo obligatorio de cuatro fuentes."}, "reviewChecks": {"unambiguous": true, "distractors": true, "conditions": true, "exceptions": true, "sources": true}, "sourceCutoff": "2026-10-29", "origin": "IA:gemini:gemini-2.5-flash:lote:89e558f0-10ed-49e1-acb2-bbdb5486d65e", "sources": [{"documentId": "8371bce1-f773-4ad8-8efa-1266276ae4ec", "chunkId": "059e3aeb-6b60-416a-a044-abcfeee25863", "title": "Reglamento de la Ley N.° 32069 — texto actualizado al 09.01.2026", "article": "48", "pageStart": 27, "pageEnd": 27, "quote": "48.3. La indagación puede ser básica o avanzada. Para la indagación básica se utilizan como mínimo una fuente de información, mientras que para la indagación avanzada se utilizan dos o más fuentes.", "version": "Texto actualizado al 09.01.2026", "sha256": "0ebe95b3e05661b80f73c060d6e6ce8dd17621ce34af9277c688dd67e5d99830"}], "status": "published", "reviewBasis": "Revisión asistida por IA el15/11/2026 por encargo y autorización expresa del administrador. Se confirma el nuevo criterio en el corpus y se reemplaza el objetivo anterior. Antecedente: Complementaria: supervisión de profesionalización, distinta de funciones operativas de DEC y evaluadores. Diferenciación: Q116 identifica una fuente permitida; aquí se verifica el mínimo necesario para clasificar la indagación avanzada. Excepciones y condiciones: El caso define una sola fuente; no se supone que cada dato dentro del historial constituye otra fuente. Objetivo: Comprobar el mínimo de fuentes para una indagación avanzada.. Evidencia: art. 48, chunk 56. Sin certificación oficial OECE ni revisión humana independiente; se conserva el corte documental declarado.", "confirmReview": true}, "estadoAnterior": "draft"}, {"numero": "Q038", "id": "0cca1c4c-c904-4f79-88dc-f1acd7dbc351", "decision": "approve", "motivo": "Se confirma el nuevo criterio en el corpus y se reemplaza el objetivo anterior. Antecedente: Complementaria: estrategia nacional de profesionalización, sin objetivo directo en el temario. Diferenciación: Q035 trata la herramienta obligatoria en CPI; aquí se clasifica la consulta general por herramientas de la misma clase. Excepciones y condiciones: No se inventa exigencia de combinar escritura y reuniones; el caso define dos herramientas distintas.", "objetivo": "Clasificar consulta avanzada con dos herramientas de la misma clasificación.", "evidencia": [{"chunkId": "dc353985-af23-42bb-9012-4e5e06e55c9b", "chunk_index": 57, "article": "49", "quote": "49.2. La consulta al mercado puede ser básica o avanzada. En el caso de la consulta al mercado básica, se emplea una sola herramienta de interacción, sea escrita o reuniones, mientras que para la avanzada se utilizan dos o más herramientas de la misma o di stinta clasificación."}], "input": {"id": "0cca1c4c-c904-4f79-88dc-f1acd7dbc351", "revision": 2, "prompt": "La entidad utiliza dos herramientas diferenciadas de reunión en su consulta al mercado: un taller con la industria y reuniones individuales con proveedores. No emplea herramientas escritas. ¿Cómo se clasifica por esas herramientas?", "options": [{"id": "A", "text": "Básica, porque ambas herramientas son reuniones."}, {"id": "B", "text": "Básica, porque toda consulta avanzada requiere una herramienta escrita."}, {"id": "C", "text": "Avanzada solo si se revisan además tres ejercicios presupuestales de datos históricos."}, {"id": "D", "text": "Avanzada, porque usa dos herramientas que pueden pertenecer a la misma clasificación."}], "correctOption": "D", "explanation": "El numeral 49.2 distingue la consulta básica por una sola herramienta y la avanzada por dos o más herramientas de igual o distinta clasificación. Dos herramientas diferenciadas de reunión pueden configurar una consulta avanzada sin añadir una herramienta escrita.", "regime": "32069", "topic": "Requerimiento, estrategia y mercado", "competency": "Actuaciones preparatorias", "difficulty": "intermediate", "curriculumVersion": "oece-2025-04-25", "competencyCode": "1", "subcompetencyCode": "1.2", "cognitiveLevel": "apply", "optionRationales": {"A": "Que ambas sean reuniones no impide que dos herramientas configuren consulta avanzada.", "B": "La consulta avanzada admite herramientas de igual clasificación y no exige necesariamente una escrita.", "C": "La revisión de ejercicios históricos no condiciona la clasificación por herramientas del numeral 49.2.", "D": "Dos o más herramientas de la misma o distinta clasificación satisfacen la regla del numeral 49.2."}, "reviewChecks": {"unambiguous": true, "distractors": true, "conditions": true, "exceptions": true, "sources": true}, "sourceCutoff": "2026-10-29", "origin": "IA:gemini:gemini-2.5-flash:lote:89e558f0-10ed-49e1-acb2-bbdb5486d65e", "sources": [{"documentId": "8371bce1-f773-4ad8-8efa-1266276ae4ec", "chunkId": "dc353985-af23-42bb-9012-4e5e06e55c9b", "title": "Reglamento de la Ley N.° 32069 — texto actualizado al 09.01.2026", "article": "49", "pageStart": 27, "pageEnd": 27, "quote": "49.2. La consulta al mercado puede ser básica o avanzada. En el caso de la consulta al mercado básica, se emplea una sola herramienta de interacción, sea escrita o reuniones, mientras que para la avanzada se utilizan dos o más herramientas de la misma o di stinta clasificación.", "version": "Texto actualizado al 09.01.2026", "sha256": "0ebe95b3e05661b80f73c060d6e6ce8dd17621ce34af9277c688dd67e5d99830"}], "status": "published", "reviewBasis": "Revisión asistida por IA el15/11/2026 por encargo y autorización expresa del administrador. Se confirma el nuevo criterio en el corpus y se reemplaza el objetivo anterior. Antecedente: Complementaria: estrategia nacional de profesionalización, sin objetivo directo en el temario. Diferenciación: Q035 trata la herramienta obligatoria en CPI; aquí se clasifica la consulta general por herramientas de la misma clase. Excepciones y condiciones: No se inventa exigencia de combinar escritura y reuniones; el caso define dos herramientas distintas. Objetivo: Clasificar consulta avanzada con dos herramientas de la misma clasificación.. Evidencia: art. 49, chunk 57. Sin certificación oficial OECE ni revisión humana independiente; se conserva el corte documental declarado.", "confirmReview": true}, "estadoAnterior": "draft"}, {"numero": "Q039", "id": "457d76cb-02e0-43e7-bcc0-0b24ad5a8b9f", "decision": "approve", "motivo": "Se confirma el nuevo criterio en el corpus y se reemplaza el objetivo anterior. Antecedente: Complementaria: componentes de profesionalización y certificación, distintos de perfiles de evaluadores. Diferenciación: No repite la selección de fuente de Q116 ni la clasificación de consultas: se decide la compatibilidad complementaria de métodos. Excepciones y condiciones: Se usa exclusivamente 50.2, no el 50.3 incorporado sujeto a nota de entrada en vigor.", "objetivo": "Complementar herramientas de consulta con indagación histórica.", "evidencia": [{"chunkId": "b0c4df12-e98f-48a8-821c-196bc315d20a", "chunk_index": 58, "article": "50", "quote": "50.2. De manera complementaria a las herramientas señaladas, la DEC puede realizar una indagación de conformidad con el artículo 48."}], "input": {"id": "457d76cb-02e0-43e7-bcc0-0b24ad5a8b9f", "revision": 2, "prompt": "La DEC realizó reuniones con proveedores como herramientas de consulta y necesita contrastar resultados con información histórica mediante indagación. ¿Puede combinar estas actuaciones según el numeral 50.2?", "options": [{"id": "A", "text": "Sí; puede realizar indagación del artículo 48 como complemento de las herramientas de consulta."}, {"id": "B", "text": "No, consulta e indagación son excluyentes en la misma estrategia."}, {"id": "C", "text": "Solo si anula las reuniones y reinicia toda la interacción."}, {"id": "D", "text": "Solo después de declarar desierto un procedimiento."}], "correctOption": "A", "explanation": "El numeral 50.2 permite a la DEC realizar indagación conforme al artículo 48 de manera complementaria a las herramientas de consulta al mercado. Puede contrastar las reuniones con información histórica sin exigir una declaratoria de desierto ni invalidar las herramientas utilizadas.", "regime": "32069", "topic": "Requerimiento, estrategia y mercado", "competency": "Actuaciones preparatorias", "difficulty": "intermediate", "curriculumVersion": "oece-2025-04-25", "competencyCode": "1", "subcompetencyCode": "1.2", "cognitiveLevel": "apply", "optionRationales": {"A": "La DEC puede complementar las herramientas de consulta con indagación conforme al artículo 48.", "B": "El numeral 50.2 permite expresamente indagación complementaria y no establece exclusión mutua.", "C": "No se exige anular las herramientas utilizadas para complementarlas con indagación.", "D": "La declaratoria de desierto no es condición para complementar la consulta con indagación."}, "reviewChecks": {"unambiguous": true, "distractors": true, "conditions": true, "exceptions": true, "sources": true}, "sourceCutoff": "2026-10-29", "origin": "IA:gemini:gemini-2.5-flash:lote:89e558f0-10ed-49e1-acb2-bbdb5486d65e", "sources": [{"documentId": "8371bce1-f773-4ad8-8efa-1266276ae4ec", "chunkId": "b0c4df12-e98f-48a8-821c-196bc315d20a", "title": "Reglamento de la Ley N.° 32069 — texto actualizado al 09.01.2026", "article": "50", "pageStart": 27, "pageEnd": 28, "quote": "50.2. De manera complementaria a las herramientas señaladas, la DEC puede realizar una indagación de conformidad con el artículo 48.", "version": "Texto actualizado al 09.01.2026", "sha256": "0ebe95b3e05661b80f73c060d6e6ce8dd17621ce34af9277c688dd67e5d99830"}], "status": "published", "reviewBasis": "Revisión asistida por IA el15/11/2026 por encargo y autorización expresa del administrador. Se confirma el nuevo criterio en el corpus y se reemplaza el objetivo anterior. Antecedente: Complementaria: componentes de profesionalización y certificación, distintos de perfiles de evaluadores. Diferenciación: No repite la selección de fuente de Q116 ni la clasificación de consultas: se decide la compatibilidad complementaria de métodos. Excepciones y condiciones: Se usa exclusivamente 50.2, no el 50.3 incorporado sujeto a nota de entrada en vigor. Objetivo: Complementar herramientas de consulta con indagación histórica.. Evidencia: art. 50, chunk 58. Sin certificación oficial OECE ni revisión humana independiente; se conserva el corte documental declarado.", "confirmReview": true}, "estadoAnterior": "draft"}, {"numero": "Q040", "id": "fe84bea1-cd5c-44ad-9190-72403c5842c9", "decision": "approve", "motivo": "Se confirma el nuevo criterio en el corpus y se reemplaza el objetivo anterior. Antecedente: Complementaria: capacitación de defensa y control, sin actuación operativa del comprador evaluada. Diferenciación: Q017 y Q028 tratan inclusión en CMN; aquí se exige el soporte documental de una excepción al fraccionamiento. Excepciones y condiciones: Se evalúa la acreditación de una excepción específica; no se otorga autorización general para dividir compras.", "objetivo": "Acreditar documentalmente la excepción al fraccionamiento por razones presupuestales.", "evidencia": [{"chunkId": "fbff2c4f-98f7-4c03-837c-6c9f28d064b4", "chunk_index": 52, "article": "45", "quote": "45.2. No constituye fraccionamiento conforme a lo dispuesto en el numeral 50.2 del artículo 50 de la Ley, lo siguiente: a) Por razones presupuestales: se acredita mediante informe de la oficina de planeamiento y presupuesto de la entidad contratante o la que haga sus veces."}], "input": {"id": "fe84bea1-cd5c-44ad-9190-72403c5842c9", "revision": 2, "prompt": "En la planificación de una compra se invoca la excepción al fraccionamiento por razones presupuestales. Solo hay una nota del área usuaria sobre insuficiencia de recursos. ¿Qué respaldo específico falta para acreditar esa causal según el literal 45.2.a?", "options": [{"id": "A", "text": "Una carta del proveedor aceptando entregas en varios periodos."}, {"id": "B", "text": "Un informe de la oficina de planeamiento y presupuesto o la que haga sus veces."}, {"id": "C", "text": "Un informe de un jurado acerca de la calidad del bien."}, {"id": "D", "text": "Una declaración de la DEC que sustituya el informe del órgano presupuestal."}], "correctOption": "B", "explanation": "El literal 45.2.a exige acreditar las razones presupuestales mediante informe de la oficina de planeamiento y presupuesto o la que haga sus veces. Una nota del área usuaria no satisface ese respaldo específico. Identificar el documento faltante no valida por sí solo toda división de compras.", "regime": "32069", "topic": "Requerimiento, estrategia y mercado", "competency": "Actuaciones preparatorias", "difficulty": "intermediate", "curriculumVersion": "oece-2025-04-25", "competencyCode": "1", "subcompetencyCode": "1.2", "cognitiveLevel": "apply", "optionRationales": {"A": "La aceptación comercial del proveedor no acredita la causal presupuestal en la forma exigida.", "B": "El literal 45.2.a exige informe del órgano de planeamiento y presupuesto o quien haga sus veces.", "C": "Una opinión técnica sobre calidad no sustituye el informe presupuestal requerido para esta causal.", "D": "La declaración de la DEC no reemplaza el informe del órgano competente establecido por la norma."}, "reviewChecks": {"unambiguous": true, "distractors": true, "conditions": true, "exceptions": true, "sources": true}, "sourceCutoff": "2026-10-29", "origin": "IA:gemini:gemini-2.5-flash:lote:89e558f0-10ed-49e1-acb2-bbdb5486d65e", "sources": [{"documentId": "8371bce1-f773-4ad8-8efa-1266276ae4ec", "chunkId": "fbff2c4f-98f7-4c03-837c-6c9f28d064b4", "title": "Reglamento de la Ley N.° 32069 — texto actualizado al 09.01.2026", "article": "45", "pageStart": 25, "pageEnd": 25, "quote": "45.2. No constituye fraccionamiento conforme a lo dispuesto en el numeral 50.2 del artículo 50 de la Ley, lo siguiente: a) Por razones presupuestales: se acredita mediante informe de la oficina de planeamiento y presupuesto de la entidad contratante o la que haga sus veces.", "version": "Texto actualizado al 09.01.2026", "sha256": "0ebe95b3e05661b80f73c060d6e6ce8dd17621ce34af9277c688dd67e5d99830"}], "status": "published", "reviewBasis": "Revisión asistida por IA el15/11/2026 por encargo y autorización expresa del administrador. Se confirma el nuevo criterio en el corpus y se reemplaza el objetivo anterior. Antecedente: Complementaria: capacitación de defensa y control, sin actuación operativa del comprador evaluada. Diferenciación: Q017 y Q028 tratan inclusión en CMN; aquí se exige el soporte documental de una excepción al fraccionamiento. Excepciones y condiciones: Se evalúa la acreditación de una excepción específica; no se otorga autorización general para dividir compras. Objetivo: Acreditar documentalmente la excepción al fraccionamiento por razones presupuestales.. Evidencia: art. 45, chunk 52. Sin certificación oficial OECE ni revisión humana independiente; se conserva el corte documental declarado.", "confirmReview": true}, "estadoAnterior": "draft"}, {"numero": "Q046", "id": "8c5a4a81-a12f-4795-b1b4-9bc88c92c15a", "decision": "approve", "motivo": "Se confirma el nuevo criterio en el corpus y se reemplaza el objetivo anterior. Antecedente: Complementaria: modificación del plan de supervisión del OECE; no es modificación del PAC. Diferenciación: Difiere del control presupuestal anterior: examina la cronología de otro supuesto exceptuado, sin equivalencia con los objetivos publicados. Excepciones y condiciones: No se presume imputabilidad ni se declara infracción automática: se concluye que esta excepción no supera el requisito temporal.", "objetivo": "Contrastar la cronología del hecho generador de una necesidad imprevisible adicional.", "evidencia": [{"chunkId": "fbff2c4f-98f7-4c03-837c-6c9f28d064b4", "chunk_index": 52, "article": "45", "quote": "b) Producto de una necesidad imprevisible adicional a la programada generada por un evento no atribuible a la entidad contratante: la necesidad y su imprevisibilidad son debidamente sustentadas por el área usuaria. La DEC verifica; (i) las magnitudes progr amadas del ítem materia del objeto contractual en el CMN, incluyendo modificatorias y, (ii) que la fecha del hecho generador de la necesidad sea posterior al primer requerimiento por objeto contractual idéntico."}], "input": {"id": "8c5a4a81-a12f-4795-b1b4-9bc88c92c15a", "revision": 2, "prompt": "El área usuaria sustenta una necesidad adicional como imprevisible. La DEC verifica las magnitudes del ítem en el CMN y sus modificatorias, pero constata que el hecho generador ocurrió antes del primer requerimiento de objeto idéntico. ¿Cumple la comprobación temporal del literal 45.2.b?", "options": [{"id": "A", "text": "Sí, basta que la compra adicional se tramite después del primer requerimiento."}, {"id": "B", "text": "Sí, si la cuantía del nuevo requerimiento es menor que la del primero."}, {"id": "C", "text": "No; el hecho generador debe ser posterior al primer requerimiento de objeto contractual idéntico."}, {"id": "D", "text": "No, porque toda necesidad adicional constituye fraccionamiento sin excepciones."}], "correctOption": "C", "explanation": "El literal 45.2.b prevé la necesidad imprevisible adicional generada por evento no atribuible a la entidad, sustentada por el área usuaria. La DEC verifica magnitudes programadas y que el hecho generador sea posterior al primer requerimiento de objeto idéntico. El caso incumple esta última comprobación.", "regime": "32069", "topic": "Requerimiento, estrategia y mercado", "competency": "Actuaciones preparatorias", "difficulty": "intermediate", "curriculumVersion": "oece-2025-04-25", "competencyCode": "1", "subcompetencyCode": "1.2", "cognitiveLevel": "apply", "optionRationales": {"A": "La norma compara el momento del hecho generador y no solo la fecha de trámite de la compra adicional.", "B": "La menor cuantía no sustituye la condición temporal expresa del literal 45.2.b.", "C": "La anterioridad del hecho generador incumple la comprobación cronológica exigida por esta excepción.", "D": "La norma sí contempla una excepción con sustento y verificaciones para necesidades adicionales imprevisibles."}, "reviewChecks": {"unambiguous": true, "distractors": true, "conditions": true, "exceptions": true, "sources": true}, "sourceCutoff": "2026-10-29", "origin": "IA:gemini:gemini-2.5-flash:lote:56314e2e-9daa-4059-a8eb-2d58767529b5", "sources": [{"documentId": "8371bce1-f773-4ad8-8efa-1266276ae4ec", "chunkId": "fbff2c4f-98f7-4c03-837c-6c9f28d064b4", "title": "Reglamento de la Ley N.° 32069 — texto actualizado al 09.01.2026", "article": "45", "pageStart": 25, "pageEnd": 25, "quote": "b) Producto de una necesidad imprevisible adicional a la programada generada por un evento no atribuible a la entidad contratante: la necesidad y su imprevisibilidad son debidamente sustentadas por el área usuaria. La DEC verifica; (i) las magnitudes progr amadas del ítem materia del objeto contractual en el CMN, incluyendo modificatorias y, (ii) que la fecha del hecho generador de la necesidad sea posterior al primer requerimiento por objeto contractual idéntico.", "version": "Texto actualizado al 09.01.2026", "sha256": "0ebe95b3e05661b80f73c060d6e6ce8dd17621ce34af9277c688dd67e5d99830"}], "status": "published", "reviewBasis": "Revisión asistida por IA el15/11/2026 por encargo y autorización expresa del administrador. Se confirma el nuevo criterio en el corpus y se reemplaza el objetivo anterior. Antecedente: Complementaria: modificación del plan de supervisión del OECE; no es modificación del PAC. Diferenciación: Difiere del control presupuestal anterior: examina la cronología de otro supuesto exceptuado, sin equivalencia con los objetivos publicados. Excepciones y condiciones: No se presume imputabilidad ni se declara infracción automática: se concluye que esta excepción no supera el requisito temporal. Objetivo: Contrastar la cronología del hecho generador de una necesidad imprevisible adicional.. Evidencia: art. 45, chunk 52. Sin certificación oficial OECE ni revisión humana independiente; se conserva el corte documental declarado.", "confirmReview": true}, "estadoAnterior": "draft"}, {"numero": "Q047", "id": "0003dc87-ad64-4ea0-9461-4a35ee88b25e", "decision": "approve", "motivo": "Se confirma el nuevo criterio en el corpus y se reemplaza el objetivo anterior. Antecedente: Complementaria: gestión del plan ministerial de homologación; no es modificación del PAC. Diferenciación: Q085 controla el umbral de cada ítem; este objetivo controla la justificación comparativa del agrupamiento. Excepciones y condiciones: No se afirma que agrupar sea siempre mejor; se exige justificar su mayor eficiencia. Se utiliza el 52.2 sin mezclar versiones del 52.1.b.", "objetivo": "Sustentar en la estrategia la eficiencia del agrupamiento frente a contrataciones separadas.", "evidencia": [{"chunkId": "177b052b-4299-4ac1-99f2-ad583387f8b7", "chunk_index": 61, "article": "52", "quote": "52.2. La DEC sustenta en la estrategia de contratación que el agrupamiento de prestaciones resulta más eficiente que efectuar contrataciones separadas."}], "input": {"id": "0003dc87-ad64-4ea0-9461-4a35ee88b25e", "revision": 2, "prompt": "La DEC propone agrupar prestaciones porque le parece más cómodo tramitarlas juntas, pero la estrategia no compara esa solución con contrataciones separadas. ¿Qué debe incorporar para cumplir el numeral 52.2?", "options": [{"id": "A", "text": "Solo la afirmación de que el proveedor prefiere vender las prestaciones juntas."}, {"id": "B", "text": "Únicamente la suma de precios, sin analizar la eficiencia del agrupamiento."}, {"id": "C", "text": "La autorización del proveedor de mayor tamaño para utilizar el agrupamiento."}, {"id": "D", "text": "El sustento en la estrategia de que agrupar resulta más eficiente que contratar por separado."}], "correctOption": "D", "explanation": "El numeral 52.2 exige que la DEC sustente en la estrategia que agrupar prestaciones resulta más eficiente que efectuar contrataciones separadas. La comodidad alegada sin ese sustento no cumple el deber de justificación comparativa.", "regime": "32069", "topic": "Requerimiento, estrategia y mercado", "competency": "Actuaciones preparatorias", "difficulty": "intermediate", "curriculumVersion": "oece-2025-04-25", "competencyCode": "1", "subcompetencyCode": "1.2", "cognitiveLevel": "apply", "optionRationales": {"A": "La preferencia comercial del proveedor no sustituye la justificación de eficiencia de la entidad.", "B": "La suma de precios aislada no demuestra que el agrupamiento sea más eficiente que contratar separadamente.", "C": "La norma no asigna al proveedor la autorización del agrupamiento ni lo exime de sustento.", "D": "El numeral 52.2 exige a la DEC sustentar esa mayor eficiencia en la estrategia de contratación."}, "reviewChecks": {"unambiguous": true, "distractors": true, "conditions": true, "exceptions": true, "sources": true}, "sourceCutoff": "2026-10-29", "origin": "IA:gemini:gemini-2.5-flash:lote:56314e2e-9daa-4059-a8eb-2d58767529b5", "sources": [{"documentId": "8371bce1-f773-4ad8-8efa-1266276ae4ec", "chunkId": "177b052b-4299-4ac1-99f2-ad583387f8b7", "title": "Reglamento de la Ley N.° 32069 — texto actualizado al 09.01.2026", "article": "52", "pageStart": 29, "pageEnd": 29, "quote": "52.2. La DEC sustenta en la estrategia de contratación que el agrupamiento de prestaciones resulta más eficiente que efectuar contrataciones separadas.", "version": "Texto actualizado al 09.01.2026", "sha256": "0ebe95b3e05661b80f73c060d6e6ce8dd17621ce34af9277c688dd67e5d99830"}], "status": "published", "reviewBasis": "Revisión asistida por IA el15/11/2026 por encargo y autorización expresa del administrador. Se confirma el nuevo criterio en el corpus y se reemplaza el objetivo anterior. Antecedente: Complementaria: gestión del plan ministerial de homologación; no es modificación del PAC. Diferenciación: Q085 controla el umbral de cada ítem; este objetivo controla la justificación comparativa del agrupamiento. Excepciones y condiciones: No se afirma que agrupar sea siempre mejor; se exige justificar su mayor eficiencia. Se utiliza el 52.2 sin mezclar versiones del 52.1.b. Objetivo: Sustentar en la estrategia la eficiencia del agrupamiento frente a contrataciones separadas.. Evidencia: art. 52, chunk 61. Sin certificación oficial OECE ni revisión humana independiente; se conserva el corte documental declarado.", "confirmReview": true}, "estadoAnterior": "draft"}, {"numero": "Q048", "id": "ee48d7dc-89e2-4fa8-bdbf-c184c111f472", "decision": "approve", "motivo": "Se confirma el nuevo criterio en el corpus y se reemplaza el objetivo anterior. Antecedente: Complementaria: publicación del plan ministerial de homologación, sin registro preparatorio de una contratación concreta. Diferenciación: El cálculo integral de conceptos de cuantía no figura entre los objetivos preparatorios publicados; no se limita a cambiar cifras de un caso previo. Excepciones y condiciones: El caso evita doble cómputo y no inventa una tasa tributaria: el tributo es un importe dado. No se usa el 53.3 modificado.", "objetivo": "Calcular cuantía incluyendo todos los conceptos aplicables sin doble cómputo.", "evidencia": [{"chunkId": "69804433-840e-47aa-a1d4-f7bad02b98c7", "chunk_index": 62, "article": "53", "quote": "53.2. La cuantía de la contratación incluye todos los conceptos que sean aplicables al bien, servicio u obra a contratar."}], "input": {"id": "ee48d7dc-89e2-4fa8-bdbf-c184c111f472", "revision": 2, "prompt": "El precio neto de un bien es S/100 000; el transporte cuesta S/5 000, la instalación S/10 000 y los tributos aplicables S/20 000. Son conceptos distintos, necesarios y no incluidos entre sí. Según el numeral 53.2, ¿qué cuantía corresponde?", "options": [{"id": "A", "text": "S/135 000, al incluir todos los conceptos aplicables indicados."}, {"id": "B", "text": "S/100 000, porque solo cuenta el precio neto del bien."}, {"id": "C", "text": "S/115 000, porque deben excluirse los tributos aplicables."}, {"id": "D", "text": "S/120 000, porque transporte e instalación son externos a la compra."}], "correctOption": "A", "explanation": "El numeral 53.2 establece que la cuantía incluye todos los conceptos aplicables al bien, servicio u obra. Como los cuatro importes son distintos, necesarios y no están incluidos entre sí, corresponde sumar S/100 000 + S/5 000 + S/10 000 + S/20 000 = S/135 000.", "regime": "32069", "topic": "Requerimiento, estrategia y mercado", "competency": "Actuaciones preparatorias", "difficulty": "intermediate", "curriculumVersion": "oece-2025-04-25", "competencyCode": "1", "subcompetencyCode": "1.2", "cognitiveLevel": "apply", "optionRationales": {"A": "La suma de 100 000, 5 000, 10 000 y 20 000 da 135 000 e incorpora todos los conceptos aplicables.", "B": "Excluir transporte, instalación y tributos omite conceptos aplicables definidos en el supuesto.", "C": "Los tributos aplicables forman parte de los conceptos de la contratación y no deben excluirse.", "D": "El supuesto identifica transporte e instalación como necesarios y sin duplicación de importes."}, "reviewChecks": {"unambiguous": true, "distractors": true, "conditions": true, "exceptions": true, "sources": true}, "sourceCutoff": "2026-10-29", "origin": "IA:gemini:gemini-2.5-flash:lote:56314e2e-9daa-4059-a8eb-2d58767529b5", "sources": [{"documentId": "8371bce1-f773-4ad8-8efa-1266276ae4ec", "chunkId": "69804433-840e-47aa-a1d4-f7bad02b98c7", "title": "Reglamento de la Ley N.° 32069 — texto actualizado al 09.01.2026", "article": "53", "pageStart": 29, "pageEnd": 30, "quote": "53.2. La cuantía de la contratación incluye todos los conceptos que sean aplicables al bien, servicio u obra a contratar.", "version": "Texto actualizado al 09.01.2026", "sha256": "0ebe95b3e05661b80f73c060d6e6ce8dd17621ce34af9277c688dd67e5d99830"}], "status": "published", "reviewBasis": "Revisión asistida por IA el15/11/2026 por encargo y autorización expresa del administrador. Se confirma el nuevo criterio en el corpus y se reemplaza el objetivo anterior. Antecedente: Complementaria: publicación del plan ministerial de homologación, sin registro preparatorio de una contratación concreta. Diferenciación: El cálculo integral de conceptos de cuantía no figura entre los objetivos preparatorios publicados; no se limita a cambiar cifras de un caso previo. Excepciones y condiciones: El caso evita doble cómputo y no inventa una tasa tributaria: el tributo es un importe dado. No se usa el 53.3 modificado. Objetivo: Calcular cuantía incluyendo todos los conceptos aplicables sin doble cómputo.. Evidencia: art. 53, chunk 62. Sin certificación oficial OECE ni revisión humana independiente; se conserva el corte documental declarado.", "confirmReview": true}, "estadoAnterior": "draft"}, {"numero": "Q049", "id": "7be818fe-ae5b-4b76-b5a3-c7d2317d6aef", "decision": "approve", "motivo": "Se confirma el nuevo criterio en el corpus y se reemplaza el objetivo anterior. Antecedente: Complementaria: horizonte del plan ministerial de homologación; no equivale al PAC ni al CMN. Diferenciación: Q016 trata requerimiento final y Q014 disponibilidad del expediente; aquí se subsana la falta de formalización del análisis de estrategia. Excepciones y condiciones: La participación de evaluadores es potestativa; no se exige una opinión obligatoria como condición del documento. No se usa el 46.1.j modificado ni el literal incorporado.", "objetivo": "Formalizar el análisis de estrategia e incorporarlo al expediente.", "evidencia": [{"chunkId": "10205b1d-7271-4eed-b1da-6b0b6ed41f8a", "chunk_index": 54, "article": "46", "quote": "46.2. El análisis de la estrategia de contratación que realice la DEC consta en un documento, conforme al formato aprobado por la DGA, y forma parte del expediente de contratación, pudiendo requerir información al área usuaria para su sustento. Asimismo, l a DEC puede solicitar la participación de los evaluadores para elaborar la estrategia de contratación, conforme lo dispuesto en el numeral 56.3 del artículo 56."}], "input": {"id": "7be818fe-ae5b-4b76-b5a3-c7d2317d6aef", "revision": 2, "prompt": "La DEC analizó la estrategia en reuniones y conserva apuntes informales, pero carece de un documento conforme al formato aprobado por la DGA. El expediente contiene solo el requerimiento y las cotizaciones. ¿Qué debe completar según el numeral 46.2?", "options": [{"id": "A", "text": "Esperar a la adjudicación para decidir si documenta la estrategia."}, {"id": "B", "text": "Documentar el análisis conforme al formato aprobado por la DGA e incorporarlo al expediente."}, {"id": "C", "text": "Sustituir el documento de estrategia por una grabación de reuniones con proveedores."}, {"id": "D", "text": "Considerar suficientes las cotizaciones y dejar verbal el análisis de estrategia."}], "correctOption": "B", "explanation": "El numeral 46.2 exige que el análisis de estrategia realizado por la DEC conste en un documento conforme al formato aprobado por la DGA y forme parte del expediente. Permite requerir información al área usuaria para sustentarlo. Los apuntes y las cotizaciones no reemplazan esa formalización.", "regime": "32069", "topic": "Expediente de contratación", "competency": "Actuaciones preparatorias", "difficulty": "intermediate", "curriculumVersion": "oece-2025-04-25", "competencyCode": "1", "subcompetencyCode": "1.1", "cognitiveLevel": "apply", "optionRationales": {"A": "La formalización de la estrategia preparatoria no se posterga hasta la adjudicación.", "B": "El análisis debe constar en documento conforme al formato aprobado y formar parte del expediente.", "C": "La grabación no sustituye por sí sola el documento exigido conforme al formato aprobado por la DGA.", "D": "Las cotizaciones son posibles insumos, pero no sustituyen el documento que recoge el análisis de estrategia."}, "reviewChecks": {"unambiguous": true, "distractors": true, "conditions": true, "exceptions": true, "sources": true}, "sourceCutoff": "2026-10-29", "origin": "IA:gemini:gemini-2.5-flash:lote:56314e2e-9daa-4059-a8eb-2d58767529b5", "sources": [{"documentId": "8371bce1-f773-4ad8-8efa-1266276ae4ec", "chunkId": "10205b1d-7271-4eed-b1da-6b0b6ed41f8a", "title": "Reglamento de la Ley N.° 32069 — texto actualizado al 09.01.2026", "article": "46", "pageStart": 25, "pageEnd": 27, "quote": "46.2. El análisis de la estrategia de contratación que realice la DEC consta en un documento, conforme al formato aprobado por la DGA, y forma parte del expediente de contratación, pudiendo requerir información al área usuaria para su sustento. Asimismo, l a DEC puede solicitar la participación de los evaluadores para elaborar la estrategia de contratación, conforme lo dispuesto en el numeral 56.3 del artículo 56.", "version": "Texto actualizado al 09.01.2026", "sha256": "0ebe95b3e05661b80f73c060d6e6ce8dd17621ce34af9277c688dd67e5d99830"}], "status": "published", "reviewBasis": "Revisión asistida por IA el15/11/2026 por encargo y autorización expresa del administrador. Se confirma el nuevo criterio en el corpus y se reemplaza el objetivo anterior. Antecedente: Complementaria: horizonte del plan ministerial de homologación; no equivale al PAC ni al CMN. Diferenciación: Q016 trata requerimiento final y Q014 disponibilidad del expediente; aquí se subsana la falta de formalización del análisis de estrategia. Excepciones y condiciones: La participación de evaluadores es potestativa; no se exige una opinión obligatoria como condición del documento. No se usa el 46.1.j modificado ni el literal incorporado. Objetivo: Formalizar el análisis de estrategia e incorporarlo al expediente.. Evidencia: art. 46, chunk 54. Sin certificación oficial OECE ni revisión humana independiente; se conserva el corte documental declarado.", "confirmReview": true}, "estadoAnterior": "draft"}, {"numero": "Q050", "id": "249a30f1-6f46-4697-b885-de3ed1ae434e", "decision": "approve", "motivo": "Se confirma el nuevo criterio en el corpus y se reemplaza el objetivo anterior. Antecedente: Duplicada cercana de Q049: mismo horizonte y metas por ejercicio; también complementaria. Diferenciación: Q092 identifica la autoridad que designa; aquí se comprueba la elegibilidad cuantitativa del perfil propuesto. Excepciones y condiciones: Se limita a expertos del jurado y a esos dos mínimos; no traslada automáticamente las cifras a expertos del comité.", "objetivo": "Comprobar mínimos concurrentes de experiencia general y especializada de experto del jurado.", "evidencia": [{"chunkId": "83949553-413b-4ae9-95ec-a29347ed89f0", "chunk_index": 66, "article": "57", "quote": "57.2. En el caso del jurado, los expertos cuentan con no menos de ocho años de experiencia general y cinco años de experiencia en la especialidad correspondiente al objeto de la convocatoria."}], "input": {"id": "249a30f1-6f46-4697-b885-de3ed1ae434e", "revision": 2, "prompt": "Para integrar un jurado se propone una experta con diez años de experiencia general y cuatro en la especialidad del objeto. Se examinan únicamente los mínimos del numeral 57.2. ¿Cumple ambos?", "options": [{"id": "A", "text": "Sí; el exceso de experiencia general compensa el déficit de especialidad."}, {"id": "B", "text": "Sí; el jurado exige solo tres años de experiencia en la especialidad."}, {"id": "C", "text": "No; cumple el mínimo general, pero no los cinco años mínimos en la especialidad."}, {"id": "D", "text": "No; se requieren doce años de experiencia general."}], "correctOption": "C", "explanation": "El numeral 57.2 exige a los expertos del jurado no menos de ocho años de experiencia general y cinco de experiencia en la especialidad del objeto. La candidata supera el primer mínimo, pero no el segundo. No cumple ambos y la experiencia general adicional no compensa el déficit especializado.", "regime": "32069", "topic": "Tipos y perfiles de evaluadores", "competency": "Actuaciones preparatorias", "difficulty": "intermediate", "curriculumVersion": "oece-2025-04-25", "competencyCode": "1", "subcompetencyCode": "1.3", "cognitiveLevel": "apply", "optionRationales": {"A": "Los mínimos son concurrentes y el numeral no establece compensación entre experiencia general y especializada.", "B": "El mínimo de especialidad del jurado es cinco años y no tres como propone la alternativa.", "C": "Diez años superan el mínimo general de ocho; cuatro no alcanzan el mínimo especializado de cinco.", "D": "El mínimo general es ocho años; exigir doce añade una condición no contenida en el numeral."}, "reviewChecks": {"unambiguous": true, "distractors": true, "conditions": true, "exceptions": true, "sources": true}, "sourceCutoff": "2026-10-29", "origin": "IA:gemini:gemini-2.5-flash:lote:8a600137-f774-413d-8333-f4dfd4291b37", "sources": [{"documentId": "8371bce1-f773-4ad8-8efa-1266276ae4ec", "chunkId": "83949553-413b-4ae9-95ec-a29347ed89f0", "title": "Reglamento de la Ley N.° 32069 — texto actualizado al 09.01.2026", "article": "57", "pageStart": 32, "pageEnd": 32, "quote": "57.2. En el caso del jurado, los expertos cuentan con no menos de ocho años de experiencia general y cinco años de experiencia en la especialidad correspondiente al objeto de la convocatoria.", "version": "Texto actualizado al 09.01.2026", "sha256": "0ebe95b3e05661b80f73c060d6e6ce8dd17621ce34af9277c688dd67e5d99830"}], "status": "published", "reviewBasis": "Revisión asistida por IA el15/11/2026 por encargo y autorización expresa del administrador. Se confirma el nuevo criterio en el corpus y se reemplaza el objetivo anterior. Antecedente: Duplicada cercana de Q049: mismo horizonte y metas por ejercicio; también complementaria. Diferenciación: Q092 identifica la autoridad que designa; aquí se comprueba la elegibilidad cuantitativa del perfil propuesto. Excepciones y condiciones: Se limita a expertos del jurado y a esos dos mínimos; no traslada automáticamente las cifras a expertos del comité. Objetivo: Comprobar mínimos concurrentes de experiencia general y especializada de experto del jurado.. Evidencia: art. 57, chunk 66. Sin certificación oficial OECE ni revisión humana independiente; se conserva el corte documental declarado.", "confirmReview": true}, "estadoAnterior": "draft"}, {"numero": "Q052", "id": "aacd26ae-cd45-487e-b08d-073e766dd9e1", "decision": "approve", "motivo": "Se confirma el nuevo criterio en el corpus y se reemplaza el objetivo anterior. Antecedente: Complementaria: inclusión en plan ministerial de homologación, no inclusión de contrataciones en PAC. Diferenciación: Q057 trata medios alternativos por implementación pendiente y Q059 consultas a bases en selección; aquí se calcula la participación en difusión preparatoria. Excepciones y condiciones: El 51.2 no aparece modificado; se distingue del 51.3, cuyo plazo original de tres días fue reemplazado por seis en el corpus. El caso supone uso operativo de PLADICOP sin afirmar implementación general.", "objetivo": "Programar en PLADICOP el cierre mínimo de consultas de difusión del requerimiento.", "evidencia": [{"chunkId": "59c25e30-8138-44d3-900a-d0094fb64cdb", "chunk_index": 59, "article": "51", "quote": "51.2. La formulación de consultas y/o comentarios técnicos se realiza a través de la Pladicop en un plazo no menor de cinco días hábiles, contabilizados desde el día siguiente a la publicación de la difusión del requerimiento."}], "input": {"id": "aacd26ae-cd45-487e-b08d-073e766dd9e1", "revision": 2, "prompt": "El lunes se publica en PLADICOP la difusión del requerimiento. No hay feriados ni días no laborables en las dos semanas del caso. Para consultas y comentarios técnicos se concede exactamente el mínimo del numeral 51.2. ¿Qué día vence?", "options": [{"id": "A", "text": "El viernes de la misma semana de publicación."}, {"id": "B", "text": "El domingo de la misma semana de publicación."}, {"id": "C", "text": "El miércoles de la semana siguiente a la publicación."}, {"id": "D", "text": "El lunes de la semana siguiente a la publicación."}], "correctOption": "D", "explanation": "El numeral 51.2 fija un plazo no menor de cinco días hábiles contado desde el día siguiente a la publicación de la difusión. Publicado un lunes y sin feriados ni días no laborables, se cuentan martes, miércoles, jueves, viernes y el lunes siguiente. Se pide el mínimo exacto, sin negar que pueda concederse más tiempo.", "regime": "32069", "topic": "PLADICOP en actuaciones preparatorias", "competency": "Actuaciones preparatorias", "difficulty": "intermediate", "curriculumVersion": "oece-2025-04-25", "competencyCode": "1", "subcompetencyCode": "1.8", "cognitiveLevel": "apply", "optionRationales": {"A": "De martes a viernes transcurren solo cuatro días hábiles y no se completa el mínimo de cinco.", "B": "El domingo no completa cinco días hábiles, pues sábado y domingo no integran el cómputo hábil.", "C": "El miércoles siguiente excede el mínimo de cinco días hábiles solicitado expresamente.", "D": "Desde el martes: martes, miércoles, jueves, viernes y lunes completan cinco días hábiles."}, "reviewChecks": {"unambiguous": true, "distractors": true, "conditions": true, "exceptions": true, "sources": true}, "sourceCutoff": "2026-10-29", "origin": "IA:gemini:gemini-2.5-flash:lote:8a600137-f774-413d-8333-f4dfd4291b37", "sources": [{"documentId": "8371bce1-f773-4ad8-8efa-1266276ae4ec", "chunkId": "59c25e30-8138-44d3-900a-d0094fb64cdb", "title": "Reglamento de la Ley N.° 32069 — texto actualizado al 09.01.2026", "article": "51", "pageStart": 28, "pageEnd": 29, "quote": "51.2. La formulación de consultas y/o comentarios técnicos se realiza a través de la Pladicop en un plazo no menor de cinco días hábiles, contabilizados desde el día siguiente a la publicación de la difusión del requerimiento.", "version": "Texto actualizado al 09.01.2026", "sha256": "0ebe95b3e05661b80f73c060d6e6ce8dd17621ce34af9277c688dd67e5d99830"}], "status": "published", "reviewBasis": "Revisión asistida por IA el15/11/2026 por encargo y autorización expresa del administrador. Se confirma el nuevo criterio en el corpus y se reemplaza el objetivo anterior. Antecedente: Complementaria: inclusión en plan ministerial de homologación, no inclusión de contrataciones en PAC. Diferenciación: Q057 trata medios alternativos por implementación pendiente y Q059 consultas a bases en selección; aquí se calcula la participación en difusión preparatoria. Excepciones y condiciones: El 51.2 no aparece modificado; se distingue del 51.3, cuyo plazo original de tres días fue reemplazado por seis en el corpus. El caso supone uso operativo de PLADICOP sin afirmar implementación general. Objetivo: Programar en PLADICOP el cierre mínimo de consultas de difusión del requerimiento.. Evidencia: art. 51, chunk 59. Sin certificación oficial OECE ni revisión humana independiente; se conserva el corte documental declarado.", "confirmReview": true}, "estadoAnterior": "draft"}, {"numero": "Q053", "id": "6dcb29ae-c442-47a1-84e4-e0e4d34d8342", "decision": "approve", "motivo": "Se confirma el nuevo criterio en el corpus y se reemplaza el objetivo anterior. Antecedente: Complementaria: contenido del plan de supervisión OECE, distinto del expediente o PAC. Diferenciación: Q018 examina un impedimento por aprobación delegada del expediente; aquí se controla la declaración previa y su oportunidad. Excepciones y condiciones: Se separa el control previo de los deberes posteriores de informar y renunciar ante materialización; la declaración inicial no los elimina.", "objetivo": "Exigir declaración de ausencia de conflicto de intereses antes de la designación.", "evidencia": [{"chunkId": "068c4228-4356-4a38-a7b5-1865a955d8b9", "chunk_index": 65, "article": "56", "quote": "56.7. Los evaluadores están obligados a presentar previo a su designación una declaración jurada de no mantener conflicto de intereses en el proceso de contratación a evaluar y a informar oportunamente sobre la existencia de un posible conflicto de interés . Asimismo, deben renunciar en caso de materializarse el referido conflicto durante cualquier fase del proceso de contratación."}], "input": {"id": "6dcb29ae-c442-47a1-84e4-e0e4d34d8342", "revision": 2, "prompt": "La entidad prepara la designación de un evaluador. El candidato ofrece presentar su declaración jurada de no mantener conflicto de intereses recién al recibir las ofertas. ¿Qué corresponde según el numeral 56.7?", "options": [{"id": "A", "text": "Exigir la declaración antes de designarlo, sin perjuicio de informar posteriormente posibles conflictos."}, {"id": "B", "text": "Aceptar la entrega posterior si promete no favorecer a nadie."}, {"id": "C", "text": "Sustituir la declaración por su currículum profesional."}, {"id": "D", "text": "Solicitarla únicamente si un proveedor presenta denuncia."}], "correctOption": "A", "explanation": "El numeral 56.7 exige presentar la declaración jurada de no mantener conflicto de intereses antes de la designación. Además, obliga a informar oportunamente posibles conflictos y a renunciar si se materializan durante cualquier fase. Presentarla al recibir ofertas sería tardío para el deber previo.", "regime": "32069", "topic": "Actores de la contratación", "competency": "Actuaciones preparatorias", "difficulty": "intermediate", "curriculumVersion": "oece-2025-04-25", "competencyCode": "1", "subcompetencyCode": "1.7", "cognitiveLevel": "apply", "optionRationales": {"A": "La norma exige declaración previa e información oportuna de posibles conflictos que aparezcan.", "B": "La promesa de conducta futura no cambia la oportunidad previa a la designación exigida por la norma.", "C": "El currículum acredita trayectoria y no sustituye la declaración sobre conflictos en el proceso.", "D": "La obligación previa no está condicionada a una denuncia formulada por un proveedor."}, "reviewChecks": {"unambiguous": true, "distractors": true, "conditions": true, "exceptions": true, "sources": true}, "sourceCutoff": "2026-10-29", "origin": "IA:gemini:gemini-2.5-flash:lote:8a600137-f774-413d-8333-f4dfd4291b37", "sources": [{"documentId": "8371bce1-f773-4ad8-8efa-1266276ae4ec", "chunkId": "068c4228-4356-4a38-a7b5-1865a955d8b9", "title": "Reglamento de la Ley N.° 32069 — texto actualizado al 09.01.2026", "article": "56", "pageStart": 31, "pageEnd": 32, "quote": "56.7. Los evaluadores están obligados a presentar previo a su designación una declaración jurada de no mantener conflicto de intereses en el proceso de contratación a evaluar y a informar oportunamente sobre la existencia de un posible conflicto de interés . Asimismo, deben renunciar en caso de materializarse el referido conflicto durante cualquier fase del proceso de contratación.", "version": "Texto actualizado al 09.01.2026", "sha256": "0ebe95b3e05661b80f73c060d6e6ce8dd17621ce34af9277c688dd67e5d99830"}], "status": "published", "reviewBasis": "Revisión asistida por IA el15/11/2026 por encargo y autorización expresa del administrador. Se confirma el nuevo criterio en el corpus y se reemplaza el objetivo anterior. Antecedente: Complementaria: contenido del plan de supervisión OECE, distinto del expediente o PAC. Diferenciación: Q018 examina un impedimento por aprobación delegada del expediente; aquí se controla la declaración previa y su oportunidad. Excepciones y condiciones: Se separa el control previo de los deberes posteriores de informar y renunciar ante materialización; la declaración inicial no los elimina. Objetivo: Exigir declaración de ausencia de conflicto de intereses antes de la designación.. Evidencia: art. 56, chunk 65. Sin certificación oficial OECE ni revisión humana independiente; se conserva el corte documental declarado.", "confirmReview": true}, "estadoAnterior": "draft"}, {"numero": "Q056", "id": "e1b2128b-ee41-46c9-835d-f4b306c65024", "decision": "approve", "motivo": "Se confirma el nuevo criterio en el corpus y se reemplaza el objetivo anterior. Antecedente: Complementaria: registro de contratos menores en todas las fases hasta el último pago; no asignar cuota 1.8 solo por mencionar preparatorias. Diferenciación: Q103 y Q186 distribuyen funciones; este caso detecta una deficiencia de composición antes de designar el comité. Excepciones y condiciones: No se convierte el perfil técnico en experto de jurado ni se aplican al comité los mínimos numéricos del 57.2.", "objetivo": "Corregir composición de comité sin comprador público de la DEC.", "evidencia": [{"chunkId": "068c4228-4356-4a38-a7b5-1865a955d8b9", "chunk_index": 65, "article": "56", "quote": "56.1. Los procedimientos de selección competitivos se encuentran a cargo de evaluadores, conforme a los siguientes tipos: a) Oficial de compra: comprador público de la DEC. b) Comité: conformado por tres integrantes de los cuales al menos uno es comprador público de la DEC y uno es experto o profesional que cuente con conocimiento técnico y/o experiencia en el objeto de contratación. c) Jurado: conformado por tres o cinco expertos en el objeto de contratación."}], "input": {"id": "e1b2128b-ee41-46c9-835d-f4b306c65024", "revision": 1, "prompt": "Se propone un comité de tres profesionales con conocimiento técnico del objeto; ninguno es comprador público de la DEC. Se verifica solo la composición del literal 56.1.b, sin evaluar otros requisitos personales. ¿Qué corrección requiere?", "options": [{"id": "A", "text": "Mantenerlo porque tres especialistas sustituyen siempre la participación de la DEC."}, {"id": "B", "text": "Incorporar al menos un comprador público de la DEC, manteniendo tres integrantes y el componente técnico exigido."}, {"id": "C", "text": "Aumentarlo a cinco especialistas sin incorporar comprador público de la DEC."}, {"id": "D", "text": "Sustituir a todos por compradores públicos sin conocimiento técnico del objeto."}], "correctOption": "B", "explanation": "El literal 56.1.b prevé un comité de tres integrantes, con al menos un comprador público de la DEC y un experto o profesional con conocimiento técnico y/o experiencia en el objeto. Falta el comprador público de la DEC; la propuesta debe corregirse preservando el número y los perfiles exigidos.", "regime": "32069", "topic": "Tipos y perfiles de evaluadores", "competency": "Actuaciones preparatorias", "difficulty": "intermediate", "curriculumVersion": "oece-2025-04-25", "competencyCode": "1", "subcompetencyCode": "1.3", "cognitiveLevel": "apply", "optionRationales": {"A": "La especialidad técnica no elimina la presencia exigida de al menos un comprador público de la DEC.", "B": "El comité exige tres integrantes con presencia de comprador público de la DEC y del componente técnico indicado.", "C": "Cinco especialistas no satisfacen la composición de comité de tres ni subsanan la ausencia señalada.", "D": "La corrección debe preservar también el componente técnico y no exige excluir a todos los especialistas."}, "reviewChecks": {"unambiguous": true, "distractors": true, "conditions": true, "exceptions": true, "sources": true}, "sourceCutoff": "2026-10-29", "origin": "IA:gemini:gemini-2.5-flash:lote:b44a05f5-2db0-487b-8791-73c3cdb1cc0f", "sources": [{"documentId": "8371bce1-f773-4ad8-8efa-1266276ae4ec", "chunkId": "068c4228-4356-4a38-a7b5-1865a955d8b9", "title": "Reglamento de la Ley N.° 32069 — texto actualizado al 09.01.2026", "article": "56", "pageStart": 31, "pageEnd": 32, "quote": "56.1. Los procedimientos de selección competitivos se encuentran a cargo de evaluadores, conforme a los siguientes tipos: a) Oficial de compra: comprador público de la DEC. b) Comité: conformado por tres integrantes de los cuales al menos uno es comprador público de la DEC y uno es experto o profesional que cuente con conocimiento técnico y/o experiencia en el objeto de contratación. c) Jurado: conformado por tres o cinco expertos en el objeto de contratación.", "version": "Texto actualizado al 09.01.2026", "sha256": "0ebe95b3e05661b80f73c060d6e6ce8dd17621ce34af9277c688dd67e5d99830"}], "status": "published", "reviewBasis": "Revisión asistida por IA el15/11/2026 por encargo y autorización expresa del administrador. Se confirma el nuevo criterio en el corpus y se reemplaza el objetivo anterior. Antecedente: Complementaria: registro de contratos menores en todas las fases hasta el último pago; no asignar cuota 1.8 solo por mencionar preparatorias. Diferenciación: Q103 y Q186 distribuyen funciones; este caso detecta una deficiencia de composición antes de designar el comité. Excepciones y condiciones: No se convierte el perfil técnico en experto de jurado ni se aplican al comité los mínimos numéricos del 57.2. Objetivo: Corregir composición de comité sin comprador público de la DEC.. Evidencia: art. 56, chunk 65. Sin certificación oficial OECE ni revisión humana independiente; se conserva el corte documental declarado.", "confirmReview": true}, "estadoAnterior": "draft"}, {"numero": "Q058", "id": "1b968f44-4d5a-4eae-8d83-726d5a0cd72d", "decision": "approve", "motivo": "Se confirma el nuevo criterio en el corpus y se reemplaza el objetivo anterior. Antecedente: Duplicada cercana de Q056: mismo registro integral de contratos menores; no corresponde exclusivamente a 1.8. Diferenciación: Q042, Q070 y Q087 tratan cambios de factores de evaluación; aquí se subsana la omisión de contenido contractual mínimo de las bases. Excepciones y condiciones: El contenido concreto varía según tipo y modalidad, pero esa variación no permite suprimir la categoría mínima. No se usa el 55.2 original ni su modificación.", "objetivo": "Completar las bases que omiten condiciones de ejecución contractual.", "evidencia": [{"chunkId": "bd84aab5-120f-4768-a955-c6bf52c71d88", "chunk_index": 64, "article": "55", "quote": "55.3. El contenido de las bases depende del tipo y modalidad del procedimiento de selección, e incluyen como mínimo lo siguiente: el requerimiento, los documentos necesarios para la presentación de ofertas y las condiciones para la ejecución contractual. L as bases estándar se aprueban mediante directiva que emita la DGA, las cuales son de uso obligatorio por los evaluadores."}], "input": {"id": "1b968f44-4d5a-4eae-8d83-726d5a0cd72d", "revision": 1, "prompt": "El evaluador prepara bases con el requerimiento y los documentos para presentar ofertas, pero elimina todas las condiciones de ejecución contractual para acordarlas después con el ganador. Según el numeral 55.3, ¿qué corresponde?", "options": [{"id": "A", "text": "Aceptar la omisión porque esas condiciones no integran el contenido mínimo de bases."}, {"id": "B", "text": "Mantener la omisión si el requerimiento describe brevemente el objeto."}, {"id": "C", "text": "Incorporar las condiciones de ejecución contractual usando las bases estándar obligatorias aplicables."}, {"id": "D", "text": "Reemplazar las bases por una invitación comercial redactada por el proveedor."}], "correctOption": "C", "explanation": "El numeral 55.3 incluye como mínimo el requerimiento, los documentos necesarios para presentar ofertas y las condiciones de ejecución contractual. También establece el uso obligatorio de las bases estándar aprobadas por la DGA. No corresponde eliminar esas condiciones para pactarlas íntegramente después.", "regime": "32069", "topic": "Documentos estandarizados", "competency": "Actuaciones preparatorias", "difficulty": "intermediate", "curriculumVersion": "oece-2025-04-25", "competencyCode": "1", "subcompetencyCode": "1.4", "cognitiveLevel": "apply", "optionRationales": {"A": "Las condiciones de ejecución contractual sí integran el contenido mínimo previsto por el numeral 55.3.", "B": "Describir el objeto no permite eliminar íntegramente otra categoría del contenido mínimo normativo.", "C": "Las bases deben contener esa categoría mínima y elaborarse usando las bases estándar obligatorias.", "D": "Una invitación comercial del proveedor no sustituye las bases del procedimiento ni el uso de bases estándar."}, "reviewChecks": {"unambiguous": true, "distractors": true, "conditions": true, "exceptions": true, "sources": true}, "sourceCutoff": "2026-10-29", "origin": "IA:gemini:gemini-2.5-flash:lote:9a8e4de9-88c1-4d47-ae86-3a71f94ec187", "sources": [{"documentId": "8371bce1-f773-4ad8-8efa-1266276ae4ec", "chunkId": "bd84aab5-120f-4768-a955-c6bf52c71d88", "title": "Reglamento de la Ley N.° 32069 — texto actualizado al 09.01.2026", "article": "55", "pageStart": 30, "pageEnd": 31, "quote": "55.3. El contenido de las bases depende del tipo y modalidad del procedimiento de selección, e incluyen como mínimo lo siguiente: el requerimiento, los documentos necesarios para la presentación de ofertas y las condiciones para la ejecución contractual. L as bases estándar se aprueban mediante directiva que emita la DGA, las cuales son de uso obligatorio por los evaluadores.", "version": "Texto actualizado al 09.01.2026", "sha256": "0ebe95b3e05661b80f73c060d6e6ce8dd17621ce34af9277c688dd67e5d99830"}], "status": "published", "reviewBasis": "Revisión asistida por IA el15/11/2026 por encargo y autorización expresa del administrador. Se confirma el nuevo criterio en el corpus y se reemplaza el objetivo anterior. Antecedente: Duplicada cercana de Q056: mismo registro integral de contratos menores; no corresponde exclusivamente a 1.8. Diferenciación: Q042, Q070 y Q087 tratan cambios de factores de evaluación; aquí se subsana la omisión de contenido contractual mínimo de las bases. Excepciones y condiciones: El contenido concreto varía según tipo y modalidad, pero esa variación no permite suprimir la categoría mínima. No se usa el 55.2 original ni su modificación. Objetivo: Completar las bases que omiten condiciones de ejecución contractual.. Evidencia: art. 55, chunk 64. Sin certificación oficial OECE ni revisión humana independiente; se conserva el corte documental declarado.", "confirmReview": true}, "estadoAnterior": "draft"}, {"numero": "Q068", "id": "77cfcf76-b18a-471a-abe5-c18f371d235e", "decision": "approve", "motivo": "Se confirma el nuevo criterio en el corpus y se reemplaza el objetivo anterior. Antecedente: Duplicada cercana de Q020 tras corregir 101.1; la prohibición general de interacción era del texto anterior. Diferenciación: Difiere de Q035 y de la clasificación por número de herramientas: aquí se selecciona la herramienta idónea para información individual detallada. Excepciones y condiciones: Se elige herramienta por finalidad; no se dice que sea obligatoria para toda consulta ni suficiente para clasificarla como avanzada.", "objetivo": "Elegir reuniones individuales para obtener información detallada directamente de cada proveedor.", "evidencia": [{"chunkId": "b0c4df12-e98f-48a8-821c-196bc315d20a", "chunk_index": 58, "article": "50", "quote": "b.2 Uno a uno: se utiliza para obtener información detallada de una manera directa con el proveedor a través de reuniones individuales."}], "input": {"id": "77cfcf76-b18a-471a-abe5-c18f371d235e", "revision": 1, "prompt": "Para perfeccionar el requerimiento, la DEC necesita información detallada de las soluciones particulares de cada proveedor mediante entrevistas individuales. No busca exponer aspectos generales a toda la industria. ¿Qué herramienta del numeral 50.1 corresponde?", "options": [{"id": "A", "text": "Una reunión uno a muchos limitada a exponer el proyecto a varios proveedores."}, {"id": "B", "text": "La revisión exclusiva de contratos históricos sin contacto con proveedores."}, {"id": "C", "text": "Una solicitud escrita que excluya toda reunión individual."}, {"id": "D", "text": "Reuniones uno a uno para obtener información detallada directamente de cada proveedor."}], "correctOption": "D", "explanation": "El literal 50.1.b.2 define las reuniones uno a uno para obtener información detallada directamente con el proveedor mediante reuniones individuales. Responde al objetivo expresamente planteado. La utilidad de otras fuentes no las convierte en entrevistas individuales.", "regime": "32069", "topic": "Requerimiento, estrategia y mercado", "competency": "Actuaciones preparatorias", "difficulty": "intermediate", "curriculumVersion": "oece-2025-04-25", "competencyCode": "1", "subcompetencyCode": "1.2", "cognitiveLevel": "apply", "optionRationales": {"A": "La herramienta uno a muchos comunica aspectos clave a varios proveedores y no es la entrevista individual buscada.", "B": "La revisión histórica puede aportar datos, pero no satisface el objetivo de entrevistar individualmente a proveedores.", "C": "La solicitud escrita es otra herramienta y no corresponde a la modalidad individual de reunión del caso.", "D": "El literal 50.1.b.2 define esa herramienta para obtener información detallada mediante reuniones individuales."}, "reviewChecks": {"unambiguous": true, "distractors": true, "conditions": true, "exceptions": true, "sources": true}, "sourceCutoff": "2026-10-29", "origin": "IA:gemini:gemini-2.5-flash:lote:faa6eded-dd3d-4002-b853-ac9c3576b5bd", "sources": [{"documentId": "8371bce1-f773-4ad8-8efa-1266276ae4ec", "chunkId": "b0c4df12-e98f-48a8-821c-196bc315d20a", "title": "Reglamento de la Ley N.° 32069 — texto actualizado al 09.01.2026", "article": "50", "pageStart": 27, "pageEnd": 28, "quote": "b.2 Uno a uno: se utiliza para obtener información detallada de una manera directa con el proveedor a través de reuniones individuales.", "version": "Texto actualizado al 09.01.2026", "sha256": "0ebe95b3e05661b80f73c060d6e6ce8dd17621ce34af9277c688dd67e5d99830"}], "status": "published", "reviewBasis": "Revisión asistida por IA el15/11/2026 por encargo y autorización expresa del administrador. Se confirma el nuevo criterio en el corpus y se reemplaza el objetivo anterior. Antecedente: Duplicada cercana de Q020 tras corregir 101.1; la prohibición general de interacción era del texto anterior. Diferenciación: Difiere de Q035 y de la clasificación por número de herramientas: aquí se selecciona la herramienta idónea para información individual detallada. Excepciones y condiciones: Se elige herramienta por finalidad; no se dice que sea obligatoria para toda consulta ni suficiente para clasificarla como avanzada. Objetivo: Elegir reuniones individuales para obtener información detallada directamente de cada proveedor.. Evidencia: art. 50, chunk 58. Sin certificación oficial OECE ni revisión humana independiente; se conserva el corte documental declarado.", "confirmReview": true}, "estadoAnterior": "draft"}, {"numero": "Q071", "id": "94b8a5b0-c200-41c6-9d18-979d7c0d5ce8", "decision": "approve", "motivo": "Se confirma el nuevo criterio en el corpus y se reemplaza el objetivo anterior. Antecedente: Duplicada cercana de Q023 después de corregir 42.3 con el texto modificado; no corresponde a modificación del PAC. Se reemplaza fuente y regla anterior por 42.3 modificado del chunk 48. Diferenciación: Q083 enumera estandarización como variable de estrategia; aquí se aplica la consecuencia de detectar una ficha vigente sobre el contenido del requerimiento. Excepciones y condiciones: El supuesto declara cobertura y vigencia de la ficha como datos hipotéticos; no atribuye vigencia real a ninguna ficha ajena al corpus.", "objetivo": "Adecuar características y calificación del requerimiento a ficha de homologación vigente.", "evidencia": [{"chunkId": "88817114-d891-44f7-b8a0-802a9b1247a4", "chunk_index": 51, "article": "44", "quote": "44.9. La DEC verifica si el requerimiento se encuentra incluido en una ficha de homologación vigente o en una ficha técnica vigente. En dichos casos, el requerimiento recoge las características técnicas ya definidas, así como los requisitos de calificación contemplados en éstas o en los documentos de información complementaria, según corresponda."}], "input": {"id": "94b8a5b0-c200-41c6-9d18-979d7c0d5ce8", "revision": 1, "prompt": "La DEC comprueba que el requerimiento está comprendido en una ficha de homologación vigente con características técnicas y requisitos de calificación. El área usuaria propone ignorarla y mantener sus condiciones propias. Según el numeral 44.9, ¿qué corresponde?", "options": [{"id": "A", "text": "Recoger características técnicas definidas y requisitos de calificación de la ficha o documentación complementaria, según corresponda."}, {"id": "B", "text": "Recoger solo las características técnicas y excluir siempre los requisitos de calificación de la ficha."}, {"id": "C", "text": "Ignorar la ficha si el área usuaria considera superiores sus condiciones propias."}, {"id": "D", "text": "Aplicar la ficha únicamente después de otorgada la buena pro."}], "correctOption": "A", "explanation": "El numeral 44.9 exige verificar si el requerimiento está incluido en una ficha de homologación o ficha técnica vigente. En ese supuesto recoge las características técnicas definidas y los requisitos de calificación contemplados en ellas o en los documentos de información complementaria, según corresponda.", "regime": "32069", "topic": "Requerimiento, estrategia y mercado", "competency": "Actuaciones preparatorias", "difficulty": "intermediate", "curriculumVersion": "oece-2025-04-25", "competencyCode": "1", "subcompetencyCode": "1.2", "cognitiveLevel": "apply", "optionRationales": {"A": "La norma exige recoger ambos componentes de la ficha o de los documentos complementarios, según corresponda.", "B": "La adecuación no se limita a características técnicas; comprende requisitos de calificación previstos.", "C": "La preferencia del área usuaria no permite desconocer una ficha vigente que comprende el requerimiento.", "D": "La verificación y adecuación recaen en el requerimiento y no se postergan hasta después de adjudicar."}, "reviewChecks": {"unambiguous": true, "distractors": true, "conditions": true, "exceptions": true, "sources": true}, "sourceCutoff": "2026-10-29", "origin": "IA:gemini:gemini-2.5-flash:lote:3d3be616-8201-4a98-8709-9fa6e15e7d85", "sources": [{"documentId": "8371bce1-f773-4ad8-8efa-1266276ae4ec", "chunkId": "88817114-d891-44f7-b8a0-802a9b1247a4", "title": "Reglamento de la Ley N.° 32069 — texto actualizado al 09.01.2026", "article": "44", "pageStart": 24, "pageEnd": 25, "quote": "44.9. La DEC verifica si el requerimiento se encuentra incluido en una ficha de homologación vigente o en una ficha técnica vigente. En dichos casos, el requerimiento recoge las características técnicas ya definidas, así como los requisitos de calificación contemplados en éstas o en los documentos de información complementaria, según corresponda.", "version": "Texto actualizado al 09.01.2026", "sha256": "0ebe95b3e05661b80f73c060d6e6ce8dd17621ce34af9277c688dd67e5d99830"}], "status": "published", "reviewBasis": "Revisión asistida por IA el15/11/2026 por encargo y autorización expresa del administrador. Se confirma el nuevo criterio en el corpus y se reemplaza el objetivo anterior. Antecedente: Duplicada cercana de Q023 después de corregir 42.3 con el texto modificado; no corresponde a modificación del PAC. Se reemplaza fuente y regla anterior por 42.3 modificado del chunk 48. Diferenciación: Q083 enumera estandarización como variable de estrategia; aquí se aplica la consecuencia de detectar una ficha vigente sobre el contenido del requerimiento. Excepciones y condiciones: El supuesto declara cobertura y vigencia de la ficha como datos hipotéticos; no atribuye vigencia real a ninguna ficha ajena al corpus. Objetivo: Adecuar características y calificación del requerimiento a ficha de homologación vigente.. Evidencia: art. 44, chunk 51. Sin certificación oficial OECE ni revisión humana independiente; se conserva el corte documental declarado.", "confirmReview": true}, "estadoAnterior": "draft"}, {"numero": "Q074", "id": "304db3e4-0090-4582-ad83-bdb4ea69eb6f", "decision": "approve", "motivo": "Se sustituye remisión orgánica por decisión de rectificación excepcional; se limita al PAC inicial y al contraste con el formato suscrito, sin convertirla en vía de nueva programación. Confirmado con texto completo del fragmento citado y contraste de objetivos con las 181 publicadas; la nueva decisión operativa no reutiliza el objetivo anterior. Se conserva ID, revisión actual, origen y corte; el sustento anterior se conserva en reviewBasis. Se usa el texto modificado o incorporado por RD0041, no una redacción previa ni el material ajeno detectado en sus primeros fragmentos. La aprobación es editorial asistida por IA y autorizada por el administrador.", "objetivo": "Rectificar un error material de transcripción sin cambiar la programación aprobada.", "evidencia": [{"chunkId": "dab3f94c-c442-4ab5-be38-439f2babc1fe", "chunk_index": 13, "article": "15", "quote": "Artículo 15.- De la rectificación del PAC La rectificación del PAC constituye la acción excepcional destinada a corregir errores materiales de registro en el PAC aprobado a inicios del año fiscal y que se publica el Seace de la Pladicop. Dicha rectificación faculta a las entidades a hacer las adecuaciones necesarias para que la información registrada coincida con la consignada en el formato PAC suscrito por la DEC y/o efectuar correcciones relativas a aspectos ortográficos”. Artículo 4.- Publicación Disponer la publicación de la presente Resolución Directoral, así como los Anexos de la Directiva N° 0002-2025-EF/54.01 en la sede digital del Ministerio de Economía y Finanzas (www.gob.pe/mef), en la misma fecha de publicación de la presente Resolución Directoral en el diario oficial El Peruano."}], "input": {"id": "304db3e4-0090-4582-ad83-bdb4ea69eb6f", "revision": 1, "prompt": "El PAC aprobado al inicio del año fiscal consigna correctamente un objeto contractual en el formato suscrito por la DEC, pero su registro en Seace contiene una palabra mal transcrita. No se pretende agregar una necesidad ni cambiar lo aprobado. Según el artículo 15 incorporado por la RD0041-2025-EF/54.01, ¿cómo debe corregirse?", "options": [{"id": "A", "text": "Agregando automáticamente otra contratación no programada."}, {"id": "B", "text": "Mediante rectificación excepcional para hacer coincidir el registro con el formato suscrito."}, {"id": "C", "text": "Tramitando una nueva aprobación de todo el PAC por cada error ortográfico."}, {"id": "D", "text": "Esperando al cierre del ejercicio para corregir el registro."}], "correctOption": "B", "explanation": "El artículo 15 permite excepcionalmente corregir errores materiales de registro del PAC inicial para adecuarlo al formato suscrito por la DEC y efectuar correcciones ortográficas. El supuesto solo corrige la transcripción; no introduce una contratación nueva.", "regime": "32069", "topic": "Modificación del Plan Anual", "competency": "Actuaciones preparatorias", "difficulty": "intermediate", "curriculumVersion": "oece-2025-04-25", "competencyCode": "1", "subcompetencyCode": "1.5", "cognitiveLevel": "apply", "optionRationales": {"A": "No existe una nueva contratación que deba agregarse como no programada.", "B": "La rectificación permite adecuar el registro al formato y corregir aspectos ortográficos.", "C": "La fuente prevé rectificación del error material, no exige aprobar nuevamente todo el PAC.", "D": "La corrección material no se condiciona al cierre del ejercicio fiscal."}, "reviewChecks": {"unambiguous": true, "distractors": true, "conditions": true, "exceptions": true, "sources": true}, "sourceCutoff": "2026-10-29", "origin": "IA:gemini:gemini-2.5-flash:lote:9c8df57f-5b69-4e41-ab53-f6fe8f34be1f", "sources": [{"documentId": "e638f467-b991-445b-8f26-eb198ee1cc64", "chunkId": "dab3f94c-c442-4ab5-be38-439f2babc1fe", "title": "Resolución Directoral N.° 0041-2025-EF/54.01 — modificatoria de la Directiva del PAC", "article": "15", "pageStart": 3, "pageEnd": 3, "quote": "Artículo 15.- De la rectificación del PAC La rectificación del PAC constituye la acción excepcional destinada a corregir errores materiales de registro en el PAC aprobado a inicios del año fiscal y que se publica el Seace de la Pladicop. Dicha rectificación faculta a las entidades a hacer las adecuaciones necesarias para que la información registrada coincida con la consignada en el formato PAC suscrito por la DEC y/o efectuar correcciones relativas a aspectos ortográficos”. Artículo 4.- Publicación Disponer la publicación de la presente Resolución Directoral, así como los Anexos de la Directiva N° 0002-2025-EF/54.01 en la sede digital del Ministerio de Economía y Finanzas (www.gob.pe/mef), en la misma fecha de publicación de la presente Resolución Directoral en el diario oficial El Peruano.", "version": "Texto publicado el 25.12.2025", "sha256": "0962d2b62f3a0d28ed8ecb84319ca4bbfc5f34e0057ce328f78fca8a26c6c914"}], "status": "published", "reviewBasis": "Revisión asistida por IA el15/11/2026 por encargo y autorización expresa del administrador. Se sustituye remisión orgánica por decisión de rectificación excepcional; se limita al PAC inicial y al contraste con el formato suscrito, sin convertirla en vía de nueva programación. Confirmado con texto completo del fragmento citado y contraste de objetivos con las 181 publicadas; la nueva decisión operativa no reutiliza el objetivo anterior. Se conserva ID, revisión actual, origen y corte; el sustento anterior se conserva en reviewBasis. Se usa el texto modificado o incorporado por RD0041, no una redacción previa ni el material ajeno detectado en sus primeros fragmentos. La aprobación es editorial asistida por IA y autorizada por el administrador. Objetivo: Rectificar un error material de transcripción sin cambiar la programación aprobada.. Evidencia: art. 15, chunk 13. Sin certificación oficial OECE ni revisión humana independiente; se conserva el corte documental declarado.", "confirmReview": true}, "estadoAnterior": "draft"}, {"numero": "Q076", "id": "3e2c0055-aef9-455d-92d9-5af16fa2fe5e", "decision": "approve", "motivo": "Se reemplaza actualización transitoria por tratamiento de contratación no programada; se comprueba la extensión a 7.2 sin afirmar que toda alteración sea automática. Confirmado con texto completo del fragmento citado y contraste de objetivos con las 181 publicadas; la nueva decisión operativa no reutiliza el objetivo anterior. Se conserva ID, revisión actual, origen y corte; el sustento anterior se conserva en reviewBasis. Se usa el texto modificado o incorporado por RD0041, no una redacción previa ni el material ajeno detectado en sus primeros fragmentos. La aprobación es editorial asistida por IA y autorizada por el administrador.", "objetivo": "Distinguir la agregación automática de una contratación no programada de una modificación del PAC.", "evidencia": [{"chunkId": "72d0478b-e805-4506-af75-2767ab6aaa23", "chunk_index": 11, "article": "11", "quote": "Artículo 11.- De las contrataciones no programadas en el PAC Durante cualquier momento del año fiscal, en caso la entidad contratante convoque un procedimiento de selección o efectúe una contratación que no se encuentre en el PAC aprobado, el Seace de la Pladicop las agrega automáticamente al PAC en calidad de contratación no programada, sin que ello constituya una modificación al PAC. Esta disposición aplica a las contrataciones señaladas en el numeral 7.2 del artículo 7 de la presente Directiva. (...)”.\n\n24 NORMAS LEGALES Jueves 25 de diciembre de 2025 El Peruano / “"}], "input": {"id": "3e2c0055-aef9-455d-92d9-5af16fa2fe5e", "revision": 1, "prompt": "Durante el año fiscal se convoca válidamente un procedimiento no previsto en el PAC aprobado. Los demás requisitos están cumplidos. Según el artículo 11 modificado por la RD0041-2025-EF/54.01, ¿qué tratamiento recibe en el PAC?", "options": [{"id": "A", "text": "Debe eliminarse la convocatoria hasta aprobar una modificación previa del PAC."}, {"id": "B", "text": "Solo se incorpora al PAC cuando se suscribe el contrato, nunca al convocar."}, {"id": "C", "text": "Seace de la Pladicop lo agrega automáticamente como no programado, sin constituir modificación del PAC."}, {"id": "D", "text": "Se excluye definitivamente del PAC por no haber sido programado al inicio."}], "correctOption": "C", "explanation": "La convocatoria de un procedimiento no previsto activa su agregación automática por Seace de la Pladicop como contratación no programada. El artículo 11 precisa que no constituye modificación del PAC y extiende su disposición a las contrataciones del numeral 7.2.", "regime": "32069", "topic": "Modificación del Plan Anual", "competency": "Actuaciones preparatorias", "difficulty": "intermediate", "curriculumVersion": "oece-2025-04-25", "competencyCode": "1", "subcompetencyCode": "1.5", "cognitiveLevel": "apply", "optionRationales": {"A": "La regla no condiciona este registro automático a una modificación previa.", "B": "El supuesto de convocatoria ya activa la agregación prevista en el artículo 11.", "C": "El artículo 11 establece agregación automática sin calificarla como modificación.", "D": "La ausencia de programación inicial determina su calidad de no programado, no su exclusión."}, "reviewChecks": {"unambiguous": true, "distractors": true, "conditions": true, "exceptions": true, "sources": true}, "sourceCutoff": "2026-10-29", "origin": "IA:gemini:gemini-2.5-flash:lote:cccca389-9b63-4a38-bdbb-823d6aa070c3", "sources": [{"documentId": "e638f467-b991-445b-8f26-eb198ee1cc64", "chunkId": "72d0478b-e805-4506-af75-2767ab6aaa23", "title": "Resolución Directoral N.° 0041-2025-EF/54.01 — modificatoria de la Directiva del PAC", "article": "11", "pageStart": 2, "pageEnd": 3, "quote": "Artículo 11.- De las contrataciones no programadas en el PAC Durante cualquier momento del año fiscal, en caso la entidad contratante convoque un procedimiento de selección o efectúe una contratación que no se encuentre en el PAC aprobado, el Seace de la Pladicop las agrega automáticamente al PAC en calidad de contratación no programada, sin que ello constituya una modificación al PAC. Esta disposición aplica a las contrataciones señaladas en el numeral 7.2 del artículo 7 de la presente Directiva. (...)”.\n\n24 NORMAS LEGALES Jueves 25 de diciembre de 2025 El Peruano / “", "version": "Texto publicado el 25.12.2025", "sha256": "0962d2b62f3a0d28ed8ecb84319ca4bbfc5f34e0057ce328f78fca8a26c6c914"}], "status": "published", "reviewBasis": "Revisión asistida por IA el15/11/2026 por encargo y autorización expresa del administrador. Se reemplaza actualización transitoria por tratamiento de contratación no programada; se comprueba la extensión a 7.2 sin afirmar que toda alteración sea automática. Confirmado con texto completo del fragmento citado y contraste de objetivos con las 181 publicadas; la nueva decisión operativa no reutiliza el objetivo anterior. Se conserva ID, revisión actual, origen y corte; el sustento anterior se conserva en reviewBasis. Se usa el texto modificado o incorporado por RD0041, no una redacción previa ni el material ajeno detectado en sus primeros fragmentos. La aprobación es editorial asistida por IA y autorizada por el administrador. Objetivo: Distinguir la agregación automática de una contratación no programada de una modificación del PAC.. Evidencia: art. 11, chunk 11. Sin certificación oficial OECE ni revisión humana independiente; se conserva el corte documental declarado.", "confirmReview": true}, "estadoAnterior": "draft"}, {"numero": "Q077", "id": "fd617f76-be6c-44df-abfd-a5a6acef4b15", "decision": "approve", "motivo": "Se abandona elaboración transitoria del PAC y se evalúa operación de formulación desde CMN aprobado; no se asume inclusión de contratos menores ni se evalúa ítem desierto. Confirmado con texto completo del fragmento citado y contraste de objetivos con las 181 publicadas; la nueva decisión operativa no reutiliza el objetivo anterior. Se conserva ID, revisión actual, origen y corte; el sustento anterior se conserva en reviewBasis. Se usa el texto modificado o incorporado por RD0041, no una redacción previa ni el material ajeno detectado en sus primeros fragmentos. La aprobación es editorial asistida por IA y autorizada por el administrador.", "objetivo": "Transformar necesidades del CMN aprobado en objetos contractuales con procedimiento o modalidad asignados.", "evidencia": [{"chunkId": "325ba101-77a7-46e8-ab1d-4fb9651759a7", "chunk_index": 6, "article": "6", "quote": "Artículo 6.- De los insumos para la elaboración del PAC 6.1 Las entidades contratantes realizan el registro de sus necesidades de bienes, servicios y obras de acuerdo con lo previsto en la Directiva N° 0007-2025-EF/54.01, Directiva para la Programación Multianual de Bienes, Servicios y Obras, aprobada mediante Resolución Directoral N° 0022-2025-EF/54.01 (en adelante, la Directiva para la PMBSO), o norma que la sustituya, cuyo producto es el CMN, el cual es insumo para la formulación del PAC. (...) 6.3. Para la elaboración del PAC, la DEC agrupa las necesidades de la entidad contratante previstas en el CMN aprobado, en objetos contractuales, asignando el procedimiento de selección con modalidad o sin modalidad o la modalidad de contratación pública eficiente respectiva, de conformidad con el formato PAC que publique el OECE para tal efecto. (...)”. “"}], "input": {"id": "fd617f76-be6c-44df-abfd-a5a6acef4b15", "revision": 1, "prompt": "La DEC recibe un CMN aprobado con necesidades de varias unidades y debe formular el PAC. Según el numeral 6.3 modificado por la RD0041-2025-EF/54.01, ¿qué operación corresponde?", "options": [{"id": "A", "text": "Usar solo solicitudes no aprobadas y dejar el CMN para la ejecución contractual."}, {"id": "B", "text": "Definir primero proveedores ganadores y luego agrupar sus contratos en el CMN."}, {"id": "C", "text": "Trasladar cada pedido sin agruparlo ni asignarle procedimiento o modalidad."}, {"id": "D", "text": "Agrupar las necesidades en objetos contractuales y asignar el procedimiento o modalidad respectivo conforme al formato PAC."}], "correctOption": "D", "explanation": "El numeral 6.3 exige agrupar las necesidades del CMN aprobado en objetos contractuales y asignar el procedimiento de selección, con o sin modalidad, o la modalidad de contratación pública eficiente respectiva, conforme al formato PAC publicado por el OECE.", "regime": "32069", "topic": "Plan Anual y necesidades", "competency": "Actuaciones preparatorias", "difficulty": "intermediate", "curriculumVersion": "oece-2025-04-25", "competencyCode": "1", "subcompetencyCode": "1.6", "cognitiveLevel": "apply", "optionRationales": {"A": "La base de formulación son las necesidades previstas en el CMN aprobado.", "B": "La formulación del PAC no se sustituye por adjudicaciones previas a proveedores.", "C": "El traslado sin agrupación ni asignación omite las operaciones expresamente exigidas.", "D": "El numeral 6.3 vincula agrupación, asignación de procedimiento o modalidad y formato PAC."}, "reviewChecks": {"unambiguous": true, "distractors": true, "conditions": true, "exceptions": true, "sources": true}, "sourceCutoff": "2026-10-29", "origin": "IA:gemini:gemini-2.5-flash:lote:cccca389-9b63-4a38-bdbb-823d6aa070c3", "sources": [{"documentId": "e638f467-b991-445b-8f26-eb198ee1cc64", "chunkId": "325ba101-77a7-46e8-ab1d-4fb9651759a7", "title": "Resolución Directoral N.° 0041-2025-EF/54.01 — modificatoria de la Directiva del PAC", "article": "6", "pageStart": 2, "pageEnd": 2, "quote": "Artículo 6.- De los insumos para la elaboración del PAC 6.1 Las entidades contratantes realizan el registro de sus necesidades de bienes, servicios y obras de acuerdo con lo previsto en la Directiva N° 0007-2025-EF/54.01, Directiva para la Programación Multianual de Bienes, Servicios y Obras, aprobada mediante Resolución Directoral N° 0022-2025-EF/54.01 (en adelante, la Directiva para la PMBSO), o norma que la sustituya, cuyo producto es el CMN, el cual es insumo para la formulación del PAC. (...) 6.3. Para la elaboración del PAC, la DEC agrupa las necesidades de la entidad contratante previstas en el CMN aprobado, en objetos contractuales, asignando el procedimiento de selección con modalidad o sin modalidad o la modalidad de contratación pública eficiente respectiva, de conformidad con el formato PAC que publique el OECE para tal efecto. (...)”. “", "version": "Texto publicado el 25.12.2025", "sha256": "0962d2b62f3a0d28ed8ecb84319ca4bbfc5f34e0057ce328f78fca8a26c6c914"}], "status": "published", "reviewBasis": "Revisión asistida por IA el15/11/2026 por encargo y autorización expresa del administrador. Se abandona elaboración transitoria del PAC y se evalúa operación de formulación desde CMN aprobado; no se asume inclusión de contratos menores ni se evalúa ítem desierto. Confirmado con texto completo del fragmento citado y contraste de objetivos con las 181 publicadas; la nueva decisión operativa no reutiliza el objetivo anterior. Se conserva ID, revisión actual, origen y corte; el sustento anterior se conserva en reviewBasis. Se usa el texto modificado o incorporado por RD0041, no una redacción previa ni el material ajeno detectado en sus primeros fragmentos. La aprobación es editorial asistida por IA y autorizada por el administrador. Objetivo: Transformar necesidades del CMN aprobado en objetos contractuales con procedimiento o modalidad asignados.. Evidencia: art. 6, chunk 6. Sin certificación oficial OECE ni revisión humana independiente; se conserva el corte documental declarado.", "confirmReview": true}, "estadoAnterior": "draft"}, {"numero": "Q078", "id": "5ba26a11-3852-434e-88d5-9e5e2128132d", "decision": "approve", "motivo": "Se sustituye remisión DGA por condición concreta de convocatoria; la excepción solo alcanza programación en PAC, no elimina la previsión en CMN ni los demás requisitos. Confirmado con texto completo del fragmento citado y contraste de objetivos con las 181 publicadas; la nueva decisión operativa no reutiliza el objetivo anterior. Se conserva ID, revisión actual, origen y corte; el sustento anterior se conserva en reviewBasis. Se usa el texto modificado o incorporado por RD0041, no una redacción previa ni el material ajeno detectado en sus primeros fragmentos. La aprobación es editorial asistida por IA y autorizada por el administrador.", "objetivo": "Determinar si la ausencia en PAC impide convocar cuando la necesidad sí está prevista en CMN.", "evidencia": [{"chunkId": "fe2c29a2-28e5-4801-b514-39aee2377b8b", "chunk_index": 10, "article": "10", "quote": "Artículo 10.- De la ejecución del PAC (...) 10.2. No es requisito para convocar un procedimiento de selección que este se encuentre previsto en el PAC; sin perjuicio de ello, la necesidad sí debe estar prevista en el CMN aprobado y sus modificatorias, conforme a las disposiciones previstas en la Directiva para la PMBSO. (....)”. “"}], "input": {"id": "5ba26a11-3852-434e-88d5-9e5e2128132d", "revision": 1, "prompt": "Un procedimiento no figura en el PAC, pero su necesidad sí está prevista en el CMN aprobado y sus modificatorias. Los demás requisitos para convocar se cumplen. Según el numeral 10.2 modificado por la RD0041-2025-EF/54.01, ¿qué corresponde?", "options": [{"id": "A", "text": "Puede convocarse: su previsión en PAC no es requisito, manteniéndose la exigencia relativa al CMN."}, {"id": "B", "text": "Solo puede convocarse si primero se elimina del CMN la necesidad."}, {"id": "C", "text": "No puede convocarse hasta incluirlo mediante modificación previa del PAC."}, {"id": "D", "text": "Puede convocarse incluso si la necesidad tampoco estuviera prevista en CMN."}], "correctOption": "A", "explanation": "El numeral 10.2 no exige que el procedimiento esté previsto en PAC para convocarlo. Sí exige que la necesidad esté prevista en el CMN aprobado y sus modificatorias conforme a la Directiva PMBSO. El caso da por cumplidos los demás requisitos.", "regime": "32069", "topic": "Plan Anual y necesidades", "competency": "Actuaciones preparatorias", "difficulty": "intermediate", "curriculumVersion": "oece-2025-04-25", "competencyCode": "1", "subcompetencyCode": "1.6", "cognitiveLevel": "apply", "optionRationales": {"A": "El numeral 10.2 distingue la no exigencia de previsión en PAC de la exigencia en CMN.", "B": "Eliminar la necesidad del CMN contradice la condición expresamente prevista.", "C": "La modificación previa del PAC no es la condición establecida para convocar.", "D": "La dispensa relativa al PAC no elimina la obligación de previsión en CMN."}, "reviewChecks": {"unambiguous": true, "distractors": true, "conditions": true, "exceptions": true, "sources": true}, "sourceCutoff": "2026-10-29", "origin": "IA:gemini:gemini-2.5-flash:lote:48b9452f-7a90-44c9-82dc-267a1ae32579", "sources": [{"documentId": "e638f467-b991-445b-8f26-eb198ee1cc64", "chunkId": "fe2c29a2-28e5-4801-b514-39aee2377b8b", "title": "Resolución Directoral N.° 0041-2025-EF/54.01 — modificatoria de la Directiva del PAC", "article": "10", "pageStart": 2, "pageEnd": 2, "quote": "Artículo 10.- De la ejecución del PAC (...) 10.2. No es requisito para convocar un procedimiento de selección que este se encuentre previsto en el PAC; sin perjuicio de ello, la necesidad sí debe estar prevista en el CMN aprobado y sus modificatorias, conforme a las disposiciones previstas en la Directiva para la PMBSO. (....)”. “", "version": "Texto publicado el 25.12.2025", "sha256": "0962d2b62f3a0d28ed8ecb84319ca4bbfc5f34e0057ce328f78fca8a26c6c914"}], "status": "published", "reviewBasis": "Revisión asistida por IA el15/11/2026 por encargo y autorización expresa del administrador. Se sustituye remisión DGA por condición concreta de convocatoria; la excepción solo alcanza programación en PAC, no elimina la previsión en CMN ni los demás requisitos. Confirmado con texto completo del fragmento citado y contraste de objetivos con las 181 publicadas; la nueva decisión operativa no reutiliza el objetivo anterior. Se conserva ID, revisión actual, origen y corte; el sustento anterior se conserva en reviewBasis. Se usa el texto modificado o incorporado por RD0041, no una redacción previa ni el material ajeno detectado en sus primeros fragmentos. La aprobación es editorial asistida por IA y autorizada por el administrador. Objetivo: Determinar si la ausencia en PAC impide convocar cuando la necesidad sí está prevista en CMN.. Evidencia: art. 10, chunk 10. Sin certificación oficial OECE ni revisión humana independiente; se conserva el corte documental declarado.", "confirmReview": true}, "estadoAnterior": "draft"}, {"numero": "Q079", "id": "e969f489-36f8-4f8e-8d3e-f4e63928d374", "decision": "approve", "motivo": "Se reemplaza actualización transitoria por obligación operativa de publicidad; se incorpora sede digital porque el caso declara que existe y se conserva plazo en días hábiles. Confirmado con texto completo del fragmento citado y contraste de objetivos con las 181 publicadas; la nueva decisión operativa no reutiliza el objetivo anterior. Se conserva ID, revisión actual, origen y corte; el sustento anterior se conserva en reviewBasis. Se usa el texto modificado o incorporado por RD0041, no una redacción previa ni el material ajeno detectado en sus primeros fragmentos. La aprobación es editorial asistida por IA y autorizada por el administrador.", "objetivo": "Ejecutar el registro y publicación del PAC aprobado en los canales y plazo aplicables.", "evidencia": [{"chunkId": "44c4b53a-b7f3-4081-ab74-665ecbb9cca9", "chunk_index": 9, "article": "9", "quote": "Artículo 9.- Del registro y publicación del PAC 9.1. La DEC registra y publica el PAC en el Seace de la Pladicop, usando el Catálogo Único de Bienes, Servicios y Obras (CUBSO) del referido sistema; asimismo, publica el formato PAC en la sede digital de la entidad contratante en caso cuente con ella, en un plazo no mayor a cinco (05) días hábiles de aprobado, conforme a las disposiciones operativas que publique el OECE. (...)” “"}], "input": {"id": "e969f489-36f8-4f8e-8d3e-f4e63928d374", "revision": 1, "prompt": "Una entidad con sede digital acaba de aprobar su PAC. Según el numeral 9.1 modificado por la RD0041-2025-EF/54.01, ¿qué actuación debe organizar la DEC?", "options": [{"id": "A", "text": "Publicar únicamente el formato en la sede digital dentro de quince días hábiles."}, {"id": "B", "text": "Registrar y publicar el PAC en Seace de la Pladicop usando CUBSO y publicar el formato en su sede digital dentro de cinco días hábiles de aprobado."}, {"id": "C", "text": "Registrar el PAC sin usar CUBSO y reservar su publicación hasta la primera convocatoria."}, {"id": "D", "text": "Publicar únicamente en Seace y omitir siempre la sede digital aunque exista."}], "correctOption": "B", "explanation": "La DEC registra y publica el PAC en Seace de la Pladicop usando CUBSO y publica además el formato PAC en la sede digital cuando cuenta con ella. El numeral 9.1 fija un máximo de cinco días hábiles de aprobado, conforme a las disposiciones operativas del OECE.", "regime": "32069", "topic": "PLADICOP en actuaciones preparatorias", "competency": "Actuaciones preparatorias", "difficulty": "intermediate", "curriculumVersion": "oece-2025-04-25", "competencyCode": "1", "subcompetencyCode": "1.8", "cognitiveLevel": "apply", "optionRationales": {"A": "La sede digital no sustituye Seace y el plazo citado no es el de registro y publicación.", "B": "Se cumplen canal, catálogo, publicidad adicional y plazo del numeral 9.1.", "C": "La norma exige usar CUBSO y no permite diferir la publicidad hasta convocar.", "D": "La publicación del formato en sede digital es exigida cuando la entidad cuenta con ella."}, "reviewChecks": {"unambiguous": true, "distractors": true, "conditions": true, "exceptions": true, "sources": true}, "sourceCutoff": "2026-10-29", "origin": "IA:gemini:gemini-2.5-flash:lote:4bf994a3-de57-4521-a048-9a2e1d34975e", "sources": [{"documentId": "e638f467-b991-445b-8f26-eb198ee1cc64", "chunkId": "44c4b53a-b7f3-4081-ab74-665ecbb9cca9", "title": "Resolución Directoral N.° 0041-2025-EF/54.01 — modificatoria de la Directiva del PAC", "article": "9", "pageStart": 2, "pageEnd": 2, "quote": "Artículo 9.- Del registro y publicación del PAC 9.1. La DEC registra y publica el PAC en el Seace de la Pladicop, usando el Catálogo Único de Bienes, Servicios y Obras (CUBSO) del referido sistema; asimismo, publica el formato PAC en la sede digital de la entidad contratante en caso cuente con ella, en un plazo no mayor a cinco (05) días hábiles de aprobado, conforme a las disposiciones operativas que publique el OECE. (...)” “", "version": "Texto publicado el 25.12.2025", "sha256": "0962d2b62f3a0d28ed8ecb84319ca4bbfc5f34e0057ce328f78fca8a26c6c914"}], "status": "published", "reviewBasis": "Revisión asistida por IA el15/11/2026 por encargo y autorización expresa del administrador. Se reemplaza actualización transitoria por obligación operativa de publicidad; se incorpora sede digital porque el caso declara que existe y se conserva plazo en días hábiles. Confirmado con texto completo del fragmento citado y contraste de objetivos con las 181 publicadas; la nueva decisión operativa no reutiliza el objetivo anterior. Se conserva ID, revisión actual, origen y corte; el sustento anterior se conserva en reviewBasis. Se usa el texto modificado o incorporado por RD0041, no una redacción previa ni el material ajeno detectado en sus primeros fragmentos. La aprobación es editorial asistida por IA y autorizada por el administrador. Objetivo: Ejecutar el registro y publicación del PAC aprobado en los canales y plazo aplicables.. Evidencia: art. 9, chunk 9. Sin certificación oficial OECE ni revisión humana independiente; se conserva el corte documental declarado.", "confirmReview": true}, "estadoAnterior": "draft"}, {"numero": "Q086", "id": "3319a126-97b3-41d1-9d6f-b4e3e50c7f57", "decision": "approve", "motivo": "Sustituye distribución jurado/DEC por control formal económico; se distingue total y subtotales de desagregados sin inferir rechazo automático. Confirmado con texto completo del fragmento citado y contraste de objetivos con las 181 publicadas; la nueva decisión operativa no reutiliza el objetivo anterior. Se conserva ID, revisión actual, origen y corte; el sustento anterior se conserva en reviewBasis. Se usa el numeral citado sin mezclar las redacciones originales y modificadas que coexisten en otros numerales del documento. La aprobación es editorial asistida por IA y autorizada por el administrador.", "objetivo": "Aplicar distinta precisión decimal al total, subtotales y valores desagregados de la oferta.", "evidencia": [{"chunkId": "c0f4c18d-7d43-47b2-a761-f373ee5c308e", "chunk_index": 81, "article": "69", "quote": ". Asi mismo, puede contener documentación que acredite el cumplimiento de las especificaciones técnicas, de haberse determinado así en la estrategia de contratación. 69.3. La oferta económica y sus subtotales se expresan en dos decimales y todos sus valores desagregados pueden ser expresados con más de dos decimales. 69.4. La oferta económica incluye todos los tributos, seguros, transporte, inspecciones, pruebas y, de ser el caso, los costos laborales conforme a la legislación vigente, así como cualquier otro concepto que pueda tener incidencia sobre el costo del bien, servicio en general, consultoría u obra a contratar. Los postores que gocen de alguna exoneración legal tributaria no incluyen en su oferta los tributos respectivos. 69.5. Los documentos que presentan los participantes en la fase de selección, incluyendo las ofertas, son presentadas en idioma español o con la respectiva traducción por traductor público juramentado o traductor colegiado certificado, salvo el caso de la información técnica complementaria contenida en folletos, instructivos, catálogos o similares, que puede ser presentada en el idioma original."}], "input": {"id": "3319a126-97b3-41d1-9d6f-b4e3e50c7f57", "revision": 2, "prompt": "Una oferta presenta un precio unitario de S/1,2578, pero su total y subtotales están expresados con dos decimales. Se pide únicamente verificar la regla de precisión del numeral 69.3. ¿Qué conclusión corresponde?", "options": [{"id": "A", "text": "Todos los valores deben tener exactamente dos decimales, incluidos los unitarios."}, {"id": "B", "text": "El total debe conservar tantos decimales como el precio unitario."}, {"id": "C", "text": "La precisión indicada es compatible: total y subtotales tienen dos decimales y los desagregados pueden tener más."}, {"id": "D", "text": "Solo el total necesita dos decimales; los subtotales necesariamente deben tener cuatro."}], "correctOption": "C", "explanation": "El numeral 69.3 exige dos decimales para la oferta económica y sus subtotales, y permite más de dos decimales en sus valores desagregados. La precisión del precio unitario descrita cumple esa regla, sin que esta comprobación resuelva los demás requisitos de la oferta.", "regime": "32069", "topic": "Etapas, plazos y condiciones", "competency": "Selección", "difficulty": "intermediate", "curriculumVersion": "oece-2025-04-25", "competencyCode": "2", "subcompetencyCode": "2.2", "cognitiveLevel": "apply", "optionRationales": {"A": "Extender dos decimales a cada desagregado contradice la autorización expresa.", "B": "La mayor precisión del unitario no cambia la precisión exigida al total.", "C": "El numeral 69.3 permite más de dos decimales en los valores desagregados.", "D": "Los subtotales también deben expresarse en dos decimales, no obligatoriamente en cuatro."}, "reviewChecks": {"unambiguous": true, "distractors": true, "conditions": true, "exceptions": true, "sources": true}, "sourceCutoff": "2026-10-29", "origin": "IA:gemini:gemini-2.5-flash:lote:68ea393c-6723-4f8b-8922-613f9f47227e", "sources": [{"documentId": "8371bce1-f773-4ad8-8efa-1266276ae4ec", "chunkId": "c0f4c18d-7d43-47b2-a761-f373ee5c308e", "title": "Reglamento de la Ley N.° 32069 — texto actualizado al 09.01.2026", "article": "69", "pageStart": 38, "pageEnd": 39, "quote": ". Asi mismo, puede contener documentación que acredite el cumplimiento de las especificaciones técnicas, de haberse determinado así en la estrategia de contratación. 69.3. La oferta económica y sus subtotales se expresan en dos decimales y todos sus valores desagregados pueden ser expresados con más de dos decimales. 69.4. La oferta económica incluye todos los tributos, seguros, transporte, inspecciones, pruebas y, de ser el caso, los costos laborales conforme a la legislación vigente, así como cualquier otro concepto que pueda tener incidencia sobre el costo del bien, servicio en general, consultoría u obra a contratar. Los postores que gocen de alguna exoneración legal tributaria no incluyen en su oferta los tributos respectivos. 69.5. Los documentos que presentan los participantes en la fase de selección, incluyendo las ofertas, son presentadas en idioma español o con la respectiva traducción por traductor público juramentado o traductor colegiado certificado, salvo el caso de la información técnica complementaria contenida en folletos, instructivos, catálogos o similares, que puede ser presentada en el idioma original.", "version": "Texto actualizado al 09.01.2026", "sha256": "0ebe95b3e05661b80f73c060d6e6ce8dd17621ce34af9277c688dd67e5d99830"}], "status": "published", "reviewBasis": "Revisión asistida por IA el15/11/2026 por encargo y autorización expresa del administrador. Sustituye distribución jurado/DEC por control formal económico; se distingue total y subtotales de desagregados sin inferir rechazo automático. Confirmado con texto completo del fragmento citado y contraste de objetivos con las 181 publicadas; la nueva decisión operativa no reutiliza el objetivo anterior. Se conserva ID, revisión actual, origen y corte; el sustento anterior se conserva en reviewBasis. Se usa el numeral citado sin mezclar las redacciones originales y modificadas que coexisten en otros numerales del documento. La aprobación es editorial asistida por IA y autorizada por el administrador. Objetivo: Aplicar distinta precisión decimal al total, subtotales y valores desagregados de la oferta.. Evidencia: art. 69, chunk 81. Sin certificación oficial OECE ni revisión humana independiente; se conserva el corte documental declarado.", "confirmReview": true}, "estadoAnterior": "draft"}, {"numero": "Q089", "id": "a6c8573e-7c05-4cf6-b939-d94c135d9531", "decision": "approve", "motivo": "Reemplaza nueva convocatoria de ítem desierto por composición del precio; la excepción depende de exoneración legal acreditada y no suprime otros costos. Confirmado con texto completo del fragmento citado y contraste de objetivos con las 181 publicadas; la nueva decisión operativa no reutiliza el objetivo anterior. Se conserva ID, revisión actual, origen y corte; el sustento anterior se conserva en reviewBasis. Se usa el numeral citado sin mezclar las redacciones originales y modificadas que coexisten en otros numerales del documento. La aprobación es editorial asistida por IA y autorizada por el administrador.", "objetivo": "Tratar una exoneración tributaria legal al integrar el precio ofertado.", "evidencia": [{"chunkId": "c0f4c18d-7d43-47b2-a761-f373ee5c308e", "chunk_index": 81, "article": "69", "quote": ". Asi mismo, puede contener documentación que acredite el cumplimiento de las especificaciones técnicas, de haberse determinado así en la estrategia de contratación. 69.3. La oferta económica y sus subtotales se expresan en dos decimales y todos sus valores desagregados pueden ser expresados con más de dos decimales. 69.4. La oferta económica incluye todos los tributos, seguros, transporte, inspecciones, pruebas y, de ser el caso, los costos laborales conforme a la legislación vigente, así como cualquier otro concepto que pueda tener incidencia sobre el costo del bien, servicio en general, consultoría u obra a contratar. Los postores que gocen de alguna exoneración legal tributaria no incluyen en su oferta los tributos respectivos. 69.5. Los documentos que presentan los participantes en la fase de selección, incluyendo las ofertas, son presentadas en idioma español o con la respectiva traducción por traductor público juramentado o traductor colegiado certificado, salvo el caso de la información técnica complementaria contenida en folletos, instructivos, catálogos o similares, que puede ser presentada en el idioma original."}], "input": {"id": "a6c8573e-7c05-4cf6-b939-d94c135d9531", "revision": 1, "prompt": "Un postor goza de una exoneración legal tributaria aplicable al bien ofertado. Para preparar su oferta económica bajo el numeral 69.4, ¿cómo debe tratar el tributo exonerado y los costos de transporte?", "options": [{"id": "A", "text": "Excluir todos los tributos, aun los no comprendidos en la exoneración."}, {"id": "B", "text": "Excluir el transporte porque solo se cotiza el precio de fábrica."}, {"id": "C", "text": "Incluir el tributo exonerado y omitir siempre el transporte."}, {"id": "D", "text": "Excluir el tributo del que está legalmente exonerado e incluir el transporte que incide en el costo."}], "correctOption": "D", "explanation": "La oferta incluye transporte, seguros, pruebas y demás conceptos que puedan incidir en el costo. El numeral 69.4 exceptúa los tributos respectivos cuando el postor goza de exoneración legal; no elimina otros costos ni tributos no exonerados.", "regime": "32069", "topic": "Etapas, plazos y condiciones", "competency": "Selección", "difficulty": "intermediate", "curriculumVersion": "oece-2025-04-25", "competencyCode": "2", "subcompetencyCode": "2.2", "cognitiveLevel": "apply", "optionRationales": {"A": "La exoneración no autoriza eliminar tributos ajenos a su alcance legal.", "B": "El numeral 69.4 incorpora transporte y otros conceptos que inciden en el costo.", "C": "La exoneración evita incluir ese tributo y no libera de incorporar transporte.", "D": "La excepción alcanza los tributos respectivos y la regla general incluye transporte."}, "reviewChecks": {"unambiguous": true, "distractors": true, "conditions": true, "exceptions": true, "sources": true}, "sourceCutoff": "2026-10-29", "origin": "IA:gemini:gemini-2.5-flash:lote:453ba81a-622d-40bb-b27e-59ff7e63d148", "sources": [{"documentId": "8371bce1-f773-4ad8-8efa-1266276ae4ec", "chunkId": "c0f4c18d-7d43-47b2-a761-f373ee5c308e", "title": "Reglamento de la Ley N.° 32069 — texto actualizado al 09.01.2026", "article": "69", "pageStart": 38, "pageEnd": 39, "quote": ". Asi mismo, puede contener documentación que acredite el cumplimiento de las especificaciones técnicas, de haberse determinado así en la estrategia de contratación. 69.3. La oferta económica y sus subtotales se expresan en dos decimales y todos sus valores desagregados pueden ser expresados con más de dos decimales. 69.4. La oferta económica incluye todos los tributos, seguros, transporte, inspecciones, pruebas y, de ser el caso, los costos laborales conforme a la legislación vigente, así como cualquier otro concepto que pueda tener incidencia sobre el costo del bien, servicio en general, consultoría u obra a contratar. Los postores que gocen de alguna exoneración legal tributaria no incluyen en su oferta los tributos respectivos. 69.5. Los documentos que presentan los participantes en la fase de selección, incluyendo las ofertas, son presentadas en idioma español o con la respectiva traducción por traductor público juramentado o traductor colegiado certificado, salvo el caso de la información técnica complementaria contenida en folletos, instructivos, catálogos o similares, que puede ser presentada en el idioma original.", "version": "Texto actualizado al 09.01.2026", "sha256": "0ebe95b3e05661b80f73c060d6e6ce8dd17621ce34af9277c688dd67e5d99830"}], "status": "published", "reviewBasis": "Revisión asistida por IA el15/11/2026 por encargo y autorización expresa del administrador. Reemplaza nueva convocatoria de ítem desierto por composición del precio; la excepción depende de exoneración legal acreditada y no suprime otros costos. Confirmado con texto completo del fragmento citado y contraste de objetivos con las 181 publicadas; la nueva decisión operativa no reutiliza el objetivo anterior. Se conserva ID, revisión actual, origen y corte; el sustento anterior se conserva en reviewBasis. Se usa el numeral citado sin mezclar las redacciones originales y modificadas que coexisten en otros numerales del documento. La aprobación es editorial asistida por IA y autorizada por el administrador. Objetivo: Tratar una exoneración tributaria legal al integrar el precio ofertado.. Evidencia: art. 69, chunk 81. Sin certificación oficial OECE ni revisión humana independiente; se conserva el corte documental declarado.", "confirmReview": true}, "estadoAnterior": "draft"}, {"numero": "Q091", "id": "4e2d9418-4cd8-4231-9c15-30de0c9f8255", "decision": "approve", "motivo": "Sustituye cuantía por ítems por regla documental de selección; se delimita catálogo complementario y se evita extender la excepción a cualquier documento técnico. Confirmado con texto completo del fragmento citado y contraste de objetivos con las 181 publicadas; la nueva decisión operativa no reutiliza el objetivo anterior. Se conserva ID, revisión actual, origen y corte; el sustento anterior se conserva en reviewBasis. Se usa el numeral citado sin mezclar las redacciones originales y modificadas que coexisten en otros numerales del documento. La aprobación es editorial asistida por IA y autorizada por el administrador.", "objetivo": "Separar la traducción exigible de documentos de la excepción para información técnica complementaria.", "evidencia": [{"chunkId": "c0f4c18d-7d43-47b2-a761-f373ee5c308e", "chunk_index": 81, "article": "69", "quote": ". Asi mismo, puede contener documentación que acredite el cumplimiento de las especificaciones técnicas, de haberse determinado así en la estrategia de contratación. 69.3. La oferta económica y sus subtotales se expresan en dos decimales y todos sus valores desagregados pueden ser expresados con más de dos decimales. 69.4. La oferta económica incluye todos los tributos, seguros, transporte, inspecciones, pruebas y, de ser el caso, los costos laborales conforme a la legislación vigente, así como cualquier otro concepto que pueda tener incidencia sobre el costo del bien, servicio en general, consultoría u obra a contratar. Los postores que gocen de alguna exoneración legal tributaria no incluyen en su oferta los tributos respectivos. 69.5. Los documentos que presentan los participantes en la fase de selección, incluyendo las ofertas, son presentadas en idioma español o con la respectiva traducción por traductor público juramentado o traductor colegiado certificado, salvo el caso de la información técnica complementaria contenida en folletos, instructivos, catálogos o similares, que puede ser presentada en el idioma original."}], "input": {"id": "4e2d9418-4cd8-4231-9c15-30de0c9f8255", "revision": 1, "prompt": "Una oferta incluye un documento de representación en francés y un catálogo en ese idioma que solo contiene información técnica complementaria. Según el numeral 69.5, ¿qué tratamiento corresponde?", "options": [{"id": "A", "text": "Traducir el documento de representación mediante traductor habilitado en la norma; el catálogo complementario puede conservar su idioma original."}, {"id": "B", "text": "Sustituir la traducción del documento de representación por una declaración libre del vendedor."}, {"id": "C", "text": "Mantener ambos documentos en francés por formar parte de una oferta técnica."}, {"id": "D", "text": "Traducir obligatoriamente todo catálogo y dejar sin traducción el documento de representación."}], "correctOption": "A", "explanation": "El numeral 69.5 exige documentos en español o traducción por traductor público juramentado o traductor colegiado certificado. Permite idioma original para información técnica complementaria en folletos, instructivos, catálogos o similares. El documento de representación no integra esa excepción.", "regime": "32069", "topic": "Etapas, plazos y condiciones", "competency": "Selección", "difficulty": "intermediate", "curriculumVersion": "oece-2025-04-25", "competencyCode": "2", "subcompetencyCode": "2.2", "cognitiveLevel": "apply", "optionRationales": {"A": "La excepción para información técnica complementaria no abarca el documento de representación.", "B": "Se exige traducción por traductor público juramentado o colegiado certificado, no declaración del vendedor.", "C": "La excepción es específica y no comprende todos los documentos de una oferta.", "D": "La norma permite idioma original para el catálogo complementario, no para la representación."}, "reviewChecks": {"unambiguous": true, "distractors": true, "conditions": true, "exceptions": true, "sources": true}, "sourceCutoff": "2026-10-29", "origin": "IA:gemini:gemini-2.5-flash:lote:efaaf2b4-dfb4-4e72-b0ce-a78eebe51d81", "sources": [{"documentId": "8371bce1-f773-4ad8-8efa-1266276ae4ec", "chunkId": "c0f4c18d-7d43-47b2-a761-f373ee5c308e", "title": "Reglamento de la Ley N.° 32069 — texto actualizado al 09.01.2026", "article": "69", "pageStart": 38, "pageEnd": 39, "quote": ". Asi mismo, puede contener documentación que acredite el cumplimiento de las especificaciones técnicas, de haberse determinado así en la estrategia de contratación. 69.3. La oferta económica y sus subtotales se expresan en dos decimales y todos sus valores desagregados pueden ser expresados con más de dos decimales. 69.4. La oferta económica incluye todos los tributos, seguros, transporte, inspecciones, pruebas y, de ser el caso, los costos laborales conforme a la legislación vigente, así como cualquier otro concepto que pueda tener incidencia sobre el costo del bien, servicio en general, consultoría u obra a contratar. Los postores que gocen de alguna exoneración legal tributaria no incluyen en su oferta los tributos respectivos. 69.5. Los documentos que presentan los participantes en la fase de selección, incluyendo las ofertas, son presentadas en idioma español o con la respectiva traducción por traductor público juramentado o traductor colegiado certificado, salvo el caso de la información técnica complementaria contenida en folletos, instructivos, catálogos o similares, que puede ser presentada en el idioma original.", "version": "Texto actualizado al 09.01.2026", "sha256": "0ebe95b3e05661b80f73c060d6e6ce8dd17621ce34af9277c688dd67e5d99830"}], "status": "published", "reviewBasis": "Revisión asistida por IA el15/11/2026 por encargo y autorización expresa del administrador. Sustituye cuantía por ítems por regla documental de selección; se delimita catálogo complementario y se evita extender la excepción a cualquier documento técnico. Confirmado con texto completo del fragmento citado y contraste de objetivos con las 181 publicadas; la nueva decisión operativa no reutiliza el objetivo anterior. Se conserva ID, revisión actual, origen y corte; el sustento anterior se conserva en reviewBasis. Se usa el numeral citado sin mezclar las redacciones originales y modificadas que coexisten en otros numerales del documento. La aprobación es editorial asistida por IA y autorizada por el administrador. Objetivo: Separar la traducción exigible de documentos de la excepción para información técnica complementaria.. Evidencia: art. 69, chunk 81. Sin certificación oficial OECE ni revisión humana independiente; se conserva el corte documental declarado.", "confirmReview": true}, "estadoAnterior": "draft"}, {"numero": "Q098", "id": "1b4a10ea-5bfc-4e56-82b6-d2f0cc89d09d", "decision": "approve", "motivo": "Reemplaza habilitación progresiva por calificación sustantiva; se limita a experiencia del postor y no confunde documentación de promesa ni porcentajes de participación. Confirmado con texto completo del fragmento citado y contraste de objetivos con las 181 publicadas; la nueva decisión operativa no reutiliza el objetivo anterior. Se conserva ID, revisión actual, origen y corte; el sustento anterior se conserva en reviewBasis. Se usa el numeral citado sin mezclar las redacciones originales y modificadas que coexisten en otros numerales del documento. La aprobación es editorial asistida por IA y autorizada por el administrador.", "objetivo": "Seleccionar la experiencia computable de integrantes de un consorcio según ejecución conjunta del objeto.", "evidencia": [{"chunkId": "85238aa1-a1c3-4dc8-9ca6-babf5b343909", "chunk_index": 86, "article": "72", "quote": ". c) Experiencia del postor en la especialidad: referida a la destreza adquirida por el postor en el desempeño de las labores consideradas iguales o similares al objeto de contratación. En el caso de obras y consultoría de obras, dicha experiencia correspond e a la acreditada en la especialidad y subespecialidad conforme a lo dispuesto en el artículo 157. Las personas jurídicas resultantes de un proceso de reorganización societaria no pueden acreditar como experiencia del postor en la especialidad que le hubiesen transmitido como parte de dicha reorganización las personas jurídicas sancionadas con inhabilit ación vigente o definitiva. En el caso de consorcios, solo se considera la experiencia de aquellos integrantes que ejecutan conjuntamente el objeto del contrato. d) Condiciones de participación en consorcio: número máximo de consorciados en función a la naturaleza de la prestación, porcentaje mínimo de participación de cada consorciado y/o que el integrante del consorcio que acredite mayor experiencia cumpla con un determinado porcentaje de participación. e) Capacidad económica: condición obtenida a partir de la evaluación de los antecedentes financieros que demuestre que se encuentra posibilitado para cumplir con las obligaciones contractuales. Solo se aplica en procedimientos de selección con etapa de pre calificación. Se sustenta con el volumen de ventas, estados financieros auditados u otros que establezcan las bases estándar. 72.4. Las bases estándar determinan los tipos de requisitos de calificación a considerar dependiendo de la modalidad del procedimiento de selección."}], "input": {"id": "1b4a10ea-5bfc-4e56-82b6-d2f0cc89d09d", "revision": 1, "prompt": "En un consorcio, dos integrantes ejecutarán conjuntamente el objeto del contrato y un tercero solo aporta financiamiento, sin ejecutarlo. Para acreditar experiencia del postor en la especialidad, ¿qué experiencia se considera según el literal 72.3.c?", "options": [{"id": "A", "text": "Toda la de los tres integrantes por el solo hecho de integrar el consorcio."}, {"id": "B", "text": "Solo la de los integrantes que ejecutan conjuntamente el objeto del contrato."}, {"id": "C", "text": "Únicamente la del representante común, aunque no ejecute el objeto."}, {"id": "D", "text": "Solo la del integrante que financia, por asumir el riesgo económico."}], "correctOption": "B", "explanation": "El literal 72.3.c dispone que en consorcios solo se considera la experiencia de los integrantes que ejecutan conjuntamente el objeto del contrato. Se evalúa la experiencia del postor en la especialidad, sin sustituir los demás requisitos de calificación aplicables.", "regime": "32069", "topic": "Etapas, plazos y condiciones", "competency": "Selección", "difficulty": "intermediate", "curriculumVersion": "oece-2025-04-25", "competencyCode": "2", "subcompetencyCode": "2.2", "cognitiveLevel": "apply", "optionRationales": {"A": "La pertenencia formal al consorcio no basta para computar toda experiencia.", "B": "El literal 72.3.c restringe el cómputo a quienes ejecutan conjuntamente el objeto.", "C": "Ser representante común no es el criterio establecido para computar experiencia.", "D": "El aporte financiero sin ejecución no satisface el criterio de este literal."}, "reviewChecks": {"unambiguous": true, "distractors": true, "conditions": true, "exceptions": true, "sources": true}, "sourceCutoff": "2026-10-29", "origin": "IA:gemini:gemini-2.5-flash:lote:f5ad814e-6c61-4b59-8a95-cda7770e6e8d", "sources": [{"documentId": "8371bce1-f773-4ad8-8efa-1266276ae4ec", "chunkId": "85238aa1-a1c3-4dc8-9ca6-babf5b343909", "title": "Reglamento de la Ley N.° 32069 — texto actualizado al 09.01.2026", "article": "72", "pageStart": 40, "pageEnd": 41, "quote": ". c) Experiencia del postor en la especialidad: referida a la destreza adquirida por el postor en el desempeño de las labores consideradas iguales o similares al objeto de contratación. En el caso de obras y consultoría de obras, dicha experiencia correspond e a la acreditada en la especialidad y subespecialidad conforme a lo dispuesto en el artículo 157. Las personas jurídicas resultantes de un proceso de reorganización societaria no pueden acreditar como experiencia del postor en la especialidad que le hubiesen transmitido como parte de dicha reorganización las personas jurídicas sancionadas con inhabilit ación vigente o definitiva. En el caso de consorcios, solo se considera la experiencia de aquellos integrantes que ejecutan conjuntamente el objeto del contrato. d) Condiciones de participación en consorcio: número máximo de consorciados en función a la naturaleza de la prestación, porcentaje mínimo de participación de cada consorciado y/o que el integrante del consorcio que acredite mayor experiencia cumpla con un determinado porcentaje de participación. e) Capacidad económica: condición obtenida a partir de la evaluación de los antecedentes financieros que demuestre que se encuentra posibilitado para cumplir con las obligaciones contractuales. Solo se aplica en procedimientos de selección con etapa de pre calificación. Se sustenta con el volumen de ventas, estados financieros auditados u otros que establezcan las bases estándar. 72.4. Las bases estándar determinan los tipos de requisitos de calificación a considerar dependiendo de la modalidad del procedimiento de selección.", "version": "Texto actualizado al 09.01.2026", "sha256": "0ebe95b3e05661b80f73c060d6e6ce8dd17621ce34af9277c688dd67e5d99830"}], "status": "published", "reviewBasis": "Revisión asistida por IA el15/11/2026 por encargo y autorización expresa del administrador. Reemplaza habilitación progresiva por calificación sustantiva; se limita a experiencia del postor y no confunde documentación de promesa ni porcentajes de participación. Confirmado con texto completo del fragmento citado y contraste de objetivos con las 181 publicadas; la nueva decisión operativa no reutiliza el objetivo anterior. Se conserva ID, revisión actual, origen y corte; el sustento anterior se conserva en reviewBasis. Se usa el numeral citado sin mezclar las redacciones originales y modificadas que coexisten en otros numerales del documento. La aprobación es editorial asistida por IA y autorizada por el administrador. Objetivo: Seleccionar la experiencia computable de integrantes de un consorcio según ejecución conjunta del objeto.. Evidencia: art. 72, chunk 86. Sin certificación oficial OECE ni revisión humana independiente; se conserva el corte documental declarado.", "confirmReview": true}, "estadoAnterior": "draft"}, {"numero": "Q101", "id": "84dc0b4a-4c32-4fc1-ba35-cea77fa723a1", "decision": "approve", "motivo": "Sustituye jurado/DEC por límite de requisito de calificación; no se cuestiona aquí selección de evaluador ni habilitaciones de capacidad legal. Confirmado con texto completo del fragmento citado y contraste de objetivos con las 181 publicadas; la nueva decisión operativa no reutiliza el objetivo anterior. Se conserva ID, revisión actual, origen y corte; el sustento anterior se conserva en reviewBasis. Se usa el numeral citado sin mezclar las redacciones originales y modificadas que coexisten en otros numerales del documento. La aprobación es editorial asistida por IA y autorizada por el administrador.", "objetivo": "Detectar uso indebido de capacidad económica en un procedimiento sin precalificación.", "evidencia": [{"chunkId": "85238aa1-a1c3-4dc8-9ca6-babf5b343909", "chunk_index": 86, "article": "72", "quote": ". c) Experiencia del postor en la especialidad: referida a la destreza adquirida por el postor en el desempeño de las labores consideradas iguales o similares al objeto de contratación. En el caso de obras y consultoría de obras, dicha experiencia correspond e a la acreditada en la especialidad y subespecialidad conforme a lo dispuesto en el artículo 157. Las personas jurídicas resultantes de un proceso de reorganización societaria no pueden acreditar como experiencia del postor en la especialidad que le hubiesen transmitido como parte de dicha reorganización las personas jurídicas sancionadas con inhabilit ación vigente o definitiva. En el caso de consorcios, solo se considera la experiencia de aquellos integrantes que ejecutan conjuntamente el objeto del contrato. d) Condiciones de participación en consorcio: número máximo de consorciados en función a la naturaleza de la prestación, porcentaje mínimo de participación de cada consorciado y/o que el integrante del consorcio que acredite mayor experiencia cumpla con un determinado porcentaje de participación. e) Capacidad económica: condición obtenida a partir de la evaluación de los antecedentes financieros que demuestre que se encuentra posibilitado para cumplir con las obligaciones contractuales. Solo se aplica en procedimientos de selección con etapa de pre calificación. Se sustenta con el volumen de ventas, estados financieros auditados u otros que establezcan las bases estándar. 72.4. Las bases estándar determinan los tipos de requisitos de calificación a considerar dependiendo de la modalidad del procedimiento de selección."}], "input": {"id": "84dc0b4a-4c32-4fc1-ba35-cea77fa723a1", "revision": 1, "prompt": "En un procedimiento sin etapa de precalificación se pretende exigir estados financieros auditados como requisito de capacidad económica del literal 72.3.e. ¿Qué decisión corresponde respecto de ese requisito?", "options": [{"id": "A", "text": "Exigirlo siempre porque todo contrato implica obligaciones económicas."}, {"id": "B", "text": "Aplicarlo únicamente si el postor es un consorcio, aunque no haya precalificación."}, {"id": "C", "text": "No aplicarlo como capacidad económica, pues ese tipo de requisito solo se aplica en procedimientos con precalificación."}, {"id": "D", "text": "Cambiarle el nombre a capacidad legal para mantener la misma exigencia financiera."}], "correctOption": "C", "explanation": "El literal 72.3.e reserva la capacidad económica a procedimientos con etapa de precalificación y la vincula con antecedentes financieros. No corresponde trasladar ese requisito al procedimiento descrito ni mantenerlo mediante un cambio de denominación.", "regime": "32069", "topic": "Etapas, plazos y condiciones", "competency": "Selección", "difficulty": "intermediate", "curriculumVersion": "oece-2025-04-25", "competencyCode": "2", "subcompetencyCode": "2.2", "cognitiveLevel": "apply", "optionRationales": {"A": "La existencia de obligaciones económicas no elimina la limitación expresa.", "B": "La norma no crea una excepción por el solo hecho de ser consorcio.", "C": "El literal 72.3.e limita este requisito a procedimientos con precalificación.", "D": "La capacidad legal se refiere a habilitaciones para la actividad, no a renombrar antecedentes financieros."}, "reviewChecks": {"unambiguous": true, "distractors": true, "conditions": true, "exceptions": true, "sources": true}, "sourceCutoff": "2026-10-29", "origin": "IA:gemini:gemini-2.5-flash:lote:7b67c82f-7a38-47ba-90ee-48083b2ece62", "sources": [{"documentId": "8371bce1-f773-4ad8-8efa-1266276ae4ec", "chunkId": "85238aa1-a1c3-4dc8-9ca6-babf5b343909", "title": "Reglamento de la Ley N.° 32069 — texto actualizado al 09.01.2026", "article": "72", "pageStart": 40, "pageEnd": 41, "quote": ". c) Experiencia del postor en la especialidad: referida a la destreza adquirida por el postor en el desempeño de las labores consideradas iguales o similares al objeto de contratación. En el caso de obras y consultoría de obras, dicha experiencia correspond e a la acreditada en la especialidad y subespecialidad conforme a lo dispuesto en el artículo 157. Las personas jurídicas resultantes de un proceso de reorganización societaria no pueden acreditar como experiencia del postor en la especialidad que le hubiesen transmitido como parte de dicha reorganización las personas jurídicas sancionadas con inhabilit ación vigente o definitiva. En el caso de consorcios, solo se considera la experiencia de aquellos integrantes que ejecutan conjuntamente el objeto del contrato. d) Condiciones de participación en consorcio: número máximo de consorciados en función a la naturaleza de la prestación, porcentaje mínimo de participación de cada consorciado y/o que el integrante del consorcio que acredite mayor experiencia cumpla con un determinado porcentaje de participación. e) Capacidad económica: condición obtenida a partir de la evaluación de los antecedentes financieros que demuestre que se encuentra posibilitado para cumplir con las obligaciones contractuales. Solo se aplica en procedimientos de selección con etapa de pre calificación. Se sustenta con el volumen de ventas, estados financieros auditados u otros que establezcan las bases estándar. 72.4. Las bases estándar determinan los tipos de requisitos de calificación a considerar dependiendo de la modalidad del procedimiento de selección.", "version": "Texto actualizado al 09.01.2026", "sha256": "0ebe95b3e05661b80f73c060d6e6ce8dd17621ce34af9277c688dd67e5d99830"}], "status": "published", "reviewBasis": "Revisión asistida por IA el15/11/2026 por encargo y autorización expresa del administrador. Sustituye jurado/DEC por límite de requisito de calificación; no se cuestiona aquí selección de evaluador ni habilitaciones de capacidad legal. Confirmado con texto completo del fragmento citado y contraste de objetivos con las 181 publicadas; la nueva decisión operativa no reutiliza el objetivo anterior. Se conserva ID, revisión actual, origen y corte; el sustento anterior se conserva en reviewBasis. Se usa el numeral citado sin mezclar las redacciones originales y modificadas que coexisten en otros numerales del documento. La aprobación es editorial asistida por IA y autorizada por el administrador. Objetivo: Detectar uso indebido de capacidad económica en un procedimiento sin precalificación.. Evidencia: art. 72, chunk 86. Sin certificación oficial OECE ni revisión humana independiente; se conserva el corte documental declarado.", "confirmReview": true}, "estadoAnterior": "draft"}, {"numero": "Q107", "id": "ee7fe2c8-47a9-4d7e-9510-d5e442ac8645", "decision": "approve", "motivo": "Reemplaza incentivo laboral por corrección económica de selección; el caso se limita a precios unitarios y error aritmético, no a cambio de contenido esencial. Confirmado con texto completo del fragmento citado y contraste de objetivos con las 181 publicadas; la nueva decisión operativa no reutiliza el objetivo anterior. Se conserva ID, revisión actual, origen y corte; el sustento anterior se conserva en reviewBasis. Se usa el numeral citado sin mezclar las redacciones originales y modificadas que coexisten en otros numerales del documento. La aprobación es editorial asistida por IA y autorizada por el administrador.", "objetivo": "Corregir errores aritméticos sin alterar precios unitarios ofertados.", "evidencia": [{"chunkId": "6cbadd98-5c39-4967-b582-9d359b6caf00", "chunk_index": 94, "article": "78", "quote": ". En el caso de errores u omisiones en documentos emitidos por entidades públicas o privados ejerciendo función pública, o la omisión de su presentación, estos son subsanables, siempre que hayan sido emitidos con anterioridad a la fecha establecida para la presentación de ofertas, tales como autorizaciones, permisos, títulos, constancias, certificaciones y/o documentos que acrediten estar inscrito o integrar un registro, y otros de naturaleza análoga.\" 78.3. En las modalidades de pago a precios unitarios, esquema mixto, pago por consumo y tarifas, cuando se advierta errores aritméticos, corresponde su corrección a los evaluadores, debiendo constar dicha rectificación en el acta respectiva; dicha correcci ón no implica la variación de los precios unitarios ofertados. 78.4. Cuando se requiera subsanación, la oferta continúa vigente para todo efecto, a condición de la efectiva subsanación dentro el plazo de dos días hábiles contabilizados desde el día siguiente de la notificación al postor, pudiendo la entidad contratant e otorgar al postor un plazo adicional de dos días hábiles para la subsanación pertinente a solicitud del postor. La solicitud de ampliación de plazo se otorga en un plazo no mayor de dos días hábiles de recibida, caso contrario se considera autorizada."}], "input": {"id": "ee7fe2c8-47a9-4d7e-9510-d5e442ac8645", "revision": 1, "prompt": "En una oferta con modalidad de pago a precios unitarios, la multiplicación de cantidad por precio unitario contiene un error aritmético. El precio unitario ofertado es claro. Según el numeral 78.3, ¿qué deben hacer los evaluadores?", "options": [{"id": "A", "text": "Modificar cantidad y precio unitario hasta obtener el monto presupuestado."}, {"id": "B", "text": "Omitir toda corrección porque los errores aritméticos nunca se rectifican."}, {"id": "C", "text": "Permitir al postor cambiar el precio unitario para conservar el total erróneo."}, {"id": "D", "text": "Corregir el cálculo, dejar constancia en acta y mantener el precio unitario ofertado."}], "correctOption": "D", "explanation": "En precios unitarios, esquema mixto, pago por consumo y tarifas, el numeral 78.3 encarga a los evaluadores corregir errores aritméticos y documentarlos en el acta respectiva. La corrección no implica variar los precios unitarios ofertados.", "regime": "32069", "topic": "Etapas, plazos y condiciones", "competency": "Selección", "difficulty": "intermediate", "curriculumVersion": "oece-2025-04-25", "competencyCode": "2", "subcompetencyCode": "2.2", "cognitiveLevel": "apply", "optionRationales": {"A": "Ajustar cantidades y unitarios excede la rectificación del error de cálculo.", "B": "La norma prevé expresamente esta corrección para la modalidad indicada.", "C": "La corrección aritmética no permite modificar los precios unitarios ofertados.", "D": "El numeral 78.3 encarga la corrección a evaluadores, con acta y sin variar unitarios."}, "reviewChecks": {"unambiguous": true, "distractors": true, "conditions": true, "exceptions": true, "sources": true}, "sourceCutoff": "2026-10-29", "origin": "IA:gemini:gemini-2.5-flash:lote:1abbba91-7d99-4d87-a2e2-5d035a0f3c0d", "sources": [{"documentId": "8371bce1-f773-4ad8-8efa-1266276ae4ec", "chunkId": "6cbadd98-5c39-4967-b582-9d359b6caf00", "title": "Reglamento de la Ley N.° 32069 — texto actualizado al 09.01.2026", "article": "78", "pageStart": 45, "pageEnd": 45, "quote": ". En el caso de errores u omisiones en documentos emitidos por entidades públicas o privados ejerciendo función pública, o la omisión de su presentación, estos son subsanables, siempre que hayan sido emitidos con anterioridad a la fecha establecida para la presentación de ofertas, tales como autorizaciones, permisos, títulos, constancias, certificaciones y/o documentos que acrediten estar inscrito o integrar un registro, y otros de naturaleza análoga.\" 78.3. En las modalidades de pago a precios unitarios, esquema mixto, pago por consumo y tarifas, cuando se advierta errores aritméticos, corresponde su corrección a los evaluadores, debiendo constar dicha rectificación en el acta respectiva; dicha correcci ón no implica la variación de los precios unitarios ofertados. 78.4. Cuando se requiera subsanación, la oferta continúa vigente para todo efecto, a condición de la efectiva subsanación dentro el plazo de dos días hábiles contabilizados desde el día siguiente de la notificación al postor, pudiendo la entidad contratant e otorgar al postor un plazo adicional de dos días hábiles para la subsanación pertinente a solicitud del postor. La solicitud de ampliación de plazo se otorga en un plazo no mayor de dos días hábiles de recibida, caso contrario se considera autorizada.", "version": "Texto actualizado al 09.01.2026", "sha256": "0ebe95b3e05661b80f73c060d6e6ce8dd17621ce34af9277c688dd67e5d99830"}], "status": "published", "reviewBasis": "Revisión asistida por IA el15/11/2026 por encargo y autorización expresa del administrador. Reemplaza incentivo laboral por corrección económica de selección; el caso se limita a precios unitarios y error aritmético, no a cambio de contenido esencial. Confirmado con texto completo del fragmento citado y contraste de objetivos con las 181 publicadas; la nueva decisión operativa no reutiliza el objetivo anterior. Se conserva ID, revisión actual, origen y corte; el sustento anterior se conserva en reviewBasis. Se usa el numeral citado sin mezclar las redacciones originales y modificadas que coexisten en otros numerales del documento. La aprobación es editorial asistida por IA y autorizada por el administrador. Objetivo: Corregir errores aritméticos sin alterar precios unitarios ofertados.. Evidencia: art. 78, chunk 94. Sin certificación oficial OECE ni revisión humana independiente; se conserva el corte documental declarado.", "confirmReview": true}, "estadoAnterior": "draft"}, {"numero": "Q117", "id": "f32677de-f0bb-4a57-a4f5-21ac5a3d19ba", "decision": "approve", "motivo": "Sustituye constancia de capacidad libre por acceso documental; distingue buena pro de consentimiento y excluye expresamente ofertas no admitidas e información protegida. Confirmado con texto completo del fragmento citado y contraste de objetivos con las 181 publicadas; la nueva decisión operativa no reutiliza el objetivo anterior. Se conserva ID, revisión actual, origen y corte; el sustento anterior se conserva en reviewBasis. Se usa el numeral citado sin mezclar las redacciones originales y modificadas que coexisten en otros numerales del documento. La aprobación es editorial asistida por IA y autorizada por el administrador.", "objetivo": "Atender acceso al expediente luego de buena pro respetando información excluida.", "evidencia": [{"chunkId": "cc8c9436-7e03-4e47-aa64-4b1a30ab1268", "chunk_index": 95, "article": "79", "quote": "Artículo 79. Acceso a la información 79.1. Durante la evaluación de las ofertas no se da a conocer información alguna acerca del análisis, subsanación y evaluación de las ofertas hasta que se haya publicado el otorgamiento de la buena pro.\n\nReglamento de la Ley Nº 32069, Ley General de Contrataciones Públicas Página 46 de 249 79.2. Una vez otorgada la buena pro, la DEC está en la obligación de permitir el acceso de los participantes y postores al expediente de contratación, salvo la información calificada como secreta, confidencial o reservada por la normativa de la materia, as í como aquella correspondiente a las ofertas que no fueron admitidas, a más tardar dentro del día hábil siguiente de haberse solicitado por escrito. SUBCAPÍTULO 5 Otorgamiento de la buena pro"}], "input": {"id": "f32677de-f0bb-4a57-a4f5-21ac5a3d19ba", "revision": 1, "prompt": "Otorgada la buena pro, un participante solicita por escrito acceso al expediente. Pide también ofertas no admitidas e información calificada como confidencial por la normativa aplicable. Según el numeral 79.2, ¿qué debe hacer la DEC?", "options": [{"id": "A", "text": "Permitir acceso a la parte no excluida a más tardar el día hábil siguiente de la solicitud, reservando la información indicada."}, {"id": "B", "text": "Otorgar acceso solo cuando el ganador firme el contrato."}, {"id": "C", "text": "Negar todo acceso hasta que quede consentida la buena pro."}, {"id": "D", "text": "Dar acceso íntegro, incluidas ofertas no admitidas y documentación confidencial."}], "correctOption": "A", "explanation": "Otorgada la buena pro, la DEC permite acceso a participantes y postores a más tardar dentro del día hábil siguiente de la solicitud escrita. El numeral 79.2 excluye información secreta, confidencial o reservada y la correspondiente a ofertas no admitidas.", "regime": "32069", "topic": "Etapas, plazos y condiciones", "competency": "Selección", "difficulty": "intermediate", "curriculumVersion": "oece-2025-04-25", "competencyCode": "2", "subcompetencyCode": "2.2", "cognitiveLevel": "apply", "optionRationales": {"A": "El numeral 79.2 establece plazo inmediato y excepciones expresas de acceso.", "B": "La suscripción del contrato no es el hito exigido para este acceso.", "C": "La regla permite acceso una vez otorgada la buena pro, sin esperar consentimiento.", "D": "Las ofertas no admitidas y la información protegida están exceptuadas."}, "reviewChecks": {"unambiguous": true, "distractors": true, "conditions": true, "exceptions": true, "sources": true}, "sourceCutoff": "2026-10-29", "origin": "IA:gemini:gemini-2.5-flash:lote:2abfcaa1-62e4-4225-9f61-edc57bde04ca", "sources": [{"documentId": "8371bce1-f773-4ad8-8efa-1266276ae4ec", "chunkId": "cc8c9436-7e03-4e47-aa64-4b1a30ab1268", "title": "Reglamento de la Ley N.° 32069 — texto actualizado al 09.01.2026", "article": "79", "pageStart": 45, "pageEnd": 46, "quote": "Artículo 79. Acceso a la información 79.1. Durante la evaluación de las ofertas no se da a conocer información alguna acerca del análisis, subsanación y evaluación de las ofertas hasta que se haya publicado el otorgamiento de la buena pro.\n\nReglamento de la Ley Nº 32069, Ley General de Contrataciones Públicas Página 46 de 249 79.2. Una vez otorgada la buena pro, la DEC está en la obligación de permitir el acceso de los participantes y postores al expediente de contratación, salvo la información calificada como secreta, confidencial o reservada por la normativa de la materia, as í como aquella correspondiente a las ofertas que no fueron admitidas, a más tardar dentro del día hábil siguiente de haberse solicitado por escrito. SUBCAPÍTULO 5 Otorgamiento de la buena pro", "version": "Texto actualizado al 09.01.2026", "sha256": "0ebe95b3e05661b80f73c060d6e6ce8dd17621ce34af9277c688dd67e5d99830"}], "status": "published", "reviewBasis": "Revisión asistida por IA el15/11/2026 por encargo y autorización expresa del administrador. Sustituye constancia de capacidad libre por acceso documental; distingue buena pro de consentimiento y excluye expresamente ofertas no admitidas e información protegida. Confirmado con texto completo del fragmento citado y contraste de objetivos con las 181 publicadas; la nueva decisión operativa no reutiliza el objetivo anterior. Se conserva ID, revisión actual, origen y corte; el sustento anterior se conserva en reviewBasis. Se usa el numeral citado sin mezclar las redacciones originales y modificadas que coexisten en otros numerales del documento. La aprobación es editorial asistida por IA y autorizada por el administrador. Objetivo: Atender acceso al expediente luego de buena pro respetando información excluida.. Evidencia: art. 79, chunk 95. Sin certificación oficial OECE ni revisión humana independiente; se conserva el corte documental declarado.", "confirmReview": true}, "estadoAnterior": "draft"}, {"numero": "Q118", "id": "f6c1f53f-0c81-43e1-be1f-1e1324254539", "decision": "approve", "motivo": "Reemplaza fuente de indagación de mercado por decisión de desempate; se evalúa el primer criterio y no se llega a preferencias MYPE ni sorteo mientras resuelva el puntaje técnico. Confirmado con texto completo del fragmento citado y contraste de objetivos con las 181 publicadas; la nueva decisión operativa no reutiliza el objetivo anterior. Se conserva ID, revisión actual, origen y corte; el sustento anterior se conserva en reviewBasis. Se usa el numeral citado sin mezclar las redacciones originales y modificadas que coexisten en otros numerales del documento. La aprobación es editorial asistida por IA y autorizada por el administrador.", "objetivo": "Resolver empate total aplicando primero el mejor puntaje técnico.", "evidencia": [{"chunkId": "5600f03b-7e9c-4b40-b372-d4f7d42aa0cf", "chunk_index": 97, "article": "81", "quote": "Artículo 81. Criterios en caso de empate Cuando dos o más ofertas empaten, el otorgamiento de la buena pro se efectúa observando los siguientes criterios, en el siguiente orden de prelación: a) La buena pro se otorga al postor que haya obtenido el mejor puntaje técnico. b) La buena pro se otorga al postor que sea microempresa o pequeña empresa integrada por personas con discapacidad o a un consorcio conformado en su totalidad por estas empresas, siempre que acredite tener tales condiciones de acuerdo con la normativa de l a materia. c) La buena pro se otorga al postor que sea microempresa o pequeña empresa o a un consorcio conformado en su totalidad por éstas, siempre que estén debidamente acreditadas de acuerdo con la normativa de la materia. d) A través de sorteo."}], "input": {"id": "f6c1f53f-0c81-43e1-be1f-1e1324254539", "revision": 1, "prompt": "Dos ofertas empatan en puntaje total. Una obtuvo mejor puntaje técnico; la otra pertenece a una MYPE debidamente acreditada. Aplicando el orden del artículo 81, ¿cómo se resuelve el empate?", "options": [{"id": "A", "text": "Otorgarla directamente a la MYPE, aunque su puntaje técnico sea menor."}, {"id": "B", "text": "Otorgar la buena pro a la oferta con mejor puntaje técnico."}, {"id": "C", "text": "Realizar inmediatamente un sorteo sin aplicar otros criterios."}, {"id": "D", "text": "Pedir a ambos postores nuevos precios como primer desempate."}], "correctOption": "B", "explanation": "El artículo 81 ordena aplicar primero el mejor puntaje técnico. Al resolverse el empate con ese criterio, no corresponde pasar a las preferencias por condición empresarial ni al sorteo. La sola condición de MYPE no altera esa prelación.", "regime": "32069", "topic": "Evaluación, principios y criterios", "competency": "Selección", "difficulty": "intermediate", "curriculumVersion": "oece-2025-04-25", "competencyCode": "2", "subcompetencyCode": "2.3", "cognitiveLevel": "apply", "optionRationales": {"A": "La preferencia MYPE no desplaza al criterio técnico que precede en el orden.", "B": "El mejor puntaje técnico ocupa el primer lugar en la prelación del artículo 81.", "C": "El sorteo se ubica al final de la prelación, no al inicio.", "D": "Solicitar nuevos precios no es el primer criterio de desempate previsto."}, "reviewChecks": {"unambiguous": true, "distractors": true, "conditions": true, "exceptions": true, "sources": true}, "sourceCutoff": "2026-10-29", "origin": "IA:gemini:gemini-2.5-flash:lote:f7c1cec8-369f-4af2-bde4-8a008cb40c87", "sources": [{"documentId": "8371bce1-f773-4ad8-8efa-1266276ae4ec", "chunkId": "5600f03b-7e9c-4b40-b372-d4f7d42aa0cf", "title": "Reglamento de la Ley N.° 32069 — texto actualizado al 09.01.2026", "article": "81", "pageStart": 46, "pageEnd": 46, "quote": "Artículo 81. Criterios en caso de empate Cuando dos o más ofertas empaten, el otorgamiento de la buena pro se efectúa observando los siguientes criterios, en el siguiente orden de prelación: a) La buena pro se otorga al postor que haya obtenido el mejor puntaje técnico. b) La buena pro se otorga al postor que sea microempresa o pequeña empresa integrada por personas con discapacidad o a un consorcio conformado en su totalidad por estas empresas, siempre que acredite tener tales condiciones de acuerdo con la normativa de l a materia. c) La buena pro se otorga al postor que sea microempresa o pequeña empresa o a un consorcio conformado en su totalidad por éstas, siempre que estén debidamente acreditadas de acuerdo con la normativa de la materia. d) A través de sorteo.", "version": "Texto actualizado al 09.01.2026", "sha256": "0ebe95b3e05661b80f73c060d6e6ce8dd17621ce34af9277c688dd67e5d99830"}], "status": "published", "reviewBasis": "Revisión asistida por IA el15/11/2026 por encargo y autorización expresa del administrador. Reemplaza fuente de indagación de mercado por decisión de desempate; se evalúa el primer criterio y no se llega a preferencias MYPE ni sorteo mientras resuelva el puntaje técnico. Confirmado con texto completo del fragmento citado y contraste de objetivos con las 181 publicadas; la nueva decisión operativa no reutiliza el objetivo anterior. Se conserva ID, revisión actual, origen y corte; el sustento anterior se conserva en reviewBasis. Se usa el numeral citado sin mezclar las redacciones originales y modificadas que coexisten en otros numerales del documento. La aprobación es editorial asistida por IA y autorizada por el administrador. Objetivo: Resolver empate total aplicando primero el mejor puntaje técnico.. Evidencia: art. 81, chunk 97. Sin certificación oficial OECE ni revisión humana independiente; se conserva el corte documental declarado.", "confirmReview": true}, "estadoAnterior": "draft"}, {"numero": "Q124", "id": "73effbbe-fd8b-467d-94ee-b159b4720861", "decision": "approve", "motivo": "Se corrige el encaje de Q124 en 2.4: la verificación documental posterior no evaluaba directamente consentimiento o firmeza. El nuevo caso aplica exclusivamente el numeral 82.2 modificado a una sola oferta presentada: consentimiento el mismo día de notificación y registro al día siguiente. Se confirma la regla con el chunk 98, artículo 82, separando la redacción modificada de la original que no explicitaba el registro. El registro documenta un consentimiento ya producido; no lo crea ni lo traslada a la firma del contrato. Se excluye el supuesto de varias ofertas aunque solo una sea admitida. Objetivo distinto de Q105, que compara dos ofertas sin apelación con apelación resuelta. Se mantienen ID, revisión, origen y sourceCutoff, sin inferir vigencia posterior al corte. Aprobación editorial asistida por IA autorizada por el administrador; no aprobación oficial OECE ni revisión humana independiente.", "objetivo": "Distinguir la fecha en que se produce el consentimiento con una única oferta de su registro en Pladicop al día siguiente, sin atribuir al registro efecto constitutivo.", "evidencia": [{"chunkId": "c32f3a5a-70eb-487a-8f0e-c88ac2151ece", "chunk_index": 98, "article": "82", "quote": "82.2. En caso de que se haya presentado una sola oferta, el consentimiento de la buena pro se produce el mismo día de la notificación de su otorgamiento y se registra en la Pladicop al día siguiente ."}], "input": {"id": "73effbbe-fd8b-467d-94ee-b159b4720861", "revision": 1, "prompt": "En un procedimiento se presentó una única oferta, no varias ofertas de las cuales solo una fue admitida. La buena pro se notifica un martes y la DEC programa el registro del consentimiento en Pladicop para el miércoles siguiente. Aplicando el numeral 82.2 modificado del Reglamento, ¿cuándo se produce el consentimiento y qué función cumple el registro del miércoles?", "options": [{"id": "A", "text": "El consentimiento se produce el miércoles porque su registro en Pladicop lo crea."}, {"id": "B", "text": "El consentimiento se produce al vencer el plazo de apelación, como si se hubieran presentado varias ofertas."}, {"id": "C", "text": "El consentimiento se produce el martes, día de la notificación; el miércoles se registra un consentimiento ya producido."}, {"id": "D", "text": "El consentimiento se produce al suscribir el contrato; el registro previo solo anuncia una intención de contratar."}], "correctOption": "C", "explanation": "El numeral 82.2 modificado distingue dos momentos cuando se ha presentado una sola oferta: el consentimiento se produce el mismo día de la notificación del otorgamiento de la buena pro y se registra en Pladicop al día siguiente. Por ello, en el caso se produce el martes y se registra el miércoles. El registro no crea el consentimiento ni retrasa su fecha; tampoco se espera a la firma del contrato. El supuesto de varias ofertas se regula separadamente en el numeral 82.1 y no es el planteado.", "regime": "32069", "topic": "Consentimiento y firmeza de la buena pro", "competency": "Selección", "difficulty": "intermediate", "curriculumVersion": "oece-2025-04-25", "competencyCode": "2", "subcompetencyCode": "2.4", "cognitiveLevel": "apply", "optionRationales": {"A": "Confunde el registro del día siguiente con el nacimiento del consentimiento, que el 82.2 sitúa el mismo día de la notificación.", "B": "Traslada a una sola oferta la espera del plazo de apelación propia del supuesto de varias ofertas del 82.1.", "C": "Distingue correctamente la producción del consentimiento el martes de su registro el miércoles, sin otorgar al registro efecto constitutivo.", "D": "La firma del contrato no es el hito de consentimiento previsto en el 82.2; este se produce con la notificación en el supuesto descrito."}, "reviewChecks": {"unambiguous": true, "distractors": true, "conditions": true, "exceptions": true, "sources": true}, "sourceCutoff": "2026-10-29", "origin": "IA:gemini:gemini-2.5-flash:lote:0ed4dc43-030c-41e4-ad25-b1cb95078036", "sources": [{"documentId": "8371bce1-f773-4ad8-8efa-1266276ae4ec", "chunkId": "c32f3a5a-70eb-487a-8f0e-c88ac2151ece", "title": "Reglamento de la Ley N.° 32069 — texto actualizado al 09.01.2026", "article": "82", "pageStart": 46, "pageEnd": 46, "quote": "82.2. En caso de que se haya presentado una sola oferta, el consentimiento de la buena pro se produce el mismo día de la notificación de su otorgamiento y se registra en la Pladicop al día siguiente .", "version": "Texto actualizado al 09.01.2026", "sha256": "0ebe95b3e05661b80f73c060d6e6ce8dd17621ce34af9277c688dd67e5d99830"}], "status": "published", "reviewBasis": "Revisión asistida por IA el15/11/2026 por encargo y autorización expresa del administrador. Se corrige el encaje de Q124 en 2.4: la verificación documental posterior no evaluaba directamente consentimiento o firmeza. El nuevo caso aplica exclusivamente el numeral 82.2 modificado a una sola oferta presentada: consentimiento el mismo día de notificación y registro al día siguiente. Se confirma la regla con el chunk 98, artículo 82, separando la redacción modificada de la original que no explicitaba el registro. El registro documenta un consentimiento ya producido; no lo crea ni lo traslada a la firma del contrato. Se excluye el supuesto de varias ofertas aunque solo una sea admitida. Objetivo distinto de Q105, que compara dos ofertas sin apelación con apelación resuelta. Se mantienen ID, revisión, origen y sourceCutoff, sin inferir vigencia posterior al corte. Aprobación editorial asistida por IA autorizada por el administrador; no aprobación oficial OECE ni revisión humana independiente. Objetivo: Distinguir la fecha en que se produce el consentimiento con una única oferta de su registro en Pladicop al día siguiente, sin atribuir al registro efecto constitutivo.. Evidencia: art. 82, chunk 98. Sin certificación oficial OECE ni revisión humana independiente; se conserva el corte documental declarado.", "confirmReview": true}, "estadoAnterior": "draft"}, {"numero": "Q128", "id": "fe17a562-9116-4341-930d-845b14920a0f", "decision": "approve", "motivo": "Sustituye devolución por denegatoria ficta por excepción de competencia; se trata de cancelación de procedimiento competitivo y no de asignar competencia por monto del ítem. Confirmado con texto completo del fragmento citado y contraste de objetivos con las 181 publicadas; la nueva decisión operativa no reutiliza el objetivo anterior. Se conserva ID, revisión actual, origen y corte; el sustento anterior se conserva en reviewBasis. Se usa el numeral citado sin mezclar las redacciones originales y modificadas que coexisten en otros numerales del documento. La aprobación es editorial asistida por IA y autorizada por el administrador.", "objetivo": "Identificar competencia del TCP para impugnar cancelación independientemente de la cuantía.", "evidencia": [{"chunkId": "d432f673-3c57-4426-b754-f49307c47921", "chunk_index": 369, "article": "302", "quote": "Artículo 302. Competencia 302.1. Los recursos de apelación son conocidos y resueltos por el TCP y por la autoridad de la gestión administrativa, según corresponda. En el caso de la autoridad de gestión administrativa esta facultad es indelegable. 302.2. En los procedimientos de selección competitivos según relación de ítems, incluso los derivados de aquellos declarados desiertos, la cuantía total del procedimiento de selección original determina la autoridad ante la que se presenta el recurso de ap elación. 302.3. Con independencia de la cuantía del procedimiento de selección competitivo, la declaración de nulidad de oficio o la cancelación del procedimiento son impugnadas ante el TCP."}], "input": {"id": "fe17a562-9116-4341-930d-845b14920a0f", "revision": 1, "prompt": "La entidad cancela un procedimiento de selección competitivo de cuantía reducida. Un participante desea apelar esa cancelación y propone hacerlo ante la autoridad administrativa de la entidad por el monto. Según el numeral 302.3, ¿ante quién corresponde impugnar?", "options": [{"id": "A", "text": "Ante el área usuaria por ser quien originó la necesidad."}, {"id": "B", "text": "Ante el OECE mediante elevación de consultas a las bases."}, {"id": "C", "text": "Ante la autoridad administrativa de la entidad siempre que el monto sea reducido."}, {"id": "D", "text": "Ante el TCP, con independencia de la cuantía del procedimiento."}], "correctOption": "D", "explanation": "El numeral 302.3 establece que la declaración de nulidad de oficio y la cancelación del procedimiento competitivo son impugnadas ante el TCP con independencia de la cuantía. La propuesta de acudir a la entidad solo por el monto no aplica a esta cancelación.", "regime": "32069", "topic": "Resolución de apelaciones", "competency": "Selección", "difficulty": "intermediate", "curriculumVersion": "oece-2025-04-25", "competencyCode": "2", "subcompetencyCode": "2.8", "cognitiveLevel": "apply", "optionRationales": {"A": "El área usuaria no es la instancia de apelación prevista para cancelación.", "B": "La elevación de consultas a bases no sustituye la apelación de una cancelación.", "C": "El monto no desplaza la excepción expresa de competencia del numeral 302.3.", "D": "La cancelación y la nulidad de oficio se impugnan ante TCP cualquiera sea la cuantía."}, "reviewChecks": {"unambiguous": true, "distractors": true, "conditions": true, "exceptions": true, "sources": true}, "sourceCutoff": "2026-10-29", "origin": "IA:gemini:gemini-2.5-flash:lote:344c0736-21bd-45f5-858e-794a9b3d4c12", "sources": [{"documentId": "8371bce1-f773-4ad8-8efa-1266276ae4ec", "chunkId": "d432f673-3c57-4426-b754-f49307c47921", "title": "Reglamento de la Ley N.° 32069 — texto actualizado al 09.01.2026", "article": "302", "pageStart": 159, "pageEnd": 159, "quote": "Artículo 302. Competencia 302.1. Los recursos de apelación son conocidos y resueltos por el TCP y por la autoridad de la gestión administrativa, según corresponda. En el caso de la autoridad de gestión administrativa esta facultad es indelegable. 302.2. En los procedimientos de selección competitivos según relación de ítems, incluso los derivados de aquellos declarados desiertos, la cuantía total del procedimiento de selección original determina la autoridad ante la que se presenta el recurso de ap elación. 302.3. Con independencia de la cuantía del procedimiento de selección competitivo, la declaración de nulidad de oficio o la cancelación del procedimiento son impugnadas ante el TCP.", "version": "Texto actualizado al 09.01.2026", "sha256": "0ebe95b3e05661b80f73c060d6e6ce8dd17621ce34af9277c688dd67e5d99830"}], "status": "published", "reviewBasis": "Revisión asistida por IA el15/11/2026 por encargo y autorización expresa del administrador. Sustituye devolución por denegatoria ficta por excepción de competencia; se trata de cancelación de procedimiento competitivo y no de asignar competencia por monto del ítem. Confirmado con texto completo del fragmento citado y contraste de objetivos con las 181 publicadas; la nueva decisión operativa no reutiliza el objetivo anterior. Se conserva ID, revisión actual, origen y corte; el sustento anterior se conserva en reviewBasis. Se usa el numeral citado sin mezclar las redacciones originales y modificadas que coexisten en otros numerales del documento. La aprobación es editorial asistida por IA y autorizada por el administrador. Objetivo: Identificar competencia del TCP para impugnar cancelación independientemente de la cuantía.. Evidencia: art. 302, chunk 369. Sin certificación oficial OECE ni revisión humana independiente; se conserva el corte documental declarado.", "confirmReview": true}, "estadoAnterior": "draft"}, {"numero": "Q130", "id": "9915c0f9-0b5b-428d-a93a-470029f89531", "decision": "approve", "motivo": "Reemplaza perfeccionamiento sin observaciones por delimitación objetiva del recurso; no se niegan mecanismos distintos de apelación ni se confunde con impugnación de buena pro. Confirmado con texto completo del fragmento citado y contraste de objetivos con las 181 publicadas; la nueva decisión operativa no reutiliza el objetivo anterior. Se conserva ID, revisión actual, origen y corte; el sustento anterior se conserva en reviewBasis. Se usa el numeral citado sin mezclar las redacciones originales y modificadas que coexisten en otros numerales del documento. La aprobación es editorial asistida por IA y autorizada por el administrador.", "objetivo": "Reconocer que la integración de bases no es acto impugnable mediante apelación.", "evidencia": [{"chunkId": "933a7eb1-8739-4a15-9da3-ff34f0248418", "chunk_index": 370, "article": "303", "quote": "Artículo 303. Actos no impugnables No son impugnables:\n\nReglamento de la Ley Nº 32069, Ley General de Contrataciones Públicas Página 160 de 249 a) Los actos y actuaciones realizadas en la fase de actuaciones preparatorias, incluyendo la interacción con el mercado y la estrategia de contratación. b) Los actos y actuaciones realizadas en los procesos de contratación de contratos menores. c) Las bases y/o su integración. d) Las actuaciones referidas al registro de participantes. e) Los actos y actuaciones realizados en las etapas de negociación y diálogo competitivo. f) El puntaje en el factor de evaluación “diseño arquitectónico” en los concursos de proyectos arquitectónicos y urbanísticos. g) Los procedimientos no competitivos."}], "input": {"id": "9915c0f9-0b5b-428d-a93a-470029f89531", "revision": 1, "prompt": "Un participante pretende interponer apelación cuyo único objeto es cuestionar las bases integradas, sin impugnar otro acto. Según el artículo 303, ¿cuál es el diagnóstico respecto de esta vía?", "options": [{"id": "A", "text": "Las bases y su integración no son actos impugnables mediante este recurso."}, {"id": "B", "text": "La integración solo se apela cuando ya se suscribió el contrato."}, {"id": "C", "text": "La integración siempre se apela antes del otorgamiento de buena pro."}, {"id": "D", "text": "Las bases son apelables únicamente si el recurrente presenta garantía duplicada."}], "correctOption": "A", "explanation": "El literal 303.c excluye las bases y su integración de los actos impugnables mediante apelación. Esta regla delimita la vía consultada; no implica afirmar la inexistencia de otros mecanismos previstos para cuestionamientos a las bases.", "regime": "32069", "topic": "Interposición de apelaciones", "competency": "Selección", "difficulty": "intermediate", "curriculumVersion": "oece-2025-04-25", "competencyCode": "2", "subcompetencyCode": "2.7", "cognitiveLevel": "apply", "optionRationales": {"A": "El literal 303.c incluye expresamente las bases y su integración como no impugnables.", "B": "La firma del contrato no transforma las bases en acto impugnable por esta vía.", "C": "Adelantar el recurso no convierte las bases en un acto apelable.", "D": "La cuantía de una garantía no elimina la exclusión objetiva del acto."}, "reviewChecks": {"unambiguous": true, "distractors": true, "conditions": true, "exceptions": true, "sources": true}, "sourceCutoff": "2026-10-29", "origin": "IA:gemini:gemini-2.5-flash:lote:5a16eb86-b092-462d-82dc-01890efaa981", "sources": [{"documentId": "8371bce1-f773-4ad8-8efa-1266276ae4ec", "chunkId": "933a7eb1-8739-4a15-9da3-ff34f0248418", "title": "Reglamento de la Ley N.° 32069 — texto actualizado al 09.01.2026", "article": "303", "pageStart": 159, "pageEnd": 160, "quote": "Artículo 303. Actos no impugnables No son impugnables:\n\nReglamento de la Ley Nº 32069, Ley General de Contrataciones Públicas Página 160 de 249 a) Los actos y actuaciones realizadas en la fase de actuaciones preparatorias, incluyendo la interacción con el mercado y la estrategia de contratación. b) Los actos y actuaciones realizadas en los procesos de contratación de contratos menores. c) Las bases y/o su integración. d) Las actuaciones referidas al registro de participantes. e) Los actos y actuaciones realizados en las etapas de negociación y diálogo competitivo. f) El puntaje en el factor de evaluación “diseño arquitectónico” en los concursos de proyectos arquitectónicos y urbanísticos. g) Los procedimientos no competitivos.", "version": "Texto actualizado al 09.01.2026", "sha256": "0ebe95b3e05661b80f73c060d6e6ce8dd17621ce34af9277c688dd67e5d99830"}], "status": "published", "reviewBasis": "Revisión asistida por IA el15/11/2026 por encargo y autorización expresa del administrador. Reemplaza perfeccionamiento sin observaciones por delimitación objetiva del recurso; no se niegan mecanismos distintos de apelación ni se confunde con impugnación de buena pro. Confirmado con texto completo del fragmento citado y contraste de objetivos con las 181 publicadas; la nueva decisión operativa no reutiliza el objetivo anterior. Se conserva ID, revisión actual, origen y corte; el sustento anterior se conserva en reviewBasis. Se usa el numeral citado sin mezclar las redacciones originales y modificadas que coexisten en otros numerales del documento. La aprobación es editorial asistida por IA y autorizada por el administrador. Objetivo: Reconocer que la integración de bases no es acto impugnable mediante apelación.. Evidencia: art. 303, chunk 370. Sin certificación oficial OECE ni revisión humana independiente; se conserva el corte documental declarado.", "confirmReview": true}, "estadoAnterior": "draft"}, {"numero": "Q133", "id": "cc8da4b8-d578-4bde-8254-59d31b435d67", "decision": "approve", "motivo": "Reemplaza plazo de perfeccionamiento por efecto suspensivo; se excluye extensión a ítems no apelados y no se aplica la excepción propia de catálogos. Confirmado con texto completo del fragmento citado y contraste de objetivos con las 181 publicadas; la nueva decisión operativa no reutiliza el objetivo anterior. Se conserva ID, revisión actual, origen y corte; el sustento anterior se conserva en reviewBasis. Se usa el numeral citado sin mezclar las redacciones originales y modificadas que coexisten en otros numerales del documento. La aprobación es editorial asistida por IA y autorizada por el administrador.", "objetivo": "Delimitar suspensión por apelación al ítem impugnado de procedimiento por ítems.", "evidencia": [{"chunkId": "f328ca47-7be7-4822-8e54-60488ad7c726", "chunk_index": 372, "article": "305", "quote": "Artículo 305. Efectos de la interposición 305.1. La interposición del recurso de apelación suspende el procedimiento de selección. Si el procedimiento de selección fue convocado según relación de ítems, la suspensión afecta únicamente al ítem impugnado. 305.2. La interposición del recurso de apelación no suspende la incorporación de proveedores a los Catálogos Electrónicos de Acuerdo Marco ni la extensión de vigencia de dichos catálogos. 305.3. La entidad contratante o el TCP, según corresponda, informa de la interposición del recurso de apelación a través de su registro en la Pladicop, hasta el día hábil siguiente de su interposición.\n\nReglamento de la Ley Nº 32069, Ley General de Contrataciones Públicas Página 161 de 249"}], "input": {"id": "cc8da4b8-d578-4bde-8254-59d31b435d67", "revision": 1, "prompt": "Un procedimiento fue convocado según relación de tres ítems. Se interpone un recurso de apelación únicamente contra el resultado del ítem 2. Según el numeral 305.1, ¿qué alcance tiene la suspensión?", "options": [{"id": "A", "text": "Afecta necesariamente los tres ítems por pertenecer a una convocatoria."}, {"id": "B", "text": "Afecta únicamente al ítem 2 impugnado."}, {"id": "C", "text": "No afecta ningún ítem mientras el recurso no sea resuelto."}, {"id": "D", "text": "Afecta solo los ítems 1 y 3 por no ser objeto del recurso."}], "correctOption": "B", "explanation": "La interposición del recurso suspende el procedimiento de selección. Si fue convocado según relación de ítems, el numeral 305.1 limita ese efecto únicamente al ítem impugnado. En el caso, la suspensión afecta al ítem 2.", "regime": "32069", "topic": "Interposición de apelaciones", "competency": "Selección", "difficulty": "intermediate", "curriculumVersion": "oece-2025-04-25", "competencyCode": "2", "subcompetencyCode": "2.7", "cognitiveLevel": "apply", "optionRationales": {"A": "El numeral 305.1 no extiende la suspensión a los ítems ajenos al recurso.", "B": "La regla especial por ítems limita la suspensión al ítem impugnado.", "C": "La interposición produce la suspensión prevista, sin esperar la resolución.", "D": "Los ítems no impugnados no son los destinatarios de esta suspensión."}, "reviewChecks": {"unambiguous": true, "distractors": true, "conditions": true, "exceptions": true, "sources": true}, "sourceCutoff": "2026-10-29", "origin": "IA:gemini:gemini-2.5-flash:lote:ebd01e4e-bc2f-4195-af98-8906b2d29750", "sources": [{"documentId": "8371bce1-f773-4ad8-8efa-1266276ae4ec", "chunkId": "f328ca47-7be7-4822-8e54-60488ad7c726", "title": "Reglamento de la Ley N.° 32069 — texto actualizado al 09.01.2026", "article": "305", "pageStart": 160, "pageEnd": 161, "quote": "Artículo 305. Efectos de la interposición 305.1. La interposición del recurso de apelación suspende el procedimiento de selección. Si el procedimiento de selección fue convocado según relación de ítems, la suspensión afecta únicamente al ítem impugnado. 305.2. La interposición del recurso de apelación no suspende la incorporación de proveedores a los Catálogos Electrónicos de Acuerdo Marco ni la extensión de vigencia de dichos catálogos. 305.3. La entidad contratante o el TCP, según corresponda, informa de la interposición del recurso de apelación a través de su registro en la Pladicop, hasta el día hábil siguiente de su interposición.\n\nReglamento de la Ley Nº 32069, Ley General de Contrataciones Públicas Página 161 de 249", "version": "Texto actualizado al 09.01.2026", "sha256": "0ebe95b3e05661b80f73c060d6e6ce8dd17621ce34af9277c688dd67e5d99830"}], "status": "published", "reviewBasis": "Revisión asistida por IA el15/11/2026 por encargo y autorización expresa del administrador. Reemplaza plazo de perfeccionamiento por efecto suspensivo; se excluye extensión a ítems no apelados y no se aplica la excepción propia de catálogos. Confirmado con texto completo del fragmento citado y contraste de objetivos con las 181 publicadas; la nueva decisión operativa no reutiliza el objetivo anterior. Se conserva ID, revisión actual, origen y corte; el sustento anterior se conserva en reviewBasis. Se usa el numeral citado sin mezclar las redacciones originales y modificadas que coexisten en otros numerales del documento. La aprobación es editorial asistida por IA y autorizada por el administrador. Objetivo: Delimitar suspensión por apelación al ítem impugnado de procedimiento por ítems.. Evidencia: art. 305, chunk 372. Sin certificación oficial OECE ni revisión humana independiente; se conserva el corte documental declarado.", "confirmReview": true}, "estadoAnterior": "draft"}, {"numero": "Q134", "id": "827f820c-9e62-4d8f-a626-f26d99a4d635", "decision": "approve", "motivo": "Sustituye pérdida en compra corporativa por cálculo de garantía; explicita no MYPE y no alcance del tope, separando base del ítem de cuantía total para competencia. Confirmado con texto completo del fragmento citado y contraste de objetivos con las 181 publicadas; la nueva decisión operativa no reutiliza el objetivo anterior. Se conserva ID, revisión actual, origen y corte; el sustento anterior se conserva en reviewBasis. Se usa el numeral citado sin mezclar las redacciones originales y modificadas que coexisten en otros numerales del documento. La aprobación es editorial asistida por IA y autorizada por el administrador.", "objetivo": "Calcular garantía ordinaria de apelación sobre el ítem impugnado sin aplicar el beneficio MYPE.", "evidencia": [{"chunkId": "ef1f0980-e32a-4bb6-9f9c-be8af322226d", "chunk_index": 376, "article": "309", "quote": "Artículo 309. Garantía por la interposición 309.1. La garantía que respalda la interposición del recurso de apelación es del 3% de la cuantía del procedimiento de selección o del ítem que se decida impugnar. En los procedimientos de selección según relación de ítems, el monto de la garantía se calcu la en función del monto de contratación del ítem impugnado. En ningún caso la garantía es mayor a trescientas (300) UIT vigentes al interponerse el recurso de apelación. 309.2. Para el caso de interposición del recurso de apelación por las micro y pequeñas empresas, el monto de la garantía es del 0.5% de la cuantía del procedimiento de selección o del ítem que se decida impugnar, cuyo límite es de 25 UIT vigentes al moment o de interponerse el recurso de apelación. 309.3. La garantía cumple los mismos requisitos previstos para las garantías contractuales reguladas en la Ley. Asimismo, la garantía puede consistir en un depósito en la cuenta bancaria de la entidad contratante o del OECE, según corresponda.\n\nReglamento de la Ley Nº 32069, Ley General de Contrataciones Públicas Página 163 de 249 309.4. En caso el recurso de apelación se presente ante la entidad contratante, la garantía tiene un plazo mínimo de vigencia de veinte días calendario, contabilizados desde el día siguiente de su emisión; de presentarse ante el TCP, la garantía tiene un p lazo mínimo de vigencia de sesenta días calendario, contabilizados desde el día siguiente de su emisión; debiendo ser renovada, en cualquiera de los casos, hasta el momento en que se agote la vía administrativa, siendo obligación del impugnante realizar di chas renovaciones en forma oportuna. En el supuesto que la garantía no fuese renovada hasta la fecha consignada como vencimiento de esta, es ejecutada para constituir un depósito en la cuenta bancaria de la entidad contratante o del OECE, el cual se mantie ne hasta el agotamiento de la vía administrativa."}], "input": {"id": "827f820c-9e62-4d8f-a626-f26d99a4d635", "revision": 1, "prompt": "Un postor que no es micro ni pequeña empresa apela solo un ítem de S/200 000 de un procedimiento por ítems cuya cuantía total es S/1 000 000. El resultado del cálculo no alcanza el tope de 300 UIT. Según el numeral 309.1, ¿cuál es la garantía?", "options": [{"id": "A", "text": "S/30 000, por aplicar 3% a la cuantía total del procedimiento."}, {"id": "B", "text": "S/1 000, por aplicar 0,5% a la cuantía del ítem."}, {"id": "C", "text": "S/6 000, por aplicar 3% a la cuantía del ítem impugnado."}, {"id": "D", "text": "S/5 000, por aplicar 0,5% a la cuantía total."}], "correctOption": "C", "explanation": "El numeral 309.1 fija la garantía ordinaria en 3% de la cuantía del ítem que se impugna: S/200 000 × 0,03 = S/6 000. El caso excluye la tasa MYPE del 309.2 y declara que el cálculo no alcanza el límite de 300 UIT. La base de garantía no debe confundirse con la regla de competencia por cuantía total.", "regime": "32069", "topic": "Interposición de apelaciones", "competency": "Selección", "difficulty": "intermediate", "curriculumVersion": "oece-2025-04-25", "competencyCode": "2", "subcompetencyCode": "2.7", "cognitiveLevel": "apply", "optionRationales": {"A": "La base de la garantía por ítems es el ítem impugnado, no el total.", "B": "El porcentaje de 0,5% corresponde a micro y pequeñas empresas, condición excluida.", "C": "El 3% ordinario de S/200 000 es S/6 000 y el caso excluye el tope.", "D": "Se aplican tanto una base como una tasa ajenas al supuesto planteado."}, "reviewChecks": {"unambiguous": true, "distractors": true, "conditions": true, "exceptions": true, "sources": true}, "sourceCutoff": "2026-10-29", "origin": "IA:gemini:gemini-2.5-flash:lote:ebd01e4e-bc2f-4195-af98-8906b2d29750", "sources": [{"documentId": "8371bce1-f773-4ad8-8efa-1266276ae4ec", "chunkId": "ef1f0980-e32a-4bb6-9f9c-be8af322226d", "title": "Reglamento de la Ley N.° 32069 — texto actualizado al 09.01.2026", "article": "309", "pageStart": 162, "pageEnd": 163, "quote": "Artículo 309. Garantía por la interposición 309.1. La garantía que respalda la interposición del recurso de apelación es del 3% de la cuantía del procedimiento de selección o del ítem que se decida impugnar. En los procedimientos de selección según relación de ítems, el monto de la garantía se calcu la en función del monto de contratación del ítem impugnado. En ningún caso la garantía es mayor a trescientas (300) UIT vigentes al interponerse el recurso de apelación. 309.2. Para el caso de interposición del recurso de apelación por las micro y pequeñas empresas, el monto de la garantía es del 0.5% de la cuantía del procedimiento de selección o del ítem que se decida impugnar, cuyo límite es de 25 UIT vigentes al moment o de interponerse el recurso de apelación. 309.3. La garantía cumple los mismos requisitos previstos para las garantías contractuales reguladas en la Ley. Asimismo, la garantía puede consistir en un depósito en la cuenta bancaria de la entidad contratante o del OECE, según corresponda.\n\nReglamento de la Ley Nº 32069, Ley General de Contrataciones Públicas Página 163 de 249 309.4. En caso el recurso de apelación se presente ante la entidad contratante, la garantía tiene un plazo mínimo de vigencia de veinte días calendario, contabilizados desde el día siguiente de su emisión; de presentarse ante el TCP, la garantía tiene un p lazo mínimo de vigencia de sesenta días calendario, contabilizados desde el día siguiente de su emisión; debiendo ser renovada, en cualquiera de los casos, hasta el momento en que se agote la vía administrativa, siendo obligación del impugnante realizar di chas renovaciones en forma oportuna. En el supuesto que la garantía no fuese renovada hasta la fecha consignada como vencimiento de esta, es ejecutada para constituir un depósito en la cuenta bancaria de la entidad contratante o del OECE, el cual se mantie ne hasta el agotamiento de la vía administrativa.", "version": "Texto actualizado al 09.01.2026", "sha256": "0ebe95b3e05661b80f73c060d6e6ce8dd17621ce34af9277c688dd67e5d99830"}], "status": "published", "reviewBasis": "Revisión asistida por IA el15/11/2026 por encargo y autorización expresa del administrador. Sustituye pérdida en compra corporativa por cálculo de garantía; explicita no MYPE y no alcance del tope, separando base del ítem de cuantía total para competencia. Confirmado con texto completo del fragmento citado y contraste de objetivos con las 181 publicadas; la nueva decisión operativa no reutiliza el objetivo anterior. Se conserva ID, revisión actual, origen y corte; el sustento anterior se conserva en reviewBasis. Se usa el numeral citado sin mezclar las redacciones originales y modificadas que coexisten en otros numerales del documento. La aprobación es editorial asistida por IA y autorizada por el administrador. Objetivo: Calcular garantía ordinaria de apelación sobre el ítem impugnado sin aplicar el beneficio MYPE.. Evidencia: art. 309, chunk 376. Sin certificación oficial OECE ni revisión humana independiente; se conserva el corte documental declarado.", "confirmReview": true}, "estadoAnterior": "draft"}, {"numero": "Q138", "id": "59798174-854a-4305-88f5-ca2bf3c9f31b", "decision": "approve", "motivo": "Repurposa ejecución de obra a selección; no reproduce rechazo de quien nunca fue participante, pues el recurrente sí presentó oferta y pretende impugnar sin revertir no admisión. Confirmado con texto completo del fragmento citado y contraste de objetivos con las 181 publicadas; la nueva decisión operativa no reutiliza el objetivo anterior. Se conserva ID, revisión actual, origen y corte; el sustento anterior se conserva en reviewBasis. Se usa el numeral citado sin mezclar las redacciones originales y modificadas que coexisten en otros numerales del documento. La aprobación es editorial asistida por IA y autorizada por el administrador.", "objetivo": "Detectar improcedencia cuando el no admitido cuestiona adjudicación sin revertir su exclusión.", "evidencia": [{"chunkId": "1cf4c64c-dc1a-444d-aa86-f68a4439f29f", "chunk_index": 375, "article": "308", "quote": "Artículo 308. Improcedencia del recurso El recurso de apelación presentado ante la entidad contratante o ante el TCP es declarado improcedente cuando: a) La entidad contratante o el TCP carezca de competencia para resolverlo, de acuerdo con lo establecido en el artículo 74 de la Ley. No aplica en estos casos lo establecido en el artículo 130 de la LPAG, o disposición que la sustituya, referido a la prese ntación de escritos ante entidades que no resultan competentes. b) Sea interpuesto contra alguno de los actos que no son impugnables. c) Sea interpuesto fuera del plazo. d) El que suscriba el recurso no sea el impugnante o su representante. e) El impugnante se encuentre impedido para participar en los procedimientos de selección y/o contratar con el Estado, conforme al artículo 30 de la Ley. f) El impugnante se encuentre incapacitado legalmente para ejercer actos civiles. g) El proveedor impugne la adjudicación de la buena pro, sin cuestionar la no admisión o descalificación de su oferta o, aun cuestionándola, no logra revertir de forma previa su condición de no admitido o descalificado del procedimiento. h) Sea interpuesto por el postor ganador de la buena pro. i) No exista conexión lógica entre los hechos expuestos en el recurso y su petitorio. j) El impugnante carezca de interés para obrar o legitimidad procesal."}], "input": {"id": "59798174-854a-4305-88f5-ca2bf3c9f31b", "revision": 1, "prompt": "Un postor cuya oferta fue no admitida apela únicamente la adjudicación a otro proveedor, sin cuestionar su propia no admisión. Según el literal 308.g, ¿cómo se califica ese recurso?", "options": [{"id": "A", "text": "Admisible sobre el fondo por el solo hecho de haber presentado oferta."}, {"id": "B", "text": "Extemporáneo necesariamente, aunque haya sido interpuesto dentro del plazo."}, {"id": "C", "text": "Fundado automáticamente porque toda no admisión anula la adjudicación."}, {"id": "D", "text": "Improcedente, porque pretende cuestionar la adjudicación sin revertir previamente su condición de no admitido."}], "correctOption": "D", "explanation": "El literal 308.g prevé improcedencia cuando el proveedor impugna la adjudicación sin cuestionar la no admisión o descalificación de su oferta, o no logra revertir esa condición previamente. El supuesto no es el de una persona que nunca fue participante o postor.", "regime": "32069", "topic": "Resolución de apelaciones", "competency": "Selección", "difficulty": "intermediate", "curriculumVersion": "oece-2025-04-25", "competencyCode": "2", "subcompetencyCode": "2.8", "cognitiveLevel": "apply", "optionRationales": {"A": "Haber presentado oferta no elimina la causal específica del literal 308.g.", "B": "El defecto descrito es de procedencia, no acredita presentación fuera de plazo.", "C": "La no admisión del recurrente no demuestra por sí misma ilegalidad de la adjudicación.", "D": "El literal 308.g exige cuestionar y revertir la no admisión o descalificación para disputar la adjudicación."}, "reviewChecks": {"unambiguous": true, "distractors": true, "conditions": true, "exceptions": true, "sources": true}, "sourceCutoff": "2026-10-29", "origin": "IA:gemini:gemini-2.5-flash:lote:460e9f10-169c-4b43-8296-2685bb7920e9", "sources": [{"documentId": "8371bce1-f773-4ad8-8efa-1266276ae4ec", "chunkId": "1cf4c64c-dc1a-444d-aa86-f68a4439f29f", "title": "Reglamento de la Ley N.° 32069 — texto actualizado al 09.01.2026", "article": "308", "pageStart": 162, "pageEnd": 162, "quote": "Artículo 308. Improcedencia del recurso El recurso de apelación presentado ante la entidad contratante o ante el TCP es declarado improcedente cuando: a) La entidad contratante o el TCP carezca de competencia para resolverlo, de acuerdo con lo establecido en el artículo 74 de la Ley. No aplica en estos casos lo establecido en el artículo 130 de la LPAG, o disposición que la sustituya, referido a la prese ntación de escritos ante entidades que no resultan competentes. b) Sea interpuesto contra alguno de los actos que no son impugnables. c) Sea interpuesto fuera del plazo. d) El que suscriba el recurso no sea el impugnante o su representante. e) El impugnante se encuentre impedido para participar en los procedimientos de selección y/o contratar con el Estado, conforme al artículo 30 de la Ley. f) El impugnante se encuentre incapacitado legalmente para ejercer actos civiles. g) El proveedor impugne la adjudicación de la buena pro, sin cuestionar la no admisión o descalificación de su oferta o, aun cuestionándola, no logra revertir de forma previa su condición de no admitido o descalificado del procedimiento. h) Sea interpuesto por el postor ganador de la buena pro. i) No exista conexión lógica entre los hechos expuestos en el recurso y su petitorio. j) El impugnante carezca de interés para obrar o legitimidad procesal.", "version": "Texto actualizado al 09.01.2026", "sha256": "0ebe95b3e05661b80f73c060d6e6ce8dd17621ce34af9277c688dd67e5d99830"}], "status": "published", "reviewBasis": "Revisión asistida por IA el15/11/2026 por encargo y autorización expresa del administrador. Repurposa ejecución de obra a selección; no reproduce rechazo de quien nunca fue participante, pues el recurrente sí presentó oferta y pretende impugnar sin revertir no admisión. Confirmado con texto completo del fragmento citado y contraste de objetivos con las 181 publicadas; la nueva decisión operativa no reutiliza el objetivo anterior. Se conserva ID, revisión actual, origen y corte; el sustento anterior se conserva en reviewBasis. Se usa el numeral citado sin mezclar las redacciones originales y modificadas que coexisten en otros numerales del documento. La aprobación es editorial asistida por IA y autorizada por el administrador. Objetivo: Detectar improcedencia cuando el no admitido cuestiona adjudicación sin revertir su exclusión.. Evidencia: art. 308, chunk 375. Sin certificación oficial OECE ni revisión humana independiente; se conserva el corte documental declarado.", "confirmReview": true}, "estadoAnterior": "draft"}, {"numero": "Q140", "id": "0fcf1ec7-e4ed-4396-9aaa-701dc21647d2", "decision": "approve", "motivo": "Repurposa suspensión de obra a trámite de selección; se especifica competencia de entidad, correspondencia de recursos y distingue expediente receptor del hito de cómputo. Confirmado con texto completo del fragmento citado y contraste de objetivos con las 181 publicadas; la nueva decisión operativa no reutiliza el objetivo anterior. Se conserva ID, revisión actual, origen y corte; el sustento anterior se conserva en reviewBasis. Se usa el numeral citado sin mezclar las redacciones originales y modificadas que coexisten en otros numerales del documento. La aprobación es editorial asistida por IA y autorizada por el administrador.", "objetivo": "Acumular apelaciones relacionadas ante entidad y recalcular el inicio del plazo resolutivo.", "evidencia": [{"chunkId": "5788ee15-8ced-49b1-baec-80c0c8f21ff7", "chunk_index": 377, "article": "310", "quote": "Artículo 310. Procedimiento ante la entidad contratante 310.1. La tramitación del recurso de apelación ante la entidad contratante se sujeta al siguiente procedimiento: a) La presentación del recurso de apelación se registra en la Pladicop al día siguiente de haber sido interpuesto. b) De haberse interpuesto dos o más recursos de apelación respecto de un mismo procedimiento de selección o ítem, la entidad contratante los acumula a fin de resolverlos de manera conjunta, siempre que los mismos guarden correspondencia. La acumulación se efectúa al procedimiento de impugnación más antiguo. Producida la acumulación, el plazo para emitir resolución se contabiliza a partir del último recurso interpuesto o subsanado. c) La entidad contratante corre traslado de la apelación a los postores que tengan interés directo en la resolución del recurso, al día hábil siguiente de la presentación del recurso o desde la subsanación de las omisiones advertidas en su presentación, se gún corresponda. Esta notificación se efectúa a través de la publicación del recurso de apelación y sus anexos en la Pladicop. d) El postor o postores emplazados pueden absolver el traslado del recurso interpuesto en un plazo no mayor a tres días hábiles, contabilizados a partir del día siguiente de notificado a través de la Pladicop. Dicha absolución es publicada en la Pladicop. La entidad contratante resuelve con la absolución del traslado o sin ella. e) Las partes formulan sus pretensiones y ofrecen los medios probatorios en el escrito que contiene el recurso de apelación y en el escrito de absolución de traslado del recurso de apelación, presentados dentro del plazo legal. La determinación de puntos c ontrovertidos se sujeta a lo expuesto por las partes en dichos escritos, sin perjuicio de la presentación de pruebas y documentos adicionales que coadyuven a la resolución de dicho procedimiento, presentados dentro del plazo legal. f) Al interponer el recurso o al absolverlo, el impugnante o los postores pueden solicitar el uso de la palabra, actuación que se realiza dentro de los tres días hábiles siguientes de culminado el plazo para la absolución del traslado del recurso de apelac ión. g) La entidad contratante resuelve la apelación y notifica su decisión a través de la Pladicop en un plazo no mayor de diez días hábiles, contabilizados a partir del día siguiente de la presentación del recurso o la subsanación de las omisiones y/o defecto s advertidos en su presentación. 310.2. A efectos de resolver el recurso de apelación, la autoridad de la gestión administrativa cuenta con la opinión previa de las áreas legal y técnicas, cautelando que en la decisión sobre la impugnación no intervengan los servidores que participaron en el procedimiento de selección."}], "input": {"id": "0fcf1ec7-e4ed-4396-9aaa-701dc21647d2", "revision": 1, "prompt": "La entidad competente recibe dos apelaciones relacionadas sobre el mismo ítem. La segunda fue subsanada después de la primera. Según el literal 310.1.b, ¿cómo debe proceder?", "options": [{"id": "A", "text": "Acumular al procedimiento de impugnación más antiguo y contar el plazo de resolución desde el último recurso interpuesto o subsanado."}, {"id": "B", "text": "Acumular al más antiguo, pero iniciar el cómputo solo desde la audiencia oral."}, {"id": "C", "text": "Acumular al más reciente y mantener siempre el cómputo desde el primer recurso."}, {"id": "D", "text": "Resolverlas separadamente aunque guarden correspondencia sobre el mismo ítem."}], "correctOption": "A", "explanation": "Los recursos sobre un mismo procedimiento o ítem se acumulan si guardan correspondencia, al procedimiento de impugnación más antiguo. Producida la acumulación, el literal 310.1.b cuenta el plazo para resolver desde el último recurso interpuesto o subsanado. La subsanación posterior del segundo recurso determina aquí el hito pertinente.", "regime": "32069", "topic": "Resolución de apelaciones", "competency": "Selección", "difficulty": "intermediate", "curriculumVersion": "oece-2025-04-25", "competencyCode": "2", "subcompetencyCode": "2.8", "cognitiveLevel": "apply", "optionRationales": {"A": "El literal 310.1.b distingue acumulación al más antiguo y cómputo desde el último recurso o subsanación.", "B": "La audiencia no es el hito establecido para este cómputo tras acumulación.", "C": "La norma dispone acumular al más antiguo y ajustar el hito del cómputo.", "D": "La correspondencia sobre el mismo ítem activa la acumulación prevista."}, "reviewChecks": {"unambiguous": true, "distractors": true, "conditions": true, "exceptions": true, "sources": true}, "sourceCutoff": "2026-10-29", "origin": "IA:gemini:gemini-2.5-flash:lote:d83b2bb4-d117-43f7-a7f2-77ec1d8045a4", "sources": [{"documentId": "8371bce1-f773-4ad8-8efa-1266276ae4ec", "chunkId": "5788ee15-8ced-49b1-baec-80c0c8f21ff7", "title": "Reglamento de la Ley N.° 32069 — texto actualizado al 09.01.2026", "article": "310", "pageStart": 163, "pageEnd": 163, "quote": "Artículo 310. Procedimiento ante la entidad contratante 310.1. La tramitación del recurso de apelación ante la entidad contratante se sujeta al siguiente procedimiento: a) La presentación del recurso de apelación se registra en la Pladicop al día siguiente de haber sido interpuesto. b) De haberse interpuesto dos o más recursos de apelación respecto de un mismo procedimiento de selección o ítem, la entidad contratante los acumula a fin de resolverlos de manera conjunta, siempre que los mismos guarden correspondencia. La acumulación se efectúa al procedimiento de impugnación más antiguo. Producida la acumulación, el plazo para emitir resolución se contabiliza a partir del último recurso interpuesto o subsanado. c) La entidad contratante corre traslado de la apelación a los postores que tengan interés directo en la resolución del recurso, al día hábil siguiente de la presentación del recurso o desde la subsanación de las omisiones advertidas en su presentación, se gún corresponda. Esta notificación se efectúa a través de la publicación del recurso de apelación y sus anexos en la Pladicop. d) El postor o postores emplazados pueden absolver el traslado del recurso interpuesto en un plazo no mayor a tres días hábiles, contabilizados a partir del día siguiente de notificado a través de la Pladicop. Dicha absolución es publicada en la Pladicop. La entidad contratante resuelve con la absolución del traslado o sin ella. e) Las partes formulan sus pretensiones y ofrecen los medios probatorios en el escrito que contiene el recurso de apelación y en el escrito de absolución de traslado del recurso de apelación, presentados dentro del plazo legal. La determinación de puntos c ontrovertidos se sujeta a lo expuesto por las partes en dichos escritos, sin perjuicio de la presentación de pruebas y documentos adicionales que coadyuven a la resolución de dicho procedimiento, presentados dentro del plazo legal. f) Al interponer el recurso o al absolverlo, el impugnante o los postores pueden solicitar el uso de la palabra, actuación que se realiza dentro de los tres días hábiles siguientes de culminado el plazo para la absolución del traslado del recurso de apelac ión. g) La entidad contratante resuelve la apelación y notifica su decisión a través de la Pladicop en un plazo no mayor de diez días hábiles, contabilizados a partir del día siguiente de la presentación del recurso o la subsanación de las omisiones y/o defecto s advertidos en su presentación. 310.2. A efectos de resolver el recurso de apelación, la autoridad de la gestión administrativa cuenta con la opinión previa de las áreas legal y técnicas, cautelando que en la decisión sobre la impugnación no intervengan los servidores que participaron en el procedimiento de selección.", "version": "Texto actualizado al 09.01.2026", "sha256": "0ebe95b3e05661b80f73c060d6e6ce8dd17621ce34af9277c688dd67e5d99830"}], "status": "published", "reviewBasis": "Revisión asistida por IA el15/11/2026 por encargo y autorización expresa del administrador. Repurposa suspensión de obra a trámite de selección; se especifica competencia de entidad, correspondencia de recursos y distingue expediente receptor del hito de cómputo. Confirmado con texto completo del fragmento citado y contraste de objetivos con las 181 publicadas; la nueva decisión operativa no reutiliza el objetivo anterior. Se conserva ID, revisión actual, origen y corte; el sustento anterior se conserva en reviewBasis. Se usa el numeral citado sin mezclar las redacciones originales y modificadas que coexisten en otros numerales del documento. La aprobación es editorial asistida por IA y autorizada por el administrador. Objetivo: Acumular apelaciones relacionadas ante entidad y recalcular el inicio del plazo resolutivo.. Evidencia: art. 310, chunk 377. Sin certificación oficial OECE ni revisión humana independiente; se conserva el corte documental declarado.", "confirmReview": true}, "estadoAnterior": "draft"}, {"numero": "Q145", "id": "2db74674-c671-4de6-a364-5138375cf50e", "decision": "approve", "motivo": "Reescrita una pregunta repetida o complementaria hacia un objetivo operativo distinto: Calcular el límite de subcontratación sobre el monto vigente y no el original. Clave única, condiciones y cada distractor contrastados con los pasajes citados.", "objetivo": "Calcular el límite de subcontratación sobre el monto vigente y no el original", "evidencia": [{"chunkId": "42c27b36-062a-4ea7-b180-7a12ab09096b", "chunk_index": 130, "article": "108", "quote": "108.1. Se puede subcontratar por un máximo del 40% del monto del contrato vigente de bienes, servicios u obras. En el caso de bienes y servicios las bases pueden especificar las prestaciones esenciales que no pueden ser materia de subcontratación o, de así haberse evaluado en la estrategia de contratación, que no se permite la subcontratación, con el sustento correspondiente."}], "input": {"id": "2db74674-c671-4de6-a364-5138375cf50e", "revision": 1, "regime": "32069", "origin": "IA:gemini:gemini-2.5-flash:lote:f7446eca-c4dc-4607-b999-0b64e3da75be", "prompt": "Un contrato de bienes pasó válidamente de S/100 000 a S/150 000. Las bases permiten subcontratar y el alcance propuesto no comprende prestaciones esenciales excluidas. Sin dar por aprobada la solicitud ni los demás requisitos, ¿cuál es el máximo monetario de subcontratación según 108.1?", "options": [{"id": "A", "text": "S/40 000, porque el límite siempre usa el monto original."}, {"id": "B", "text": "S/60 000, equivalente al 40% del monto vigente."}, {"id": "C", "text": "S/75 000, equivalente al 50% del monto vigente."}, {"id": "D", "text": "S/150 000, porque la modificación elimina el límite."}], "correctOption": "B", "explanation": "El 108.1 establece hasta 40% del monto del contrato vigente: 0,40×S/150 000=S/60 000. Es un tope, no aprobación automática de la subcontratación.", "topic": "Contenido y vigencia del contrato", "competency": "Ejecución contractual", "difficulty": "intermediate", "curriculumVersion": "oece-2025-04-25", "competencyCode": "3", "subcompetencyCode": "3.1", "cognitiveLevel": "apply", "optionRationales": {"A": "La base indicada por 108.1 es el contrato vigente, no el monto original.", "B": "El 108.1 establece hasta 40% del monto del contrato vigente: 0,40×S/150 000=S/60 000. Es un tope, no aprobación automática de la subcontratación.", "C": "El 108.1 fija 40%, no 50%, del monto vigente.", "D": "La modificación del monto no elimina el límite ni los requisitos de subcontratación."}, "reviewChecks": {"unambiguous": true, "distractors": true, "conditions": true, "exceptions": true, "sources": true}, "sourceCutoff": "2026-10-29", "sources": [{"documentId": "8371bce1-f773-4ad8-8efa-1266276ae4ec", "chunkId": "42c27b36-062a-4ea7-b180-7a12ab09096b", "title": "Reglamento de la Ley N.° 32069 — texto actualizado al 09.01.2026", "article": "108", "pageStart": 60, "pageEnd": 60, "quote": "108.1. Se puede subcontratar por un máximo del 40% del monto del contrato vigente de bienes, servicios u obras. En el caso de bienes y servicios las bases pueden especificar las prestaciones esenciales que no pueden ser materia de subcontratación o, de así haberse evaluado en la estrategia de contratación, que no se permite la subcontratación, con el sustento correspondiente.", "version": "Texto actualizado al 09.01.2026", "sha256": "0ebe95b3e05661b80f73c060d6e6ce8dd17621ce34af9277c688dd67e5d99830"}], "status": "published", "confirmReview": true, "reviewBasis": "Revisión asistida por IA el15/11/2026 por encargo y autorización expresa del administrador. Reescrita una pregunta repetida o complementaria hacia un objetivo operativo distinto: Calcular el límite de subcontratación sobre el monto vigente y no el original. Clave única, condiciones y cada distractor contrastados con los pasajes citados. Objetivo: Calcular el límite de subcontratación sobre el monto vigente y no el original. Evidencia: art. 108, chunk 130. Sin certificación oficial OECE ni revisión humana independiente; se conserva el corte documental declarado."}, "estadoAnterior": "draft"}, {"numero": "Q166", "id": "fc8152c9-ad0b-4dc3-9955-786adea1762c", "decision": "approve", "motivo": "Reescrita una pregunta repetida o complementaria hacia un objetivo operativo distinto: Distinguir modalidad institucional de arbitraje frente al límite para ad hoc. Clave única, condiciones y cada distractor contrastados con los pasajes citados.", "objetivo": "Distinguir modalidad institucional de arbitraje frente al límite para ad hoc", "evidencia": [{"chunkId": "46540bae-785c-4b83-b99f-03a7caa99997", "chunk_index": 99, "article": "84", "quote": "84.1. El arbitraje al que se refiere la presente ley es de derecho, nacional o internacional y se desarrolla en idioma español. Cuando hubiere arbitraje internacional, se podrá acudir a cortes arbitrales en otros países o foros de reputación reconocidos internacionalmente. El a rbitraje puede ser ad hoc solo en los casos en los que el monto de la controversia no supere las diez UIT. En todos los demás casos, es institucional, y el convenio arbitral puede identificar la institución que administra el arbitraje, la cual debe encontrarse en el registro de instituciones arbitrales y centros de administración de juntas de prevención y resolución de disputas. Todo pacto en contrario es nulo. En caso de arbitraje internacional, se podrá acudir a cortes arbitrales en otros países o foros de reputación reconocidos internacionalmente, sin necesidad de que se encuentren en el referido registro. Las condiciones para acudir al arbitraje internacional se establecen en el reglamento."}], "input": {"id": "fc8152c9-ad0b-4dc3-9955-786adea1762c", "revision": 1, "regime": "32069", "origin": "IA:gemini:gemini-2.5-flash:lote:5f7ad23c-fd5c-465a-abdf-6ba178fa4fed", "prompt": "En una controversia nacional sujeta a la Ley 32069, el monto discutido es doce UIT. Se propone arbitraje ad hoc por acuerdo de ambas partes. Según 84.1, ¿es compatible esa modalidad con el monto del caso?", "options": [{"id": "A", "text": "Sí; cualquier cuantía puede tramitarse ad hoc por acuerdo."}, {"id": "B", "text": "Sí; el límite se mide por el monto total del contrato y no por la controversia."}, {"id": "C", "text": "No; el ad hoc solo cabe si la controversia no supera diez UIT y en los demás casos corresponde institucional."}, {"id": "D", "text": "No; toda controversia mayor de diez UIT se resuelve exclusivamente en el Poder Judicial."}], "correctOption": "C", "explanation": "El 84.1 permite ad hoc solo si el monto de la controversia no supera diez UIT. Para doce UIT exige arbitraje institucional; no convierte por ello la controversia en judicial.", "topic": "Controversias y solución de conflictos", "competency": "Ejecución contractual", "difficulty": "intermediate", "curriculumVersion": "oece-2025-04-25", "competencyCode": "3", "subcompetencyCode": "3.5", "cognitiveLevel": "apply", "optionRationales": {"A": "El acuerdo no elimina el límite expreso del 84.1.", "B": "El pasaje usa el monto de la controversia, no el monto total del contrato.", "C": "El 84.1 permite ad hoc solo si el monto de la controversia no supera diez UIT. Para doce UIT exige arbitraje institucional; no convierte por ello la controversia en judicial.", "D": "La regla indica modalidad institucional, no exclusividad del Poder Judicial."}, "reviewChecks": {"unambiguous": true, "distractors": true, "conditions": true, "exceptions": true, "sources": true}, "sourceCutoff": "2026-10-29", "sources": [{"documentId": "dc721f35-138c-41b8-8dca-16289f74d9df", "chunkId": "46540bae-785c-4b83-b99f-03a7caa99997", "title": "Ley N.° 32069 — texto actualizado al 19.07.2026", "article": "84", "pageStart": 40, "pageEnd": 42, "quote": "84.1. El arbitraje al que se refiere la presente ley es de derecho, nacional o internacional y se desarrolla en idioma español. Cuando hubiere arbitraje internacional, se podrá acudir a cortes arbitrales en otros países o foros de reputación reconocidos internacionalmente. El a rbitraje puede ser ad hoc solo en los casos en los que el monto de la controversia no supere las diez UIT. En todos los demás casos, es institucional, y el convenio arbitral puede identificar la institución que administra el arbitraje, la cual debe encontrarse en el registro de instituciones arbitrales y centros de administración de juntas de prevención y resolución de disputas. Todo pacto en contrario es nulo. En caso de arbitraje internacional, se podrá acudir a cortes arbitrales en otros países o foros de reputación reconocidos internacionalmente, sin necesidad de que se encuentren en el referido registro. Las condiciones para acudir al arbitraje internacional se establecen en el reglamento.", "version": "Texto actualizado al 19.07.2026", "sha256": "f14ffa37b824b8af03c0b97e0603839a786ed61c7ca07b1d300c9af928d133f7"}], "status": "published", "confirmReview": true, "reviewBasis": "Revisión asistida por IA el15/11/2026 por encargo y autorización expresa del administrador. Reescrita una pregunta repetida o complementaria hacia un objetivo operativo distinto: Distinguir modalidad institucional de arbitraje frente al límite para ad hoc. Clave única, condiciones y cada distractor contrastados con los pasajes citados. Objetivo: Distinguir modalidad institucional de arbitraje frente al límite para ad hoc. Evidencia: art. 84, chunk 99. Sin certificación oficial OECE ni revisión humana independiente; se conserva el corte documental declarado."}, "estadoAnterior": "draft"}, {"numero": "Q167", "id": "7cef6b1c-d5b8-48e8-92d0-7e7059fc8386", "decision": "approve", "motivo": "Reescrita una pregunta repetida o complementaria hacia un objetivo operativo distinto: Determinar composición arbitral supletoria y su excepción por complejidad o cuantía. Clave única, condiciones y cada distractor contrastados con los pasajes citados.", "objetivo": "Determinar composición arbitral supletoria y su excepción por complejidad o cuantía", "evidencia": [{"chunkId": "46540bae-785c-4b83-b99f-03a7caa99997", "chunk_index": 99, "article": "84", "quote": "84.2. El arbitraje es resuelto por árbitro único o tribunal arbitral integrado por tres miembros, según el acuerdo de las partes en el convenio arbitral o en el reglamento arbitral aplicable. 84.3. A falta de acuerdo o ante la existencia de dudas sobre el mismo, el arbitraje es resuelto por árbitro único, a no ser que la complejidad o cuantía de las controversias justifique la conformación de un tribunal arbitral."}], "input": {"id": "7cef6b1c-d5b8-48e8-92d0-7e7059fc8386", "revision": 2, "regime": "32069", "origin": "IA:gemini:gemini-2.5-flash:lote:9d451b94-9169-4b2b-bb96-fb5e3562b7f4", "prompt": "El convenio arbitral no define la composición y el reglamento aplicable tampoco resuelve la duda. No se acredita complejidad ni cuantía que justifique un tribunal. Según 84.3, ¿qué composición corresponde por defecto?", "options": [{"id": "A", "text": "Tres árbitros en todo contrato público, sin excepción."}, {"id": "B", "text": "Cinco árbitros por existir duda en el convenio."}, {"id": "C", "text": "La que elija unilateralmente la parte que presenta la solicitud."}, {"id": "D", "text": "Árbitro único."}], "correctOption": "D", "explanation": "A falta de acuerdo o ante dudas, el 84.3 dispone árbitro único, salvo que complejidad o cuantía justifiquen tribunal. El caso excluye esa excepción.", "topic": "Controversias y solución de conflictos", "competency": "Ejecución contractual", "difficulty": "intermediate", "curriculumVersion": "oece-2025-04-25", "competencyCode": "3", "subcompetencyCode": "3.5", "cognitiveLevel": "apply", "optionRationales": {"A": "El 84.3 no establece un tribunal obligatorio de tres en todo caso.", "B": "La duda activa la regla supletoria de árbitro único, no cinco árbitros.", "C": "La norma no atribuye esa elección unilateral a la parte solicitante.", "D": "A falta de acuerdo o ante dudas, el 84.3 dispone árbitro único, salvo que complejidad o cuantía justifiquen tribunal. El caso excluye esa excepción."}, "reviewChecks": {"unambiguous": true, "distractors": true, "conditions": true, "exceptions": true, "sources": true}, "sourceCutoff": "2026-10-29", "sources": [{"documentId": "dc721f35-138c-41b8-8dca-16289f74d9df", "chunkId": "46540bae-785c-4b83-b99f-03a7caa99997", "title": "Ley N.° 32069 — texto actualizado al 19.07.2026", "article": "84", "pageStart": 40, "pageEnd": 42, "quote": "84.2. El arbitraje es resuelto por árbitro único o tribunal arbitral integrado por tres miembros, según el acuerdo de las partes en el convenio arbitral o en el reglamento arbitral aplicable. 84.3. A falta de acuerdo o ante la existencia de dudas sobre el mismo, el arbitraje es resuelto por árbitro único, a no ser que la complejidad o cuantía de las controversias justifique la conformación de un tribunal arbitral.", "version": "Texto actualizado al 19.07.2026", "sha256": "f14ffa37b824b8af03c0b97e0603839a786ed61c7ca07b1d300c9af928d133f7"}], "status": "published", "confirmReview": true, "reviewBasis": "Revisión asistida por IA el15/11/2026 por encargo y autorización expresa del administrador. Reescrita una pregunta repetida o complementaria hacia un objetivo operativo distinto: Determinar composición arbitral supletoria y su excepción por complejidad o cuantía. Clave única, condiciones y cada distractor contrastados con los pasajes citados. Objetivo: Determinar composición arbitral supletoria y su excepción por complejidad o cuantía. Evidencia: art. 84, chunk 99. Sin certificación oficial OECE ni revisión humana independiente; se conserva el corte documental declarado."}, "estadoAnterior": "draft"}, {"numero": "Q178", "id": "72214aca-e219-4565-b845-e9c55e38f6b0", "decision": "approve", "motivo": "Reescrita una pregunta repetida o complementaria hacia un objetivo operativo distinto: Identificar el límite material de competencia de la JPRD sobre validez contractual. Clave única, condiciones y cada distractor contrastados con los pasajes citados.", "objetivo": "Identificar el límite material de competencia de la JPRD sobre validez contractual", "evidencia": [{"chunkId": "dd7999ce-12fb-455b-9f64-61b3d5eff15d", "chunk_index": 94, "article": "79", "quote": "79.1. La junta de prevención y resolución de disputas promueve que las partes logren prevenir o resolver eficientemente las controversias surgidas en contratos de suministro y de obras de acuerdo con lo establecido en el reglamento. 79.2. La junta de prevención y resolución de disputas tiene competencia para las siguientes acciones: a) Absolver consultas planteadas por las partes respecto de algún aspecto contractual o técnico. b) Resolver controversias técnicas y contractuales. c) Otras establecidas en el reglamento. 79.3. La junta de prevención y resolución de disputas resuelve controversias a través de decisiones. No puede conocer controversias relativas a la validez, nulidad, o eficacia del contrato. Sus decisiones son obligatorias y son de inmediato cumplimiento."}], "input": {"id": "72214aca-e219-4565-b845-e9c55e38f6b0", "revision": 1, "regime": "32069", "origin": "IA:gemini:gemini-2.5-flash:lote:d4a866a3-678b-4ba7-ade8-75f94bde13c0", "prompt": "En una obra con JPRD, una parte solicita que la junta declare inválido el contrato. No pide resolver una discrepancia técnica de ejecución. Según 79.3 de la Ley, ¿puede la junta conocer esa pretensión?", "options": [{"id": "A", "text": "No; la junta no puede conocer controversias relativas a validez, nulidad o eficacia del contrato."}, {"id": "B", "text": "Sí; tener junta vuelve arbitrable ante ella cualquier materia."}, {"id": "C", "text": "Sí; basta que ambas partes acepten ampliar sus competencias por escrito."}, {"id": "D", "text": "No; porque la junta no resuelve ninguna controversia contractual, ni siquiera técnica."}], "correctOption": "A", "explanation": "El 79.3 excluye expresamente controversias relativas a validez, nulidad o eficacia contractual de la competencia de la JPRD. Ello no elimina sus competencias técnicas y contractuales dentro de su ámbito.", "topic": "Controversias y solución de conflictos", "competency": "Ejecución contractual", "difficulty": "intermediate", "curriculumVersion": "oece-2025-04-25", "competencyCode": "3", "subcompetencyCode": "3.5", "cognitiveLevel": "apply", "optionRationales": {"A": "El 79.3 excluye expresamente controversias relativas a validez, nulidad o eficacia contractual de la competencia de la JPRD. Ello no elimina sus competencias técnicas y contractuales dentro de su ámbito.", "B": "La existencia de la junta no elimina las exclusiones materiales del 79.3.", "C": "El acuerdo no sustituye la exclusión expresa de competencia del 79.3.", "D": "Los numerales 79.1 y 79.2 sí le atribuyen funciones dentro de su ámbito; la exclusión es específica."}, "reviewChecks": {"unambiguous": true, "distractors": true, "conditions": true, "exceptions": true, "sources": true}, "sourceCutoff": "2026-10-29", "sources": [{"documentId": "dc721f35-138c-41b8-8dca-16289f74d9df", "chunkId": "dd7999ce-12fb-455b-9f64-61b3d5eff15d", "title": "Ley N.° 32069 — texto actualizado al 19.07.2026", "article": "79", "pageStart": 39, "pageEnd": 39, "quote": "79.1. La junta de prevención y resolución de disputas promueve que las partes logren prevenir o resolver eficientemente las controversias surgidas en contratos de suministro y de obras de acuerdo con lo establecido en el reglamento. 79.2. La junta de prevención y resolución de disputas tiene competencia para las siguientes acciones: a) Absolver consultas planteadas por las partes respecto de algún aspecto contractual o técnico. b) Resolver controversias técnicas y contractuales. c) Otras establecidas en el reglamento. 79.3. La junta de prevención y resolución de disputas resuelve controversias a través de decisiones. No puede conocer controversias relativas a la validez, nulidad, o eficacia del contrato. Sus decisiones son obligatorias y son de inmediato cumplimiento.", "version": "Texto actualizado al 19.07.2026", "sha256": "f14ffa37b824b8af03c0b97e0603839a786ed61c7ca07b1d300c9af928d133f7"}], "status": "published", "confirmReview": true, "reviewBasis": "Revisión asistida por IA el15/11/2026 por encargo y autorización expresa del administrador. Reescrita una pregunta repetida o complementaria hacia un objetivo operativo distinto: Identificar el límite material de competencia de la JPRD sobre validez contractual. Clave única, condiciones y cada distractor contrastados con los pasajes citados. Objetivo: Identificar el límite material de competencia de la JPRD sobre validez contractual. Evidencia: art. 79, chunk 94. Sin certificación oficial OECE ni revisión humana independiente; se conserva el corte documental declarado."}, "estadoAnterior": "draft"}, {"numero": "Q182", "id": "68252fe0-a810-427c-8761-54daeac8e4c5", "decision": "approve", "motivo": "Reescrita una pregunta repetida o complementaria hacia un objetivo operativo distinto: Evaluar si iniciar controversia suspende automáticamente obligaciones contractuales. Clave única, condiciones y cada distractor contrastados con los pasajes citados.", "objetivo": "Evaluar si iniciar controversia suspende automáticamente obligaciones contractuales", "evidencia": [{"chunkId": "ce61a772-1181-4ad7-baf2-749cb77f5b74", "chunk_index": 89, "article": "76", "quote": "76.5. El inicio del procedimiento de solución de controversias no suspende o paraliza las obligaciones contractuales de las partes, salvo que la entidad contratante o el órgano jurisdiccional competente disponga lo contrario, de acuerdo con el plazo y condiciones establecidos en el reglamento."}], "input": {"id": "68252fe0-a810-427c-8761-54daeac8e4c5", "revision": 1, "regime": "32069", "origin": "IA:gemini:gemini-2.5-flash:lote:fc90874b-be42-4d32-9a74-5c5a85892f6f", "prompt": "En un contrato de servicios sujeto a la Ley 32069, una parte inicia un mecanismo de solución de controversias y anuncia que dejará de cumplir por ese solo hecho. Ni la entidad ni un órgano jurisdiccional competente han dispuesto suspensión. Según 76.5, ¿qué efecto tiene el inicio del procedimiento?", "options": [{"id": "A", "text": "Suspende automáticamente todas las obligaciones."}, {"id": "B", "text": "No suspende ni paraliza por sí solo las obligaciones contractuales."}, {"id": "C", "text": "Suspende únicamente las obligaciones de quien inició el mecanismo."}, {"id": "D", "text": "Extingue las obligaciones hasta que se emita decisión definitiva."}], "correctOption": "B", "explanation": "El 76.5 establece que iniciar la solución de controversias no suspende ni paraliza obligaciones, salvo disposición de la entidad u órgano jurisdiccional competente en las condiciones aplicables. El caso no presenta esa excepción.", "topic": "Controversias y solución de conflictos", "competency": "Ejecución contractual", "difficulty": "intermediate", "curriculumVersion": "oece-2025-04-25", "competencyCode": "3", "subcompetencyCode": "3.5", "cognitiveLevel": "apply", "optionRationales": {"A": "La suspensión automática contradice la regla expresa del 76.5.", "B": "El 76.5 establece que iniciar la solución de controversias no suspende ni paraliza obligaciones, salvo disposición de la entidad u órgano jurisdiccional competente en las condiciones aplicables. El caso no presenta esa excepción.", "C": "El 76.5 no crea una suspensión unilateral para quien inicia el mecanismo.", "D": "El procedimiento no extingue por sí mismo obligaciones contractuales."}, "reviewChecks": {"unambiguous": true, "distractors": true, "conditions": true, "exceptions": true, "sources": true}, "sourceCutoff": "2026-10-29", "sources": [{"documentId": "dc721f35-138c-41b8-8dca-16289f74d9df", "chunkId": "ce61a772-1181-4ad7-baf2-749cb77f5b74", "title": "Ley N.° 32069 — texto actualizado al 19.07.2026", "article": "76", "pageStart": 37, "pageEnd": 37, "quote": "76.5. El inicio del procedimiento de solución de controversias no suspende o paraliza las obligaciones contractuales de las partes, salvo que la entidad contratante o el órgano jurisdiccional competente disponga lo contrario, de acuerdo con el plazo y condiciones establecidos en el reglamento.", "version": "Texto actualizado al 19.07.2026", "sha256": "f14ffa37b824b8af03c0b97e0603839a786ed61c7ca07b1d300c9af928d133f7"}], "status": "published", "confirmReview": true, "reviewBasis": "Revisión asistida por IA el15/11/2026 por encargo y autorización expresa del administrador. Reescrita una pregunta repetida o complementaria hacia un objetivo operativo distinto: Evaluar si iniciar controversia suspende automáticamente obligaciones contractuales. Clave única, condiciones y cada distractor contrastados con los pasajes citados. Objetivo: Evaluar si iniciar controversia suspende automáticamente obligaciones contractuales. Evidencia: art. 76, chunk 89. Sin certificación oficial OECE ni revisión humana independiente; se conserva el corte documental declarado."}, "estadoAnterior": "draft"}, {"numero": "Q183", "id": "01884310-bcf1-4f89-99b2-5d8c92b0ad8d", "decision": "approve", "motivo": "Reescrita una pregunta repetida o complementaria hacia un objetivo operativo distinto: Determinar la facultad de pedir reducción proporcional de garantías tras reducción contractual. Clave única, condiciones y cada distractor contrastados con los pasajes citados.", "objetivo": "Determinar la facultad de pedir reducción proporcional de garantías tras reducción contractual", "evidencia": [{"chunkId": "30f7b478-66b4-45f8-81c8-1ef4bf4dabee", "chunk_index": 140, "article": "117", "quote": "117.3. Cuando la modificación contractual implique una reducción del monto y/o plazo, el contratista puede solicitar la disminución proporcional del monto y/o plazo de las garantías que hubiera otorgado."}], "input": {"id": "01884310-bcf1-4f89-99b2-5d8c92b0ad8d", "revision": 1, "regime": "32069", "origin": "IA:gemini:gemini-2.5-flash:lote:30f2138a-1758-46d6-84f3-fa47ebc16fd3", "prompt": "Una modificación válida reduce el monto contractual y mantiene su plazo. El contratista otorgó garantías vinculadas al monto inicial. Según 117.3, ¿qué puede solicitar respecto a ellas?", "options": [{"id": "A", "text": "La devolución íntegra de todas las garantías, aunque continúe el contrato."}, {"id": "B", "text": "La eliminación automática de su plazo por haberse reducido solo el monto."}, {"id": "C", "text": "La disminución proporcional del monto de las garantías otorgadas."}, {"id": "D", "text": "Ninguna adecuación, porque las garantías nunca cambian tras reducir el contrato."}], "correctOption": "C", "explanation": "El 117.3 permite solicitar disminución proporcional del monto y/o plazo de garantías según la reducción contractual. Si solo disminuye el monto, ello no equivale a cancelar íntegramente ni acortar sin base su vigencia.", "topic": "Penalidades, garantías, resolución y nulidad", "competency": "Ejecución contractual", "difficulty": "intermediate", "curriculumVersion": "oece-2025-04-25", "competencyCode": "3", "subcompetencyCode": "3.3", "cognitiveLevel": "apply", "optionRationales": {"A": "La reducción proporcional no equivale a devolución íntegra mientras continúan obligaciones.", "B": "La reducción solo de monto no implica por sí sola reducir el plazo que no cambió.", "C": "El 117.3 permite solicitar disminución proporcional del monto y/o plazo de garantías según la reducción contractual. Si solo disminuye el monto, ello no equivale a cancelar íntegramente ni acortar sin base su vigencia.", "D": "El 117.3 reconoce expresamente la posibilidad de pedir adecuación proporcional."}, "reviewChecks": {"unambiguous": true, "distractors": true, "conditions": true, "exceptions": true, "sources": true}, "sourceCutoff": "2026-10-29", "sources": [{"documentId": "8371bce1-f773-4ad8-8efa-1266276ae4ec", "chunkId": "30f7b478-66b4-45f8-81c8-1ef4bf4dabee", "title": "Reglamento de la Ley N.° 32069 — texto actualizado al 09.01.2026", "article": "117", "pageStart": 64, "pageEnd": 64, "quote": "117.3. Cuando la modificación contractual implique una reducción del monto y/o plazo, el contratista puede solicitar la disminución proporcional del monto y/o plazo de las garantías que hubiera otorgado.", "version": "Texto actualizado al 09.01.2026", "sha256": "0ebe95b3e05661b80f73c060d6e6ce8dd17621ce34af9277c688dd67e5d99830"}], "status": "published", "confirmReview": true, "reviewBasis": "Revisión asistida por IA el15/11/2026 por encargo y autorización expresa del administrador. Reescrita una pregunta repetida o complementaria hacia un objetivo operativo distinto: Determinar la facultad de pedir reducción proporcional de garantías tras reducción contractual. Clave única, condiciones y cada distractor contrastados con los pasajes citados. Objetivo: Determinar la facultad de pedir reducción proporcional de garantías tras reducción contractual. Evidencia: art. 117, chunk 140. Sin certificación oficial OECE ni revisión humana independiente; se conserva el corte documental declarado."}, "estadoAnterior": "draft"}, {"numero": "Q185", "id": "c46dc4c8-614a-4463-a69b-5036a1b9f853", "decision": "approve", "motivo": "Reescrita una pregunta repetida o complementaria hacia un objetivo operativo distinto: Identificar las fuentes de deducción de penalidades y el carácter subsidiario de la garantía. Clave única, condiciones y cada distractor contrastados con los pasajes citados.", "objetivo": "Identificar las fuentes de deducción de penalidades y el carácter subsidiario de la garantía", "evidencia": [{"chunkId": "45f9633f-daff-442d-9546-8fcd549b4ddd", "chunk_index": 142, "article": "119", "quote": "119.3. Estas penalidades se deducen de los pagos a cuenta, pagos parciales o del pago o liquidación final, según corresponda; o si fuera necesario, se descuenta del monto resultante de la ejecución de la garantía de fiel cumplimiento."}], "input": {"id": "c46dc4c8-614a-4463-a69b-5036a1b9f853", "revision": 1, "regime": "32069", "origin": "IA:gemini:gemini-2.5-flash:lote:24a722fb-088a-4652-8fde-4e20817fc871", "prompt": "En un contrato ordinario de servicios hay penalidades válidamente determinadas y un pago parcial pendiente. Se afirma que solo pueden cobrarse ejecutando la garantía de fiel cumplimiento. Según 119.3, ¿qué respuesta corresponde?", "options": [{"id": "A", "text": "La afirmación es correcta: nunca se deducen de pagos parciales."}, {"id": "B", "text": "Solo pueden deducirse de una liquidación final, aunque haya pagos pendientes."}, {"id": "C", "text": "Las penalidades no pueden cobrarse mientras el contrato siga vigente."}, {"id": "D", "text": "Pueden deducirse de pagos a cuenta, parciales o finales; si fuera necesario, del monto resultante de ejecutar la garantía."}], "correctOption": "D", "explanation": "El 119.3 permite deducir penalidades de pagos a cuenta, parciales o del pago o liquidación final; si resulta necesario, del monto de ejecutar la garantía de fiel cumplimiento. No exige acudir exclusivamente a esta.", "topic": "Penalidades, garantías, resolución y nulidad", "competency": "Ejecución contractual", "difficulty": "intermediate", "curriculumVersion": "oece-2025-04-25", "competencyCode": "3", "subcompetencyCode": "3.3", "cognitiveLevel": "apply", "optionRationales": {"A": "El numeral 119.3 admite expresamente deducirlas de pagos parciales.", "B": "La liquidación final es una de las vías y no la única prevista.", "C": "La regla contempla pagos durante la ejecución y no obliga a esperar al término del contrato.", "D": "El 119.3 permite deducir penalidades de pagos a cuenta, parciales o del pago o liquidación final; si resulta necesario, del monto de ejecutar la garantía de fiel cumplimiento. No exige acudir exclusivamente a esta."}, "reviewChecks": {"unambiguous": true, "distractors": true, "conditions": true, "exceptions": true, "sources": true}, "sourceCutoff": "2026-10-29", "sources": [{"documentId": "8371bce1-f773-4ad8-8efa-1266276ae4ec", "chunkId": "45f9633f-daff-442d-9546-8fcd549b4ddd", "title": "Reglamento de la Ley N.° 32069 — texto actualizado al 09.01.2026", "article": "119", "pageStart": 65, "pageEnd": 65, "quote": "119.3. Estas penalidades se deducen de los pagos a cuenta, pagos parciales o del pago o liquidación final, según corresponda; o si fuera necesario, se descuenta del monto resultante de la ejecución de la garantía de fiel cumplimiento.", "version": "Texto actualizado al 09.01.2026", "sha256": "0ebe95b3e05661b80f73c060d6e6ce8dd17621ce34af9277c688dd67e5d99830"}], "status": "published", "confirmReview": true, "reviewBasis": "Revisión asistida por IA el15/11/2026 por encargo y autorización expresa del administrador. Reescrita una pregunta repetida o complementaria hacia un objetivo operativo distinto: Identificar las fuentes de deducción de penalidades y el carácter subsidiario de la garantía. Clave única, condiciones y cada distractor contrastados con los pasajes citados. Objetivo: Identificar las fuentes de deducción de penalidades y el carácter subsidiario de la garantía. Evidencia: art. 119, chunk 142. Sin certificación oficial OECE ni revisión humana independiente; se conserva el corte documental declarado."}, "estadoAnterior": "draft"}, {"numero": "Q187", "id": "b9d5ca50-3dc2-45b8-a0a6-680db112a443", "decision": "approve", "motivo": "Reescrita una pregunta repetida o complementaria hacia un objetivo operativo distinto: Diferenciar causal de nulidad por documentación de adjudicación y exigencia de descargo. Clave única, condiciones y cada distractor contrastados con los pasajes citados.", "objetivo": "Diferenciar causal de nulidad por documentación de adjudicación y exigencia de descargo", "evidencia": [{"chunkId": "3016b588-4a2d-47a5-ad89-facd7d55859f", "chunk_index": 84, "article": "71", "quote": "71.1. Después de perfeccionados los contratos, la autoridad de la gestión administrativa de la entidad contratante puede declarar su nulidad en los siguientes casos: a) Por haberse suscrito con un proveedor impedido para contratar con el Estado. b) Cuando se verifique que, durante el procedimiento de selección, se haya presentado documentación falsa, adulterada o con información inexacta que haya sustentado la adjudicación de la buena pro en el procedimiento de selección, previo descargo del contr atista. c) Cuando se haya suscrito, a pesar de encontrarse en trámite un recurso de apelación. d) Cuando se haya suscrito prescindiendo del procedimiento de selección competitivo respectivo o no se haya cumplido con las condiciones establecidas para utilizar un procedimiento de selección no competitivo o cuando, pese a que correspondía aplicar los p rocesos de contratación previstos en la presente ley, se simuló la aplicación de alguno de los supuestos excluidos a los que se hace referencia en el artículo 7 de la presente ley. e) Cuando por sentencia consentida o ejecutoriada, se evidencie que durante el procedimiento de selección o para el perfeccionamiento del contrato, sus accionistas, socios o empresas vinculadas, o cualquiera de sus respectivos directores, funcionarios, empleados, asesores, repres entantes legales o apoderados, haya pagado, recibido, ofrecido, intentado pagar o recibir u ofrecer en el futuro algún pago, beneficio indebido, dádiva o comisión. Esta nulidad se declara sin perjuicio de la responsabilidad administrativa, civil y penal a que hubiere lugar."}], "input": {"id": "b9d5ca50-3dc2-45b8-a0a6-680db112a443", "revision": 1, "regime": "32069", "origin": "IA:gemini:gemini-2.5-flash:lote:17351734-dcc1-4af2-a450-1e0b193f4341", "prompt": "Después de perfeccionar un contrato ordinario, se verifica que documentación falsa presentada durante la selección sustentó la adjudicación. Según 71.1.bde la Ley, ¿qué actuación contempla esa causal?", "options": [{"id": "A", "text": "La autoridad de gestión administrativa puede declarar nulidad, previo descargo del contratista."}, {"id": "B", "text": "La DEC declara nulidad sin descargo por ser quien custodia el expediente."}, {"id": "C", "text": "El contratista declara unilateralmente la nulidad y queda liberado de todo procedimiento."}, {"id": "D", "text": "La falsedad solo puede examinarse al liquidar, sin posibilidad de nulidad contractual."}], "correctOption": "A", "explanation": "El 71.1.bpermite a la autoridad de gestión administrativa declarar nulidad por documentación falsa, adulterada o inexacta que sustentó la adjudicación, previo descargo del contratista. La fase y el vínculo con la adjudicación están expresos.", "topic": "Penalidades, garantías, resolución y nulidad", "competency": "Ejecución contractual", "difficulty": "intermediate", "curriculumVersion": "oece-2025-04-25", "competencyCode": "3", "subcompetencyCode": "3.3", "cognitiveLevel": "apply", "optionRationales": {"A": "El 71.1.bpermite a la autoridad de gestión administrativa declarar nulidad por documentación falsa, adulterada o inexacta que sustentó la adjudicación, previo descargo del contratista. La fase y el vínculo con la adjudicación están expresos.", "B": "La norma atribuye la facultad a la autoridad de gestión administrativa y exige descargo.", "C": "El 71.1 no atribuye declaración unilateral de nulidad al contratista.", "D": "La causal opera después del perfeccionamiento y no se difiere necesariamente a la liquidación."}, "reviewChecks": {"unambiguous": true, "distractors": true, "conditions": true, "exceptions": true, "sources": true}, "sourceCutoff": "2026-10-29", "sources": [{"documentId": "dc721f35-138c-41b8-8dca-16289f74d9df", "chunkId": "3016b588-4a2d-47a5-ad89-facd7d55859f", "title": "Ley N.° 32069 — texto actualizado al 19.07.2026", "article": "71", "pageStart": 35, "pageEnd": 35, "quote": "71.1. Después de perfeccionados los contratos, la autoridad de la gestión administrativa de la entidad contratante puede declarar su nulidad en los siguientes casos: a) Por haberse suscrito con un proveedor impedido para contratar con el Estado. b) Cuando se verifique que, durante el procedimiento de selección, se haya presentado documentación falsa, adulterada o con información inexacta que haya sustentado la adjudicación de la buena pro en el procedimiento de selección, previo descargo del contr atista. c) Cuando se haya suscrito, a pesar de encontrarse en trámite un recurso de apelación. d) Cuando se haya suscrito prescindiendo del procedimiento de selección competitivo respectivo o no se haya cumplido con las condiciones establecidas para utilizar un procedimiento de selección no competitivo o cuando, pese a que correspondía aplicar los p rocesos de contratación previstos en la presente ley, se simuló la aplicación de alguno de los supuestos excluidos a los que se hace referencia en el artículo 7 de la presente ley. e) Cuando por sentencia consentida o ejecutoriada, se evidencie que durante el procedimiento de selección o para el perfeccionamiento del contrato, sus accionistas, socios o empresas vinculadas, o cualquiera de sus respectivos directores, funcionarios, empleados, asesores, repres entantes legales o apoderados, haya pagado, recibido, ofrecido, intentado pagar o recibir u ofrecer en el futuro algún pago, beneficio indebido, dádiva o comisión. Esta nulidad se declara sin perjuicio de la responsabilidad administrativa, civil y penal a que hubiere lugar.", "version": "Texto actualizado al 19.07.2026", "sha256": "f14ffa37b824b8af03c0b97e0603839a786ed61c7ca07b1d300c9af928d133f7"}], "status": "published", "confirmReview": true, "reviewBasis": "Revisión asistida por IA el15/11/2026 por encargo y autorización expresa del administrador. Reescrita una pregunta repetida o complementaria hacia un objetivo operativo distinto: Diferenciar causal de nulidad por documentación de adjudicación y exigencia de descargo. Clave única, condiciones y cada distractor contrastados con los pasajes citados. Objetivo: Diferenciar causal de nulidad por documentación de adjudicación y exigencia de descargo. Evidencia: art. 71, chunk 84. Sin certificación oficial OECE ni revisión humana independiente; se conserva el corte documental declarado."}, "estadoAnterior": "draft"}, {"numero": "Q188", "id": "fd62f380-fe02-423e-afc4-f6adf22adb40", "decision": "approve", "motivo": "Reescrita una pregunta repetida o complementaria hacia un objetivo operativo distinto: Evaluar continuación excepcional de ejecución pese a vicio de nulidad y carácter indelegable. Clave única, condiciones y cada distractor contrastados con los pasajes citados.", "objetivo": "Evaluar continuación excepcional de ejecución pese a vicio de nulidad y carácter indelegable", "evidencia": [{"chunkId": "3016b588-4a2d-47a5-ad89-facd7d55859f", "chunk_index": 84, "article": "71", "quote": "71.3. Aun cuando se verifique la configuración de un vicio de nulidad del contrato, la autoridad de la gestión administrativa puede autorizar la continuación de su ejecución, previos informes técnicos y legales favorables que sustenten tal necesidad basada en un análisis costo - beneficio orientado al cumplimiento de la finalidad pública del contrato y de los principios que rigen esta ley, sin perjuicio del deslinde de responsabilidades que corresponda. Esta facultad es indelegable."}], "input": {"id": "fd62f380-fe02-423e-afc4-f6adf22adb40", "revision": 2, "regime": "32069", "origin": "IA:gemini:gemini-2.5-flash:lote:cf94b24d-0b37-4b86-aca9-1525b19f75cd", "prompt": "En un contrato de servicios se configura un vicio de nulidad. Existen informes técnicos y legales favorables y análisis costo-beneficio orientado a su finalidad pública. Según 71.3, ¿qué facultad tiene la autoridad de gestión administrativa?", "options": [{"id": "A", "text": "Debe detener siempre la ejecución, sin que la Ley admita continuación."}, {"id": "B", "text": "Puede autorizar la continuación con esos presupuestos; la facultad es indelegable y no elimina responsabilidades."}, {"id": "C", "text": "Puede ordenar continuación sin informes si considera urgente la prestación."}, {"id": "D", "text": "Puede delegar libremente la decisión de continuar al área usuaria."}], "correctOption": "B", "explanation": "El 71.3 permite autorizar continuación con informes técnicos y legales favorables y análisis costo-beneficio orientado a finalidad pública y principios. La facultad es indelegable y no suprime el deslinde de responsabilidades.", "topic": "Penalidades, garantías, resolución y nulidad", "competency": "Ejecución contractual", "difficulty": "intermediate", "curriculumVersion": "oece-2025-04-25", "competencyCode": "3", "subcompetencyCode": "3.3", "cognitiveLevel": "analyze", "optionRationales": {"A": "El 71.3 contempla expresamente una facultad excepcional de continuación.", "B": "El 71.3 permite autorizar continuación con informes técnicos y legales favorables y análisis costo-beneficio orientado a finalidad pública y principios. La facultad es indelegable y no suprime el deslinde de responsabilidades.", "C": "La urgencia no sustituye los informes favorables ni el análisis que exige 71.3.", "D": "El 71.3 declara indelegable esa facultad."}, "reviewChecks": {"unambiguous": true, "distractors": true, "conditions": true, "exceptions": true, "sources": true}, "sourceCutoff": "2026-10-29", "sources": [{"documentId": "dc721f35-138c-41b8-8dca-16289f74d9df", "chunkId": "3016b588-4a2d-47a5-ad89-facd7d55859f", "title": "Ley N.° 32069 — texto actualizado al 19.07.2026", "article": "71", "pageStart": 35, "pageEnd": 35, "quote": "71.3. Aun cuando se verifique la configuración de un vicio de nulidad del contrato, la autoridad de la gestión administrativa puede autorizar la continuación de su ejecución, previos informes técnicos y legales favorables que sustenten tal necesidad basada en un análisis costo - beneficio orientado al cumplimiento de la finalidad pública del contrato y de los principios que rigen esta ley, sin perjuicio del deslinde de responsabilidades que corresponda. Esta facultad es indelegable.", "version": "Texto actualizado al 19.07.2026", "sha256": "f14ffa37b824b8af03c0b97e0603839a786ed61c7ca07b1d300c9af928d133f7"}], "status": "published", "confirmReview": true, "reviewBasis": "Revisión asistida por IA el15/11/2026 por encargo y autorización expresa del administrador. Reescrita una pregunta repetida o complementaria hacia un objetivo operativo distinto: Evaluar continuación excepcional de ejecución pese a vicio de nulidad y carácter indelegable. Clave única, condiciones y cada distractor contrastados con los pasajes citados. Objetivo: Evaluar continuación excepcional de ejecución pese a vicio de nulidad y carácter indelegable. Evidencia: art. 71, chunk 84. Sin certificación oficial OECE ni revisión humana independiente; se conserva el corte documental declarado."}, "estadoAnterior": "draft"}, {"numero": "Q192", "id": "b0c28267-d367-4c97-9e8e-702092fef41a", "decision": "approve", "motivo": "Reescrita una pregunta repetida o complementaria hacia un objetivo operativo distinto: Calcular tope de adicional en bienes y reconocer indispensabilidad para la finalidad contractual. Clave única, condiciones y cada distractor contrastados con los pasajes citados.", "objetivo": "Calcular tope de adicional en bienes y reconocer indispensabilidad para la finalidad contractual", "evidencia": [{"chunkId": "2a26061b-aebc-4f88-bf47-ca8ca47c1013", "chunk_index": 76, "article": "64", "quote": "64.1. En caso de bienes, servicios y consultorías de obras, la autoridad de la gestión administrativa puede autorizar, ordenar y pagar directamente la ejecución de prestaciones adicionales hasta por el 25 % del monto del contrato original, siempre que sean indispensables\n\npara alcanzar la finalidad del contrato. Asimismo, puede reducir bienes, servicios, consultorías u obras hasta por el mismo porcentaje."}], "input": {"id": "b0c28267-d367-4c97-9e8e-702092fef41a", "revision": 1, "regime": "32069", "origin": "IA:gemini:gemini-2.5-flash:lote:78051880-54d5-4566-ae72-ca7eb6c17495", "prompt": "En un contrato ordinario de bienes de S/200 000 se evalúan adicionales indispensables para alcanzar su finalidad. No es un mecanismo diferenciado de tecnologías sanitarias. Según 64.1 de la Ley, ¿cuál es el máximo por ese numeral?", "options": [{"id": "A", "text": "S/30 000, porque siempre se aplica el 15% previsto para obras."}, {"id": "B", "text": "S/100 000, equivalente al 50% del contrato original."}, {"id": "C", "text": "S/50 000, equivalente al 25% del monto original."}, {"id": "D", "text": "Cualquier monto que acepte el contratista, sin límite porcentual."}], "correctOption": "C", "explanation": "El 64.1 permite a la autoridad de gestión administrativa autorizar, ordenar y pagar adicionales de bienes hasta 25% del contrato original cuando son indispensables para su finalidad: S/50 000 en el caso. No se traslada el umbral especial de obras.", "topic": "Modificaciones contractuales", "competency": "Ejecución contractual", "difficulty": "intermediate", "curriculumVersion": "oece-2025-04-25", "competencyCode": "3", "subcompetencyCode": "3.2", "cognitiveLevel": "apply", "optionRationales": {"A": "El 15% del 64.2 corresponde a adicionales de obras bajo su supuesto, no a este contrato de bienes.", "B": "El 64.1 no fija 50% para adicionales ordinarios de bienes.", "C": "El 64.1 permite a la autoridad de gestión administrativa autorizar, ordenar y pagar adicionales de bienes hasta 25% del contrato original cuando son indispensables para su finalidad: S/50 000 en el caso. No se traslada el umbral especial de obras.", "D": "El acuerdo del contratista no elimina el límite ni las condiciones legales."}, "reviewChecks": {"unambiguous": true, "distractors": true, "conditions": true, "exceptions": true, "sources": true}, "sourceCutoff": "2026-10-29", "sources": [{"documentId": "dc721f35-138c-41b8-8dca-16289f74d9df", "chunkId": "2a26061b-aebc-4f88-bf47-ca8ca47c1013", "title": "Ley N.° 32069 — texto actualizado al 19.07.2026", "article": "64", "pageStart": 30, "pageEnd": 31, "quote": "64.1. En caso de bienes, servicios y consultorías de obras, la autoridad de la gestión administrativa puede autorizar, ordenar y pagar directamente la ejecución de prestaciones adicionales hasta por el 25 % del monto del contrato original, siempre que sean indispensables\n\npara alcanzar la finalidad del contrato. Asimismo, puede reducir bienes, servicios, consultorías u obras hasta por el mismo porcentaje.", "version": "Texto actualizado al 19.07.2026", "sha256": "f14ffa37b824b8af03c0b97e0603839a786ed61c7ca07b1d300c9af928d133f7"}], "status": "published", "confirmReview": true, "reviewBasis": "Revisión asistida por IA el15/11/2026 por encargo y autorización expresa del administrador. Reescrita una pregunta repetida o complementaria hacia un objetivo operativo distinto: Calcular tope de adicional en bienes y reconocer indispensabilidad para la finalidad contractual. Clave única, condiciones y cada distractor contrastados con los pasajes citados. Objetivo: Calcular tope de adicional en bienes y reconocer indispensabilidad para la finalidad contractual. Evidencia: art. 64, chunk 76. Sin certificación oficial OECE ni revisión humana independiente; se conserva el corte documental declarado."}, "estadoAnterior": "draft"}, {"numero": "Q194", "id": "a711b872-67f0-45b7-9a68-eb48b06fcd30", "decision": "approve", "motivo": "Reescrita una pregunta repetida o complementaria hacia un objetivo operativo distinto: Aplicar límite de reducción de obra ordinaria sin confundirlo con umbrales de adicionales. Clave única, condiciones y cada distractor contrastados con los pasajes citados.", "objetivo": "Aplicar límite de reducción de obra ordinaria sin confundirlo con umbrales de adicionales", "evidencia": [{"chunkId": "2a26061b-aebc-4f88-bf47-ca8ca47c1013", "chunk_index": 76, "article": "64", "quote": "64.1. En caso de bienes, servicios y consultorías de obras, la autoridad de la gestión administrativa puede autorizar, ordenar y pagar directamente la ejecución de prestaciones adicionales hasta por el 25 % del monto del contrato original, siempre que sean indispensables\n\npara alcanzar la finalidad del contrato. Asimismo, puede reducir bienes, servicios, consultorías u obras hasta por el mismo porcentaje."}], "input": {"id": "a711b872-67f0-45b7-9a68-eb48b06fcd30", "revision": 2, "regime": "32069", "origin": "IA:gemini:gemini-2.5-flash:lote:78051880-54d5-4566-ae72-ca7eb6c17495", "prompt": "En una obra ordinaria de S/1 000 000 que no usa contrato estandarizado internacional ni régimen diferenciado, la autoridad de gestión administrativa evalúa reducir prestaciones. Según 64.1 de la Ley, ¿qué máximo porcentual de reducción establece ese numeral?", "options": [{"id": "A", "text": "15%, porque toda reducción usa el primer umbral de adicionales de obra."}, {"id": "B", "text": "50%, porque toda reducción se equipara al mayor adicional de obra."}, {"id": "C", "text": "No existe límite, porque reducir nunca requiere aplicar porcentajes."}, {"id": "D", "text": "25%, equivalente a S/250 000 del contrato original."}], "correctOption": "D", "explanation": "El 64.1 permite reducir bienes, servicios, consultorías u obras hasta 25% del monto original. Para S/1 000 000 son S/250 000; no se confunde con los umbrales distintos para adicionales de obra.", "topic": "Modificaciones contractuales", "competency": "Ejecución contractual", "difficulty": "intermediate", "curriculumVersion": "oece-2025-04-25", "competencyCode": "3", "subcompetencyCode": "3.2", "cognitiveLevel": "apply", "optionRationales": {"A": "El 15% del 64.2 no es el límite de reducción previsto por 64.1.", "B": "El 50% de otros supuestos de adicionales no reemplaza el 25% de reducción del 64.1.", "C": "El numeral 64.1 establece expresamente un máximo de reducción.", "D": "El 64.1 permite reducir bienes, servicios, consultorías u obras hasta 25% del monto original. Para S/1 000 000 son S/250 000; no se confunde con los umbrales distintos para adicionales de obra."}, "reviewChecks": {"unambiguous": true, "distractors": true, "conditions": true, "exceptions": true, "sources": true}, "sourceCutoff": "2026-10-29", "sources": [{"documentId": "dc721f35-138c-41b8-8dca-16289f74d9df", "chunkId": "2a26061b-aebc-4f88-bf47-ca8ca47c1013", "title": "Ley N.° 32069 — texto actualizado al 19.07.2026", "article": "64", "pageStart": 30, "pageEnd": 31, "quote": "64.1. En caso de bienes, servicios y consultorías de obras, la autoridad de la gestión administrativa puede autorizar, ordenar y pagar directamente la ejecución de prestaciones adicionales hasta por el 25 % del monto del contrato original, siempre que sean indispensables\n\npara alcanzar la finalidad del contrato. Asimismo, puede reducir bienes, servicios, consultorías u obras hasta por el mismo porcentaje.", "version": "Texto actualizado al 19.07.2026", "sha256": "f14ffa37b824b8af03c0b97e0603839a786ed61c7ca07b1d300c9af928d133f7"}], "status": "published", "confirmReview": true, "reviewBasis": "Revisión asistida por IA el15/11/2026 por encargo y autorización expresa del administrador. Reescrita una pregunta repetida o complementaria hacia un objetivo operativo distinto: Aplicar límite de reducción de obra ordinaria sin confundirlo con umbrales de adicionales. Clave única, condiciones y cada distractor contrastados con los pasajes citados. Objetivo: Aplicar límite de reducción de obra ordinaria sin confundirlo con umbrales de adicionales. Evidencia: art. 64, chunk 76. Sin certificación oficial OECE ni revisión humana independiente; se conserva el corte documental declarado."}, "estadoAnterior": "draft"}, {"numero": "Q195", "id": "4a7facf2-01ff-4d30-9369-03dfab571b37", "decision": "approve", "motivo": "Reescrita una pregunta repetida o complementaria hacia un objetivo operativo distinto: Distinguir recepción física de bienes y conformidad emitida por el área usuaria. Clave única, condiciones y cada distractor contrastados con los pasajes citados.", "objetivo": "Distinguir recepción física de bienes y conformidad emitida por el área usuaria", "evidencia": [{"chunkId": "75408d51-d4b5-402c-9fc3-3cccd43a8dd0", "chunk_index": 170, "article": "144", "quote": "144.1. El área usuaria es responsable de brindar la conformidad, para lo cual verifica el cumplimiento de las especificaciones técnicas o términos de referencia. En el caso de bienes, realiza el respectivo control de calidad, de haberse establecido en el r equerimiento. 144.2. En el caso de bienes, la recepción de los bienes adquiridos se rige de acuerdo con la normativa del Sistema Nacional de Abastecimiento.\n\nReglamento de la Ley Nº 32069, Ley General de Contrataciones Públicas Página 77 de 249 144.3. La conformidad se emite en un plazo máximo de siete días contabilizados desde el día siguiente de recibido el entregable, salvo que se requiera efectuar pruebas que permitan verificar el cumplimiento de la obligación, o si se trata de consultorías, en cuyo caso la conformidad se emite en un plazo máximo de veinte días, bajo responsabilidad del servidor o funcionario que debe emitir la conformidad. La sola recepción de bienes en la entidad o en el destino final, según sea el caso, no constituye la con formidad del área usuaria."}], "input": {"id": "4a7facf2-01ff-4d30-9369-03dfab571b37", "revision": 1, "regime": "32069", "origin": "IA:gemini:gemini-2.5-flash:lote:10278395-5aee-4fb0-a34a-43f1b78f4284", "prompt": "Un proveedor entregó bienes en el almacén y obtuvo constancia de recepción física. El área usuaria aún no verificó el cumplimiento técnico ni emitió conformidad. Según 144.1 y 144.3, ¿la sola recepción ya equivale a esa conformidad?", "options": [{"id": "A", "text": "No; la sola recepción no constituye conformidad y esta corresponde al área usuaria tras verificar el cumplimiento."}, {"id": "B", "text": "Sí; toda recepción de almacén sustituye la verificación del área usuaria."}, {"id": "C", "text": "Sí; basta que el proveedor firme la constancia para emitirla por su cuenta."}, {"id": "D", "text": "No; porque en bienes nunca corresponde otorgar conformidad, únicamente recepción física."}], "correctOption": "A", "explanation": "La sola recepción de bienes no constituye conformidad del área usuaria. El 144.1 atribuye a esta verificar especificaciones o términos aplicables y brindar conformidad; la constancia de entrega no la sustituye.", "topic": "Entrega, conformidad y observaciones", "competency": "Ejecución contractual", "difficulty": "intermediate", "curriculumVersion": "oece-2025-04-25", "competencyCode": "3", "subcompetencyCode": "3.4", "cognitiveLevel": "apply", "optionRationales": {"A": "La sola recepción de bienes no constituye conformidad del área usuaria. El 144.1 atribuye a esta verificar especificaciones o términos aplicables y brindar conformidad; la constancia de entrega no la sustituye.", "B": "El 144.3 niega expresamente que la sola recepción equivalga a conformidad.", "C": "El 144.1 no atribuye al proveedor emitir la conformidad del área usuaria.", "D": "Los numerales 144.1 y 144.3 distinguen ambos actos, sin suprimir la conformidad para bienes."}, "reviewChecks": {"unambiguous": true, "distractors": true, "conditions": true, "exceptions": true, "sources": true}, "sourceCutoff": "2026-10-29", "sources": [{"documentId": "8371bce1-f773-4ad8-8efa-1266276ae4ec", "chunkId": "75408d51-d4b5-402c-9fc3-3cccd43a8dd0", "title": "Reglamento de la Ley N.° 32069 — texto actualizado al 09.01.2026", "article": "144", "pageStart": 76, "pageEnd": 77, "quote": "144.1. El área usuaria es responsable de brindar la conformidad, para lo cual verifica el cumplimiento de las especificaciones técnicas o términos de referencia. En el caso de bienes, realiza el respectivo control de calidad, de haberse establecido en el r equerimiento. 144.2. En el caso de bienes, la recepción de los bienes adquiridos se rige de acuerdo con la normativa del Sistema Nacional de Abastecimiento.\n\nReglamento de la Ley Nº 32069, Ley General de Contrataciones Públicas Página 77 de 249 144.3. La conformidad se emite en un plazo máximo de siete días contabilizados desde el día siguiente de recibido el entregable, salvo que se requiera efectuar pruebas que permitan verificar el cumplimiento de la obligación, o si se trata de consultorías, en cuyo caso la conformidad se emite en un plazo máximo de veinte días, bajo responsabilidad del servidor o funcionario que debe emitir la conformidad. La sola recepción de bienes en la entidad o en el destino final, según sea el caso, no constituye la con formidad del área usuaria.", "version": "Texto actualizado al 09.01.2026", "sha256": "0ebe95b3e05661b80f73c060d6e6ce8dd17621ce34af9277c688dd67e5d99830"}], "status": "published", "confirmReview": true, "reviewBasis": "Revisión asistida por IA el15/11/2026 por encargo y autorización expresa del administrador. Reescrita una pregunta repetida o complementaria hacia un objetivo operativo distinto: Distinguir recepción física de bienes y conformidad emitida por el área usuaria. Clave única, condiciones y cada distractor contrastados con los pasajes citados. Objetivo: Distinguir recepción física de bienes y conformidad emitida por el área usuaria. Evidencia: art. 144, chunk 170. Sin certificación oficial OECE ni revisión humana independiente; se conserva el corte documental declarado."}, "estadoAnterior": "draft"}, {"numero": "Q197", "id": "a1773634-fc27-45a5-9ecc-6bb03c15b44a", "decision": "approve", "motivo": "Reescrita una pregunta repetida o complementaria hacia un objetivo operativo distinto: Identificar condiciones para ceder posición entre entidades por desaparición y traslado de necesidad. Clave única, condiciones y cada distractor contrastados con los pasajes citados.", "objetivo": "Identificar condiciones para ceder posición entre entidades por desaparición y traslado de necesidad", "evidencia": [{"chunkId": "b44c4b40-7721-4232-80ce-a6bcfb180219", "chunk_index": 134, "article": "112", "quote": "112.2. La cesión de posición contractual de una entidad contratante a otra puede darse en los siguientes casos, previo sustento técnico legal de la DEC: a) Cuando las funciones de una entidad contratante sean trasladadas a otra que, como consecuencia, asume su posición contractual en los contratos relacionados con estas funciones. b) Cuando la entidad contratante se extinga, fusione, escinda o sea absorbida por otra. c) Cuando desaparezca la necesidad de la entidad contratante y la entidad cesionaria acredite dicha necesidad programada en su CMN, siempre que se sustente que la cesión resulta económica y técnicamente más ventajosa para el Estado, de acuerdo con los prin cipios de eficacia y eficiencia y vigencia tecnológica, entre otros, que resulten aplicables. d) Por norma expresa.\n\nReglamento de la Ley Nº 32069, Ley General de Contrataciones Públicas Página 62 de 249 SUBCAPÍTULO 2 Garantías"}], "input": {"id": "a1773634-fc27-45a5-9ecc-6bb03c15b44a", "revision": 1, "regime": "32069", "origin": "IA:gemini:gemini-2.5-flash:lote:10a37972-b686-47b1-a767-b8540c6c0bc7", "prompt": "Una entidad ya no necesita una prestación contratada y otra entidad acredita esa necesidad programada en su CMN. Según 112.2.c, ¿qué sustento adicional exige esa vía de cesión de posición contractual entre entidades?", "options": [{"id": "A", "text": "Solo acuerdo informal de los jefes, sin necesidad programada ni sustento."}, {"id": "B", "text": "Sustento técnico legal de la DEC y que la cesión resulte económica y técnicamente más ventajosa para el Estado."}, {"id": "C", "text": "Una multa al proveedor que sustituya el análisis técnico legal."}, {"id": "D", "text": "Que la cesionaria carezca de la necesidad en su CMN, para evitar cualquier programación."}], "correctOption": "B", "explanation": "La vía del 112.2.c, con sustento técnico legal de la DEC, exige necesidad programada de la cesionaria y justificar que la cesión sea económica y técnicamente más ventajosa para el Estado. No basta la desaparición de la necesidad original.", "topic": "Modificaciones contractuales", "competency": "Ejecución contractual", "difficulty": "intermediate", "curriculumVersion": "oece-2025-04-25", "competencyCode": "3", "subcompetencyCode": "3.2", "cognitiveLevel": "apply", "optionRationales": {"A": "El 112.2 exige sustento técnico legal y condiciones que no se sustituyen por acuerdo informal.", "B": "La vía del 112.2.c, con sustento técnico legal de la DEC, exige necesidad programada de la cesionaria y justificar que la cesión sea económica y técnicamente más ventajosa para el Estado. No basta la desaparición de la necesidad original.", "C": "La sanción al proveedor no es el sustento de esta cesión entre entidades.", "D": "El 112.2.cexige precisamente necesidad programada en el CMN de la cesionaria."}, "reviewChecks": {"unambiguous": true, "distractors": true, "conditions": true, "exceptions": true, "sources": true}, "sourceCutoff": "2026-10-29", "sources": [{"documentId": "8371bce1-f773-4ad8-8efa-1266276ae4ec", "chunkId": "b44c4b40-7721-4232-80ce-a6bcfb180219", "title": "Reglamento de la Ley N.° 32069 — texto actualizado al 09.01.2026", "article": "112", "pageStart": 61, "pageEnd": 62, "quote": "112.2. La cesión de posición contractual de una entidad contratante a otra puede darse en los siguientes casos, previo sustento técnico legal de la DEC: a) Cuando las funciones de una entidad contratante sean trasladadas a otra que, como consecuencia, asume su posición contractual en los contratos relacionados con estas funciones. b) Cuando la entidad contratante se extinga, fusione, escinda o sea absorbida por otra. c) Cuando desaparezca la necesidad de la entidad contratante y la entidad cesionaria acredite dicha necesidad programada en su CMN, siempre que se sustente que la cesión resulta económica y técnicamente más ventajosa para el Estado, de acuerdo con los prin cipios de eficacia y eficiencia y vigencia tecnológica, entre otros, que resulten aplicables. d) Por norma expresa.\n\nReglamento de la Ley Nº 32069, Ley General de Contrataciones Públicas Página 62 de 249 SUBCAPÍTULO 2 Garantías", "version": "Texto actualizado al 09.01.2026", "sha256": "0ebe95b3e05661b80f73c060d6e6ce8dd17621ce34af9277c688dd67e5d99830"}], "status": "published", "confirmReview": true, "reviewBasis": "Revisión asistida por IA el15/11/2026 por encargo y autorización expresa del administrador. Reescrita una pregunta repetida o complementaria hacia un objetivo operativo distinto: Identificar condiciones para ceder posición entre entidades por desaparición y traslado de necesidad. Clave única, condiciones y cada distractor contrastados con los pasajes citados. Objetivo: Identificar condiciones para ceder posición entre entidades por desaparición y traslado de necesidad. Evidencia: art. 112, chunk 134. Sin certificación oficial OECE ni revisión humana independiente; se conserva el corte documental declarado."}, "estadoAnterior": "draft"}, {"numero": "Q199", "id": "e3fe0d6c-66b4-46e2-af0c-c24d091a4b50", "decision": "approve", "motivo": "Reescrita una pregunta repetida o complementaria hacia un objetivo operativo distinto: Aplicar excepción a aceptación de amortización total de adelanto de materiales cuando saldo supera valorización. Clave única, condiciones y cada distractor contrastados con los pasajes citados.", "objetivo": "Aplicar excepción a aceptación de amortización total de adelanto de materiales cuando saldo supera valorización", "evidencia": [{"chunkId": "cf28fb4f-590a-4703-b130-785bcc00809f", "chunk_index": 217, "article": "180", "quote": "180.2. La amortización del adelanto para materiales, insumos, equipamiento y mobiliario para obras se realiza de acuerdo con lo dispuesto en la directiva que la DGA emita sobre fórmulas polinómicas. La entidad contratante acepta la amortización total del a delanto, a solicitud del contratista, salvo que el saldo pendiente de amortizar sea mayor que el monto de la valorización.\n\nReglamento de la Ley Nº 32069, Ley General de Contrataciones Públicas Página 98 de 249"}], "input": {"id": "e3fe0d6c-66b4-46e2-af0c-c24d091a4b50", "revision": 1, "regime": "32069", "origin": "IA:gemini:gemini-2.5-flash:lote:22452f3e-94da-419b-88b3-ae6131e04ad5", "prompt": "En una obra, el contratista pide amortizar íntegramente un adelanto para materiales. El saldo pendiente es S/80 000 y la valorización correspondiente es S/50 000. Según 180.2, ¿está obligada la entidad a aceptar esa amortización total en dicha valorización?", "options": [{"id": "A", "text": "Sí; la solicitud elimina toda comparación con el monto valorizado."}, {"id": "B", "text": "Sí; debe incrementar la valorización a S/80 000 aunque no corresponda a lo ejecutado."}, {"id": "C", "text": "No; el saldo pendiente supera la valorización y opera la excepción del numeral 180.2."}, {"id": "D", "text": "Sí; se elimina automáticamente el saldo que excede la valorización."}], "correctOption": "C", "explanation": "El 180.2 ordena aceptar la amortización total solicitada salvo que el saldo pendiente sea mayor que la valorización. S/80 000 supera S/50 000; esa excepción impide exigir la aceptación total por esa sola solicitud.", "topic": "Adelantos y amortización", "competency": "Ejecución contractual", "difficulty": "intermediate", "curriculumVersion": "oece-2025-04-25", "competencyCode": "3", "subcompetencyCode": "3.9", "cognitiveLevel": "apply", "optionRationales": {"A": "La regla incluye una excepción por comparación de saldo y valorización.", "B": "El 180.2 no ordena aumentar artificialmente una valorización para igualar el saldo.", "C": "El 180.2 ordena aceptar la amortización total solicitada salvo que el saldo pendiente sea mayor que la valorización. S/80 000 supera S/50 000; esa excepción impide exigir la aceptación total por esa sola solicitud.", "D": "El exceso de saldo no se condona ni desaparece por solicitar amortización total."}, "reviewChecks": {"unambiguous": true, "distractors": true, "conditions": true, "exceptions": true, "sources": true}, "sourceCutoff": "2026-10-29", "sources": [{"documentId": "8371bce1-f773-4ad8-8efa-1266276ae4ec", "chunkId": "cf28fb4f-590a-4703-b130-785bcc00809f", "title": "Reglamento de la Ley N.° 32069 — texto actualizado al 09.01.2026", "article": "180", "pageStart": 97, "pageEnd": 98, "quote": "180.2. La amortización del adelanto para materiales, insumos, equipamiento y mobiliario para obras se realiza de acuerdo con lo dispuesto en la directiva que la DGA emita sobre fórmulas polinómicas. La entidad contratante acepta la amortización total del a delanto, a solicitud del contratista, salvo que el saldo pendiente de amortizar sea mayor que el monto de la valorización.\n\nReglamento de la Ley Nº 32069, Ley General de Contrataciones Públicas Página 98 de 249", "version": "Texto actualizado al 09.01.2026", "sha256": "0ebe95b3e05661b80f73c060d6e6ce8dd17621ce34af9277c688dd67e5d99830"}], "status": "published", "confirmReview": true, "reviewBasis": "Revisión asistida por IA el15/11/2026 por encargo y autorización expresa del administrador. Reescrita una pregunta repetida o complementaria hacia un objetivo operativo distinto: Aplicar excepción a aceptación de amortización total de adelanto de materiales cuando saldo supera valorización. Clave única, condiciones y cada distractor contrastados con los pasajes citados. Objetivo: Aplicar excepción a aceptación de amortización total de adelanto de materiales cuando saldo supera valorización. Evidencia: art. 180, chunk 217. Sin certificación oficial OECE ni revisión humana independiente; se conserva el corte documental declarado."}, "estadoAnterior": "draft"}, {"numero": "Q205", "id": "e13dd18b-9b39-47aa-8a5d-8ff4b4474d2f", "decision": "approve", "motivo": "Reescrita una pregunta repetida o complementaria hacia un objetivo operativo distinto: Reconocer que revisión inicial del expediente no impide aprobar modificaciones no advertidas. Clave única, condiciones y cada distractor contrastados con los pasajes citados.", "objetivo": "Reconocer que revisión inicial del expediente no impide aprobar modificaciones no advertidas", "evidencia": [{"chunkId": "c1a3d4f1-7ee0-4a3e-95e4-b0ad864819ba", "chunk_index": 205, "article": "171", "quote": "171.1. En el sistema de entrega de solo construcción, el contratista presenta a la entidad contratante y al supervisor un informe técnico de revisión del expediente técnico dentro de los\n\nReglamento de la Ley Nº 32069, Ley General de Contrataciones Públicas Página 92 de 249 doce días siguientes a la suscripción del contrato. Este informe tiene como objetivo detectar posibles deficiencias u omisiones en el expediente técnico, e incluye las posibles prestaciones adicionales, riesgos y otros aspectos que puedan ser advertidos de la sola revisión documental por parte del contratista. Esta revisión no impide la aprobación de modificaciones contractuales no advertidas en el informe técnico."}], "input": {"id": "e13dd18b-9b39-47aa-8a5d-8ff4b4474d2f", "revision": 1, "regime": "32069", "origin": "IA:gemini:gemini-2.5-flash:lote:3fbaff8b-d72e-4a26-a84d-f10f2225c15e", "prompt": "En una obra de solo construcción, el informe inicial de revisión no advirtió una deficiencia que se descubre después. Se propone rechazar cualquier modificación por la sola ausencia del hallazgo en ese informe. Según 171.1, ¿qué conclusión corresponde?", "options": [{"id": "A", "text": "La omisión del hallazgo impide para siempre toda modificación relacionada."}, {"id": "B", "text": "Todo hallazgo posterior queda aprobado como adicional sin procedimiento."}, {"id": "C", "text": "El informe sustituye al expediente técnico y hace innecesario analizar la deficiencia posterior."}, {"id": "D", "text": "Esa sola ausencia no impide aprobar modificaciones no advertidas, sin eximir de verificar los demás requisitos aplicables."}], "correctOption": "D", "explanation": "El 171.1 establece que la revisión no impide aprobar modificaciones contractuales no advertidas en el informe. Ello elimina ese impedimento específico, pero no aprueba automáticamente un adicional ni sus demás presupuestos.", "topic": "Expediente técnico de obra", "competency": "Ejecución contractual", "difficulty": "intermediate", "curriculumVersion": "oece-2025-04-25", "competencyCode": "3", "subcompetencyCode": "3.7", "cognitiveLevel": "apply", "optionRationales": {"A": "Contradice la previsión expresa sobre modificaciones no advertidas del 171.1.", "B": "La posibilidad de aprobar no equivale a aprobación automática ni sustituye el procedimiento.", "C": "El informe de revisión identifica hallazgos y no reemplaza por sí mismo el expediente técnico.", "D": "El 171.1 establece que la revisión no impide aprobar modificaciones contractuales no advertidas en el informe. Ello elimina ese impedimento específico, pero no aprueba automáticamente un adicional ni sus demás presupuestos."}, "reviewChecks": {"unambiguous": true, "distractors": true, "conditions": true, "exceptions": true, "sources": true}, "sourceCutoff": "2026-10-29", "sources": [{"documentId": "8371bce1-f773-4ad8-8efa-1266276ae4ec", "chunkId": "c1a3d4f1-7ee0-4a3e-95e4-b0ad864819ba", "title": "Reglamento de la Ley N.° 32069 — texto actualizado al 09.01.2026", "article": "171", "pageStart": 91, "pageEnd": 92, "quote": "171.1. En el sistema de entrega de solo construcción, el contratista presenta a la entidad contratante y al supervisor un informe técnico de revisión del expediente técnico dentro de los\n\nReglamento de la Ley Nº 32069, Ley General de Contrataciones Públicas Página 92 de 249 doce días siguientes a la suscripción del contrato. Este informe tiene como objetivo detectar posibles deficiencias u omisiones en el expediente técnico, e incluye las posibles prestaciones adicionales, riesgos y otros aspectos que puedan ser advertidos de la sola revisión documental por parte del contratista. Esta revisión no impide la aprobación de modificaciones contractuales no advertidas en el informe técnico.", "version": "Texto actualizado al 09.01.2026", "sha256": "0ebe95b3e05661b80f73c060d6e6ce8dd17621ce34af9277c688dd67e5d99830"}], "status": "published", "confirmReview": true, "reviewBasis": "Revisión asistida por IA el15/11/2026 por encargo y autorización expresa del administrador. Reescrita una pregunta repetida o complementaria hacia un objetivo operativo distinto: Reconocer que revisión inicial del expediente no impide aprobar modificaciones no advertidas. Clave única, condiciones y cada distractor contrastados con los pasajes citados. Objetivo: Reconocer que revisión inicial del expediente no impide aprobar modificaciones no advertidas. Evidencia: art. 171, chunk 205. Sin certificación oficial OECE ni revisión humana independiente; se conserva el corte documental declarado."}, "estadoAnterior": "draft"}, {"numero": "Q211", "id": "060396db-8881-40be-8da0-af8dfcee663c", "decision": "approve", "motivo": "Reescrita una pregunta repetida o complementaria hacia un objetivo operativo distinto: Verificar que sustituto de personal clave conserve condiciones que generaron puntaje además del perfil mínimo. Clave única, condiciones y cada distractor contrastados con los pasajes citados.", "objetivo": "Verificar que sustituto de personal clave conserve condiciones que generaron puntaje además del perfil mínimo", "evidencia": [{"chunkId": "dba573cc-5ffe-4f24-8794-6bdedfb1ef85", "chunk_index": 231, "article": "189", "quote": "189.1. Es responsabilidad del contratista ejecutar su prestación con el personal considerado en la oferta durante el procedimiento de selección. 189.2. El contratista puede solicitar sustituir al personal clave de su plantel técnico, excepcionalmente y con el sustento debido, siempre que quien lo sustituya tenga un perfil igual o mayor a lo establecido en las bases y, en caso de haberse otorgado pu ntaje por el profesional reemplazado, el reemplazante debe cumplir las mismas condiciones que le ameritaron el puntaje al proveedor."}], "input": {"id": "060396db-8881-40be-8da0-af8dfcee663c", "revision": 1, "regime": "32069", "origin": "IA:gemini:gemini-2.5-flash:lote:572461a4-db25-4c42-ba36-cc7c766ad1b4", "prompt": "En una obra se pide, excepcionalmente y con sustento, sustituir a un profesional clave. El propuesto cumple el mínimo de las bases, pero no las condiciones por las que el profesional reemplazado otorgó puntaje a la oferta. Según 189.2, ¿basta cumplir el mínimo?", "options": [{"id": "A", "text": "No; si hubo puntaje por el profesional, el reemplazante debe cumplir las mismas condiciones que lo generaron, además del perfil exigido."}, {"id": "B", "text": "Sí; todo puntaje profesional deja de importar al firmarse el contrato."}, {"id": "C", "text": "Sí; basta que el contratista acepte al reemplazante aunque pierda las condiciones puntuadas."}, {"id": "D", "text": "No; ninguna sustitución de personal clave puede admitirse durante una obra."}], "correctOption": "A", "explanation": "El 189.2 permite sustitución excepcional sustentada con perfil igual o mayor al de las bases; si se otorgó puntaje por el profesional reemplazado, exige conservar las condiciones que lo generaron. Cumplir solo el mínimo no basta en el caso.", "topic": "Modificaciones de obras", "competency": "Ejecución contractual", "difficulty": "intermediate", "curriculumVersion": "oece-2025-04-25", "competencyCode": "3", "subcompetencyCode": "3.10", "cognitiveLevel": "apply", "optionRationales": {"A": "El 189.2 permite sustitución excepcional sustentada con perfil igual o mayor al de las bases; si se otorgó puntaje por el profesional reemplazado, exige conservar las condiciones que lo generaron. Cumplir solo el mínimo no basta en el caso.", "B": "El 189.2 mantiene expresamente las condiciones que generaron el puntaje.", "C": "La aceptación del contratista no sustituye las exigencias del numeral 189.2.", "D": "La norma sí permite sustituciones excepcionales con sustento y condiciones."}, "reviewChecks": {"unambiguous": true, "distractors": true, "conditions": true, "exceptions": true, "sources": true}, "sourceCutoff": "2026-10-29", "sources": [{"documentId": "8371bce1-f773-4ad8-8efa-1266276ae4ec", "chunkId": "dba573cc-5ffe-4f24-8794-6bdedfb1ef85", "title": "Reglamento de la Ley N.° 32069 — texto actualizado al 09.01.2026", "article": "189", "pageStart": 105, "pageEnd": 105, "quote": "189.1. Es responsabilidad del contratista ejecutar su prestación con el personal considerado en la oferta durante el procedimiento de selección. 189.2. El contratista puede solicitar sustituir al personal clave de su plantel técnico, excepcionalmente y con el sustento debido, siempre que quien lo sustituya tenga un perfil igual o mayor a lo establecido en las bases y, en caso de haberse otorgado pu ntaje por el profesional reemplazado, el reemplazante debe cumplir las mismas condiciones que le ameritaron el puntaje al proveedor.", "version": "Texto actualizado al 09.01.2026", "sha256": "0ebe95b3e05661b80f73c060d6e6ce8dd17621ce34af9277c688dd67e5d99830"}], "status": "published", "confirmReview": true, "reviewBasis": "Revisión asistida por IA el15/11/2026 por encargo y autorización expresa del administrador. Reescrita una pregunta repetida o complementaria hacia un objetivo operativo distinto: Verificar que sustituto de personal clave conserve condiciones que generaron puntaje además del perfil mínimo. Clave única, condiciones y cada distractor contrastados con los pasajes citados. Objetivo: Verificar que sustituto de personal clave conserve condiciones que generaron puntaje además del perfil mínimo. Evidencia: art. 189, chunk 231. Sin certificación oficial OECE ni revisión humana independiente; se conserva el corte documental declarado."}, "estadoAnterior": "draft"}, {"numero": "Q212", "id": "e68be20e-b4d9-4264-9708-e6c732743962", "decision": "approve", "motivo": "Reescrita una pregunta repetida o complementaria hacia un objetivo operativo distinto: Aplicar plazo de decisión y silencio en sustitución permanente sin anticipar fecha efectiva del cambio. Clave única, condiciones y cada distractor contrastados con los pasajes citados.", "objetivo": "Aplicar plazo de decisión y silencio en sustitución permanente sin anticipar fecha efectiva del cambio", "evidencia": [{"chunkId": "dba573cc-5ffe-4f24-8794-6bdedfb1ef85", "chunk_index": 231, "article": "189", "quote": "\"189.3. La sustitución permanente del personal clave del plantel técnico debe solicitarse a la entidad contratante diez días hábiles antes de la fecha en la que operaría la sustitución. En caso ésta no se pronuncie en el plazo del numeral 189.5 , se considera autorizada la sustitución. La entidad contratante aplica una penalidad al contratista si se produce una sustitución del mismo integrante del plantel técnico a partir de la segunda vez. El plazo y penalidad señalados no aplican cuando la sustitución se o rigine por caso fortuito o fuerza mayor o por un hecho sobreviniente no imputable al contratista.\""}, {"chunkId": "dba573cc-5ffe-4f24-8794-6bdedfb1ef85", "chunk_index": 231, "article": "189", "quote": "189.5. La entidad contratante autoriza o rechaza la solicitud de sustitución, de manera sustentada, en el plazo máximo de cinco días hábiles, contabilizados desde el día siguiente de presentada la solicitud."}], "input": {"id": "e68be20e-b4d9-4264-9708-e6c732743962", "revision": 1, "regime": "32069", "origin": "IA:gemini:gemini-2.5-flash:lote:57510fe4-da54-47d7-b03a-d841c9df9b53", "prompt": "En una obra se solicitó sustitución permanente de personal clave con diez días hábiles de anticipación. No hay caso fortuito ni hecho sobreviniente. Pasaron cinco días hábiles desde el día siguiente de presentar la solicitud sin respuesta. Según 189.3 modificado y 189.5, ¿qué efecto corresponde?", "options": [{"id": "A", "text": "La solicitud se considera denegada por el silencio."}, {"id": "B", "text": "La sustitución se considera autorizada para la fecha solicitada, sin anticipar por ello la fecha efectiva del cambio."}, {"id": "C", "text": "El plazo de respuesta es siempre diez días hábiles porque ese es el preaviso de presentación."}, {"id": "D", "text": "El silencio autoriza cualquier cambio inmediato, incluso antes de la fecha solicitada."}], "correctOption": "B", "explanation": "El 189.3 modificado vincula la autorización por silencio al plazo del 189.5: cinco días hábiles desde el siguiente de presentar. El preaviso de diez días y la fecha de sustitución son distintos; la autorización no implica adelantar el cambio.", "topic": "Modificaciones de obras", "competency": "Ejecución contractual", "difficulty": "intermediate", "curriculumVersion": "oece-2025-04-25", "competencyCode": "3", "subcompetencyCode": "3.10", "cognitiveLevel": "analyze", "optionRationales": {"A": "El 189.3 modificado prevé autorización y no denegación por ese silencio.", "B": "El 189.3 modificado vincula la autorización por silencio al plazo del 189.5: cinco días hábiles desde el siguiente de presentar. El preaviso de diez días y la fecha de sustitución son distintos; la autorización no implica adelantar el cambio.", "C": "Confunde los diez días de preaviso con cinco de decisión del 189.5.", "D": "La autorización de la solicitud no convierte en inmediata una sustitución prevista para otra fecha."}, "reviewChecks": {"unambiguous": true, "distractors": true, "conditions": true, "exceptions": true, "sources": true}, "sourceCutoff": "2026-10-29", "sources": [{"documentId": "8371bce1-f773-4ad8-8efa-1266276ae4ec", "chunkId": "dba573cc-5ffe-4f24-8794-6bdedfb1ef85", "title": "Reglamento de la Ley N.° 32069 — texto actualizado al 09.01.2026", "article": "189", "pageStart": 105, "pageEnd": 105, "quote": "\"189.3. La sustitución permanente del personal clave del plantel técnico debe solicitarse a la entidad contratante diez días hábiles antes de la fecha en la que operaría la sustitución. En caso ésta no se pronuncie en el plazo del numeral 189.5 , se considera autorizada la sustitución. La entidad contratante aplica una penalidad al contratista si se produce una sustitución del mismo integrante del plantel técnico a partir de la segunda vez. El plazo y penalidad señalados no aplican cuando la sustitución se o rigine por caso fortuito o fuerza mayor o por un hecho sobreviniente no imputable al contratista.\"", "version": "Texto actualizado al 09.01.2026", "sha256": "0ebe95b3e05661b80f73c060d6e6ce8dd17621ce34af9277c688dd67e5d99830"}, {"documentId": "8371bce1-f773-4ad8-8efa-1266276ae4ec", "chunkId": "dba573cc-5ffe-4f24-8794-6bdedfb1ef85", "title": "Reglamento de la Ley N.° 32069 — texto actualizado al 09.01.2026", "article": "189", "pageStart": 105, "pageEnd": 105, "quote": "189.5. La entidad contratante autoriza o rechaza la solicitud de sustitución, de manera sustentada, en el plazo máximo de cinco días hábiles, contabilizados desde el día siguiente de presentada la solicitud.", "version": "Texto actualizado al 09.01.2026", "sha256": "0ebe95b3e05661b80f73c060d6e6ce8dd17621ce34af9277c688dd67e5d99830"}], "status": "published", "confirmReview": true, "reviewBasis": "Revisión asistida por IA el15/11/2026 por encargo y autorización expresa del administrador. Reescrita una pregunta repetida o complementaria hacia un objetivo operativo distinto: Aplicar plazo de decisión y silencio en sustitución permanente sin anticipar fecha efectiva del cambio. Clave única, condiciones y cada distractor contrastados con los pasajes citados. Objetivo: Aplicar plazo de decisión y silencio en sustitución permanente sin anticipar fecha efectiva del cambio. Evidencia: art. 189, chunk 231; art. 189, chunk 231. Sin certificación oficial OECE ni revisión humana independiente; se conserva el corte documental declarado."}, "estadoAnterior": "draft"}, {"numero": "Q213", "id": "1933905e-b9c5-4bfc-8b7e-a203d687d847", "decision": "approve", "motivo": "Reescrita una pregunta repetida o complementaria hacia un objetivo operativo distinto: Identificar naturaleza de pagos a cuenta y periodicidad de valorizaciones de supervisión en texto modificado. Clave única, condiciones y cada distractor contrastados con los pasajes citados.", "objetivo": "Identificar naturaleza de pagos a cuenta y periodicidad de valorizaciones de supervisión en texto modificado", "evidencia": [{"chunkId": "bafa1c9a-9719-4511-a408-45e4e549ade2", "chunk_index": 264, "article": "211", "quote": "Las valorizaciones se realizan mensualmente y son consideradas pagos a cuenta. Las bases pueden establecer periodos distintos de valorización, en cuyo caso contemplan el procedimiento correspondiente para su pago. En las valorizaciones, se incluyen las pre staciones adicionales, extensión de los servicios de supervisión y/u otros pagos que provengan de una modificación contractual, que pueden ser calculados de manera independiente. ”"}], "input": {"id": "1933905e-b9c5-4bfc-8b7e-a203d687d847", "revision": 1, "regime": "32069", "origin": "IA:gemini:gemini-2.5-flash:lote:57510fe4-da54-47d7-b03a-d841c9df9b53", "prompt": "En una consultoría de supervisión de obra, las bases no fijan un período distinto de valorización. Según el artículo 211 modificado, ¿cómo se realizan y qué naturaleza tienen esas valorizaciones?", "options": [{"id": "A", "text": "Solo al final de la obra y como liquidación definitiva."}, {"id": "B", "text": "Trimestralmente, aunque las bases guarden silencio, sin admitir pagos adicionales."}, {"id": "C", "text": "Mensualmente y como pagos a cuenta; las bases pueden prever otros períodos con su procedimiento de pago."}, {"id": "D", "text": "Una sola vez al mes de recepción y con carácter irrevocable de liquidación."}], "correctOption": "C", "explanation": "El 211 modificado establece valorizaciones mensuales consideradas pagos a cuenta. Permite períodos distintos previstos en bases con el procedimiento correspondiente e incluir pagos de modificaciones contractuales; no equivalen a liquidación definitiva.", "topic": "Valorización, recepción y liquidación", "competency": "Ejecución contractual", "difficulty": "intermediate", "curriculumVersion": "oece-2025-04-25", "competencyCode": "3", "subcompetencyCode": "3.11", "cognitiveLevel": "apply", "optionRationales": {"A": "La regla modificada prevé periodicidad mensual, no solo un pago al final.", "B": "El 211 no fija trimestre por defecto ni excluye pagos derivados de modificaciones.", "C": "El 211 modificado establece valorizaciones mensuales consideradas pagos a cuenta. Permite períodos distintos previstos en bases con el procedimiento correspondiente e incluir pagos de modificaciones contractuales; no equivalen a liquidación definitiva.", "D": "Confunde valorizaciones a cuenta con una liquidación única y definitiva."}, "reviewChecks": {"unambiguous": true, "distractors": true, "conditions": true, "exceptions": true, "sources": true}, "sourceCutoff": "2026-10-29", "sources": [{"documentId": "8371bce1-f773-4ad8-8efa-1266276ae4ec", "chunkId": "bafa1c9a-9719-4511-a408-45e4e549ade2", "title": "Reglamento de la Ley N.° 32069 — texto actualizado al 09.01.2026", "article": "211", "pageStart": 119, "pageEnd": 119, "quote": "Las valorizaciones se realizan mensualmente y son consideradas pagos a cuenta. Las bases pueden establecer periodos distintos de valorización, en cuyo caso contemplan el procedimiento correspondiente para su pago. En las valorizaciones, se incluyen las pre staciones adicionales, extensión de los servicios de supervisión y/u otros pagos que provengan de una modificación contractual, que pueden ser calculados de manera independiente. ”", "version": "Texto actualizado al 09.01.2026", "sha256": "0ebe95b3e05661b80f73c060d6e6ce8dd17621ce34af9277c688dd67e5d99830"}], "status": "published", "confirmReview": true, "reviewBasis": "Revisión asistida por IA el15/11/2026 por encargo y autorización expresa del administrador. Reescrita una pregunta repetida o complementaria hacia un objetivo operativo distinto: Identificar naturaleza de pagos a cuenta y periodicidad de valorizaciones de supervisión en texto modificado. Clave única, condiciones y cada distractor contrastados con los pasajes citados. Objetivo: Identificar naturaleza de pagos a cuenta y periodicidad de valorizaciones de supervisión en texto modificado. Evidencia: art. 211, chunk 264. Sin certificación oficial OECE ni revisión humana independiente; se conserva el corte documental declarado."}, "estadoAnterior": "draft"}, {"numero": "Q224", "id": "f5a50b23-8fc0-4ef2-8b6e-d8eae6f20490", "decision": "approve", "motivo": "Reescrita una pregunta repetida o complementaria hacia un objetivo operativo distinto: Delimitar alcance de la segunda verificación de observaciones de recepción sin negar régimen de vicios ocultos. Clave única, condiciones y cada distractor contrastados con los pasajes citados.", "objetivo": "Delimitar alcance de la segunda verificación de observaciones de recepción sin negar régimen de vicios ocultos", "evidencia": [{"chunkId": "396125db-d3d1-49ab-9ffd-586e20fe9ab3", "chunk_index": 266, "article": "212", "quote": "212.8. Dentro de los cinco días hábiles siguientes de comunicado el levantamiento de las observaciones, el comité de recepción de obra verifica únicamente el levantamiento de las observaciones. No es posible formular nuevas observaciones."}, {"chunkId": "422de656-d282-48f2-bca6-38d476abf8f6", "chunk_index": 267, "article": "212", "quote": "Si en el proceso de verificación de la subsanación de las observaciones, el comité de recepción constata la existencia de vicios o defectos distintos a las observaciones antes formuladas, sin perjuicio de suscribir el Acta de Recepción de Obra, inf orma a la entidad\n\nReglamento de la Ley Nº 32069, Ley General de Contrataciones Públicas Página 121 de 249 contratante para que solicite por escrito al contratista las subsanaciones del caso, siempre que constituyan vicios ocultos."}], "input": {"id": "f5a50b23-8fc0-4ef2-8b6e-d8eae6f20490", "revision": 1, "regime": "32069", "origin": "IA:gemini:gemini-2.5-flash:lote:7cfc594a-ee69-41f5-91b7-836d9ee969e2", "prompt": "En la recepción de una obra, el contratista comunica haber levantado el pliego de observaciones. Se realiza la verificación del 212.8 y no se trata de tramitar vicios ocultos distintos. ¿Cuál es el alcance de esa visita del comité?", "options": [{"id": "A", "text": "Reformular todo el expediente y abrir un pliego nuevo sin atender el anterior."}, {"id": "B", "text": "Recibir sin verificar, porque la sola comunicación obliga a aceptar."}, {"id": "C", "text": "Declarar que después de la visita nunca podrán reclamarse vicios ocultos."}, {"id": "D", "text": "Verificar únicamente el levantamiento de las observaciones; en esa actuación no se formulan nuevas observaciones."}], "correctOption": "D", "explanation": "El 212.8 limita la actuación a verificar el levantamiento y prohíbe nuevas observaciones en ella. Eso no elimina el tratamiento diferenciado de vicios ocultos distintos contemplado en 212.10.", "topic": "Valorización, recepción y liquidación", "competency": "Ejecución contractual", "difficulty": "intermediate", "curriculumVersion": "oece-2025-04-25", "competencyCode": "3", "subcompetencyCode": "3.11", "cognitiveLevel": "analyze", "optionRationales": {"A": "El 212.8 no dispone reabrir indiscriminadamente todo el control de recepción.", "B": "La comunicación no sustituye la verificación que exige el 212.8.", "C": "El 212.10 contempla informar sobre vicios ocultos distintos para solicitar su subsanación; no se elimina esa vía.", "D": "El 212.8 limita la actuación a verificar el levantamiento y prohíbe nuevas observaciones en ella. Eso no elimina el tratamiento diferenciado de vicios ocultos distintos contemplado en 212.10."}, "reviewChecks": {"unambiguous": true, "distractors": true, "conditions": true, "exceptions": true, "sources": true}, "sourceCutoff": "2026-10-29", "sources": [{"documentId": "8371bce1-f773-4ad8-8efa-1266276ae4ec", "chunkId": "396125db-d3d1-49ab-9ffd-586e20fe9ab3", "title": "Reglamento de la Ley N.° 32069 — texto actualizado al 09.01.2026", "article": "212", "pageStart": 119, "pageEnd": 121, "quote": "212.8. Dentro de los cinco días hábiles siguientes de comunicado el levantamiento de las observaciones, el comité de recepción de obra verifica únicamente el levantamiento de las observaciones. No es posible formular nuevas observaciones.", "version": "Texto actualizado al 09.01.2026", "sha256": "0ebe95b3e05661b80f73c060d6e6ce8dd17621ce34af9277c688dd67e5d99830"}, {"documentId": "8371bce1-f773-4ad8-8efa-1266276ae4ec", "chunkId": "422de656-d282-48f2-bca6-38d476abf8f6", "title": "Reglamento de la Ley N.° 32069 — texto actualizado al 09.01.2026", "article": "212", "pageStart": 119, "pageEnd": 121, "quote": "Si en el proceso de verificación de la subsanación de las observaciones, el comité de recepción constata la existencia de vicios o defectos distintos a las observaciones antes formuladas, sin perjuicio de suscribir el Acta de Recepción de Obra, inf orma a la entidad\n\nReglamento de la Ley Nº 32069, Ley General de Contrataciones Públicas Página 121 de 249 contratante para que solicite por escrito al contratista las subsanaciones del caso, siempre que constituyan vicios ocultos.", "version": "Texto actualizado al 09.01.2026", "sha256": "0ebe95b3e05661b80f73c060d6e6ce8dd17621ce34af9277c688dd67e5d99830"}], "status": "published", "confirmReview": true, "reviewBasis": "Revisión asistida por IA el15/11/2026 por encargo y autorización expresa del administrador. Reescrita una pregunta repetida o complementaria hacia un objetivo operativo distinto: Delimitar alcance de la segunda verificación de observaciones de recepción sin negar régimen de vicios ocultos. Clave única, condiciones y cada distractor contrastados con los pasajes citados. Objetivo: Delimitar alcance de la segunda verificación de observaciones de recepción sin negar régimen de vicios ocultos. Evidencia: art. 212, chunk 266; art. 212, chunk 267. Sin certificación oficial OECE ni revisión humana independiente; se conserva el corte documental declarado."}, "estadoAnterior": "draft"}, {"numero": "Q225", "id": "4ffb1ea9-b3aa-4dfa-919d-17285d613256", "decision": "approve", "motivo": "Reescrita una pregunta repetida o complementaria hacia un objetivo operativo distinto: Aplicar exclusión de modificaciones de monto por errores de diseño imputables al mismo contratista estandarizado. Clave única, condiciones y cada distractor contrastados con los pasajes citados.", "objetivo": "Aplicar exclusión de modificaciones de monto por errores de diseño imputables al mismo contratista estandarizado", "evidencia": [{"chunkId": "1eea072c-47c2-4980-8267-8712117ea44f", "chunk_index": 280, "article": "221", "quote": "g) En los sistemas de entrega en los que el contratista de la obra también se encuentra a cargo de la elaboración del expediente técnico, no es posible aprobar modificaciones durante la ejecución de obra que incidan en el monto contractual si son consecuen cia de deficiencias o errores en el expediente técnico que le sean imputables."}], "input": {"id": "4ffb1ea9-b3aa-4dfa-919d-17285d613256", "revision": 1, "regime": "32069", "origin": "IA:gemini:gemini-2.5-flash:lote:7cfc594a-ee69-41f5-91b7-836d9ee969e2", "prompt": "En un contrato estandarizado internacional, el contratista de obra también elaboró el expediente técnico. En ejecución pide aumentar el monto para corregir errores de ese expediente que le son imputables. Aunque haya presupuesto y no se supere 50%, ¿qué dispone 221.2.g?", "options": [{"id": "A", "text": "No es posible aprobar por esa causa modificaciones de monto durante la ejecución."}, {"id": "B", "text": "Puede aprobarse necesariamente porque todo aumento inferior 50% es admisible."}, {"id": "C", "text": "Basta contar con presupuesto para trasladar a la entidad cualquier error imputable de diseño."}, {"id": "D", "text": "El contratista puede validar unilateralmente el aumento por haber elaborado el expediente."}], "correctOption": "A", "explanation": "El 221.2.gprohíbe aprobar en ejecución modificaciones que incidan en el monto si derivan de errores o deficiencias del expediente imputables al contratista que también elaboró el diseño. Tener presupuesto y estar bajo el límite no elimina esa prohibición.", "topic": "Contratos estandarizados", "competency": "Ejecución contractual", "difficulty": "intermediate", "curriculumVersion": "oece-2025-04-25", "competencyCode": "3", "subcompetencyCode": "3.12", "cognitiveLevel": "analyze", "optionRationales": {"A": "El 221.2.gprohíbe aprobar en ejecución modificaciones que incidan en el monto si derivan de errores o deficiencias del expediente imputables al contratista que también elaboró el diseño. Tener presupuesto y estar bajo el límite no elimina esa prohibición.", "B": "El límite del literal d) no desplaza la prohibición específica del literal g).", "C": "El financiamiento no convierte en aprobable esa causa expresamente excluida.", "D": "La autoría del expediente no otorga potestad unilateral de incrementar el monto."}, "reviewChecks": {"unambiguous": true, "distractors": true, "conditions": true, "exceptions": true, "sources": true}, "sourceCutoff": "2026-10-29", "sources": [{"documentId": "8371bce1-f773-4ad8-8efa-1266276ae4ec", "chunkId": "1eea072c-47c2-4980-8267-8712117ea44f", "title": "Reglamento de la Ley N.° 32069 — texto actualizado al 09.01.2026", "article": "221", "pageStart": 125, "pageEnd": 126, "quote": "g) En los sistemas de entrega en los que el contratista de la obra también se encuentra a cargo de la elaboración del expediente técnico, no es posible aprobar modificaciones durante la ejecución de obra que incidan en el monto contractual si son consecuen cia de deficiencias o errores en el expediente técnico que le sean imputables.", "version": "Texto actualizado al 09.01.2026", "sha256": "0ebe95b3e05661b80f73c060d6e6ce8dd17621ce34af9277c688dd67e5d99830"}], "status": "published", "confirmReview": true, "reviewBasis": "Revisión asistida por IA el15/11/2026 por encargo y autorización expresa del administrador. Reescrita una pregunta repetida o complementaria hacia un objetivo operativo distinto: Aplicar exclusión de modificaciones de monto por errores de diseño imputables al mismo contratista estandarizado. Clave única, condiciones y cada distractor contrastados con los pasajes citados. Objetivo: Aplicar exclusión de modificaciones de monto por errores de diseño imputables al mismo contratista estandarizado. Evidencia: art. 221, chunk 280. Sin certificación oficial OECE ni revisión humana independiente; se conserva el corte documental declarado."}, "estadoAnterior": "draft"}, {"numero": "Q241", "id": "4080132f-ba85-466f-bdff-f5e87993f613", "decision": "approve", "motivo": "Reescrita una pregunta repetida o complementaria hacia un objetivo operativo distinto: Distinguir autorización judicial de anulación de laudo de una apelación y reconocer competencia indelegable. Clave única, condiciones y cada distractor contrastados con los pasajes citados.", "objetivo": "Distinguir autorización judicial de anulación de laudo de una apelación y reconocer competencia indelegable", "evidencia": [{"chunkId": "8b96e880-acea-4284-a80b-0a1562d57b72", "chunk_index": 100, "article": "84", "quote": "84.9. El laudo arbitral es inapelable, definitivo y obligatorio para las partes desde el momento de su notificación y se debe notificar a las partes a través de la Pladicop . Contra dicho laudo, solo cabe interponer recurso de anulación. Las entidades contratantes solo pueden iniciar la acción judicial de anulación de laudo previa autorización del titular de la entidad, mediante resolución debidamente motivada, bajo responsab ilidad, siendo esta facultad indelegable. Para tal efecto, se realiza el análisis costo - beneficio, considerando el costo en tiempo y recursos del proceso judicial, la expectativa de éxito de seguir la anulación. Constituye responsabilidad funcional impulsar la anulación del laudo arbitral cuando el análisis costo - beneficio determina que la posición de la entidad razonablemente no puede ser acogida. Solo en caso de indicios de comis ión de delitos, la decisión de impugnar un laudo arbitral es objeto de control por parte de la Contraloría General de la República."}], "input": {"id": "4080132f-ba85-466f-bdff-f5e87993f613", "revision": 3, "regime": "32069", "origin": "IA:gemini:gemini-2.5-flash:lote:52b5f134-72ee-410e-b815-3b6f06d0573d", "prompt": "Una entidad evalúa pedir judicialmente anulación de un laudo de contratación pública. Según 84.9 de la Ley, ¿qué requisito institucional debe cumplirse antes de iniciar esa acción?", "options": [{"id": "A", "text": "Acuerdo verbal del área usuaria, porque la anulación equivale a otra apelación administrativa."}, {"id": "B", "text": "Autorización del titular mediante resolución motivada, facultad indelegable, con análisis costo-beneficio."}, {"id": "C", "text": "Autorización del propio tribunal arbitral que emitió el laudo."}, {"id": "D", "text": "Decisión unilateral de cualquier servidor, sin análisis, porque impugnar siempre es obligatorio."}], "correctOption": "B", "explanation": "El 84.9 exige autorización del titular mediante resolución motivada y declara esa facultad indelegable. Requiere análisis costo-beneficio de tiempo, recursos y expectativa de éxito; el laudo es inapelable y la vía prevista es la anulación, no otra apelación.", "topic": "Controversias y solución de conflictos", "competency": "Ejecución contractual", "difficulty": "intermediate", "curriculumVersion": "oece-2025-04-25", "competencyCode": "3", "subcompetencyCode": "3.5", "cognitiveLevel": "analyze", "optionRationales": {"A": "No basta acuerdo verbal ni se trata de apelación administrativa del laudo.", "B": "El 84.9 exige autorización del titular mediante resolución motivada y declara esa facultad indelegable. Requiere análisis costo-beneficio de tiempo, recursos y expectativa de éxito; el laudo es inapelable y la vía prevista es la anulación, no otra apelación.", "C": "El 84.9 no atribuye al tribunal arbitral la autorización institucional para demandar anulación.", "D": "El 84.9 exige motivación y análisis; no dispone impugnar todo laudo sin evaluar viabilidad."}, "reviewChecks": {"unambiguous": true, "distractors": true, "conditions": true, "exceptions": true, "sources": true}, "sourceCutoff": "2026-10-29", "sources": [{"documentId": "dc721f35-138c-41b8-8dca-16289f74d9df", "chunkId": "8b96e880-acea-4284-a80b-0a1562d57b72", "title": "Ley N.° 32069 — texto actualizado al 19.07.2026", "article": "84", "pageStart": 40, "pageEnd": 42, "quote": "84.9. El laudo arbitral es inapelable, definitivo y obligatorio para las partes desde el momento de su notificación y se debe notificar a las partes a través de la Pladicop . Contra dicho laudo, solo cabe interponer recurso de anulación. Las entidades contratantes solo pueden iniciar la acción judicial de anulación de laudo previa autorización del titular de la entidad, mediante resolución debidamente motivada, bajo responsab ilidad, siendo esta facultad indelegable. Para tal efecto, se realiza el análisis costo - beneficio, considerando el costo en tiempo y recursos del proceso judicial, la expectativa de éxito de seguir la anulación. Constituye responsabilidad funcional impulsar la anulación del laudo arbitral cuando el análisis costo - beneficio determina que la posición de la entidad razonablemente no puede ser acogida. Solo en caso de indicios de comis ión de delitos, la decisión de impugnar un laudo arbitral es objeto de control por parte de la Contraloría General de la República.", "version": "Texto actualizado al 19.07.2026", "sha256": "f14ffa37b824b8af03c0b97e0603839a786ed61c7ca07b1d300c9af928d133f7"}], "status": "published", "confirmReview": true, "reviewBasis": "Revisión asistida por IA el15/11/2026 por encargo y autorización expresa del administrador. Reescrita una pregunta repetida o complementaria hacia un objetivo operativo distinto: Distinguir autorización judicial de anulación de laudo de una apelación y reconocer competencia indelegable. Clave única, condiciones y cada distractor contrastados con los pasajes citados. Objetivo: Distinguir autorización judicial de anulación de laudo de una apelación y reconocer competencia indelegable. Evidencia: art. 84, chunk 100. Sin certificación oficial OECE ni revisión humana independiente; se conserva el corte documental declarado."}, "estadoAnterior": "draft"}], "newSources": []}$correcciones36$::jsonb;
 item jsonb; entry jsonb; s jsonb; ch public.document_chunks; d public.documents;
 actor uuid; approved integer; expected_reviews integer; before_attempts text; after_attempts text; existing public.exam_questions; before_others text; after_others text;
 before_reviews bigint; after_reviews bigint; changed integer := 0;
begin
 if jsonb_array_length(payload->'patches') <> 61 then raise exception 'Alcance distinto de 61'; end if;
 if (select count(distinct x->'input'->>'id') from jsonb_array_elements(payload->'patches') x) <> 61 then raise exception 'UUID repetido'; end if;
 -- Bloquear únicamente las preguntas del lote en orden determinista.
 perform q.id from public.exam_questions q
 where q.id in (select (x->'input'->>'id')::uuid from jsonb_array_elements(payload->'patches') x)
 order by q.id for update;
 if (select count(*) from public.exam_questions q where q.id in
   (select (x->'input'->>'id')::uuid from jsonb_array_elements(payload->'patches') x)) <> 61 then
  raise exception 'No se encontraron todos los UUID';
 end if;
 select md5(coalesce(jsonb_agg(to_jsonb(q) order by q.id),'[]'::jsonb)::text) into before_others
 from public.exam_questions q where q.id not in
 (select (x->'input'->>'id')::uuid from jsonb_array_elements(payload->'patches') x);
 select count(*) into before_reviews from public.exam_question_reviews;
 select count(*) into expected_reviews from jsonb_array_elements(payload->'patches') j where j->'input'->>'status'='published';
 if (select count(distinct created_by) from public.exam_questions where id in (select (j->'input'->>'id')::uuid from jsonb_array_elements(payload->'patches') j))<>1 then raise exception 'Identidad administrativa ambigua';end if;
 select distinct created_by into actor from public.exam_questions where created_by is not null and id in (select (j->'input'->>'id')::uuid from jsonb_array_elements(payload->'patches') j);
 if not exists(select 1 from public.profiles where id=actor and role='admin') then raise exception 'El autor del banco no es administrador';end if;
 select md5(coalesce(jsonb_agg(to_jsonb(t) order by id),'[]'::jsonb)::text) into before_attempts from public.exam_attempts t;

 for item in select value from jsonb_array_elements(payload->'patches') loop
  entry:=item->'input';
  select * into existing from public.exam_questions where id=(entry->>'id')::uuid;
  if existing.revision <> (entry->>'revision')::integer or existing.status <> item->>'estadoAnterior' then
   raise exception 'La pregunta % cambió; no se aplicó el lote',item->>'numero' using errcode='40001';
  end if;
  if entry->>'status' not in ('draft','published') then raise exception 'Estado no autorizado'; end if;
  if entry->>'status'='published' and (entry->>'confirmReview'<>'true' or
   exists(select 1 from jsonb_each_text(entry->'reviewChecks') j where j.value<>'true')) then
   raise exception 'Publicación sin comprobaciones';
  end if;
 end loop;
 -- Referencias editoriales exactas para corregir etiquetas de artículos; no se modifica el corpus original.
 for s in select value from jsonb_array_elements(payload->'newSources') loop
  select * into ch from public.document_chunks where id=(s->>'id')::uuid;
  if found then
   if ch.content<>s->>'content' or ch.metadata->>'article'<>s->'metadata'->>'article' then raise exception 'Referencia derivada diferente';end if;
  else
   select * into ch from public.document_chunks where id=(s->'metadata'->>'derivedFromChunkId')::uuid;
   if not found or ch.document_id<>(s->>'document_id')::uuid or strpos(ch.content,s->>'content')=0 then raise exception 'Extracto no literal';end if;
   perform pg_advisory_xact_lock(hashtextextended(s->>'document_id',0));
   if (select coalesce(max(chunk_index),-1)+1 from public.document_chunks where document_id=(s->>'document_id')::uuid)<>(s->>'chunk_index')::integer then raise exception 'Cambió la secuencia del corpus; revisar';end if;
   insert into public.document_chunks(id,document_id,chunk_index,page_start,page_end,content,metadata)
   values((s->>'id')::uuid,(s->>'document_id')::uuid,(s->>'chunk_index')::integer,(s->>'page_start')::integer,(s->>'page_end')::integer,s->>'content',s->'metadata');
  end if;
 end loop;
 for item in select value from jsonb_array_elements(payload->'patches') loop
  entry:=item->'input';
  for s in select value from jsonb_array_elements(entry->'sources') loop
   select * into ch from public.document_chunks where id=(s->>'chunkId')::uuid;
   if not found or ch.document_id<>(s->>'documentId')::uuid then raise exception 'Fragmento inexistente'; end if;
   select * into d from public.documents where id=ch.document_id;
   if d.status<>'indexed' or d.es_institucional is distinct from true or
    d.metadata->>'indexedTextComplete' is distinct from 'true' or
    d.metadata->>'sha256' is distinct from s->>'sha256' or
    d.metadata->>'officialVersion' is distinct from s->>'version' or d.title<>s->>'title' or
    ch.metadata->>'article' is distinct from s->>'article' or
    ch.page_start is distinct from (s->>'pageStart')::integer or ch.page_end is distinct from (s->>'pageEnd')::integer or
    coalesce((ch.metadata->>'ocrPartial')::boolean,false) or
    strpos(regexp_replace(ch.content,'\s+',' ','g'),regexp_replace(s->>'quote','\s+',' ','g'))=0 then
    raise exception 'La fuente de % requiere revisión; no se aplicó el lote',item->>'numero';
   end if;
   if coalesce(d.metadata->>'regime'<>entry->>'regime',true) and
      not coalesce(d.metadata->'declaredRegimes' ? (entry->>'regime'),false) then
    raise exception 'Régimen de fuente incompatible';
   end if;
  end loop;
  -- Publicación asistida por encargo explícito del administrador, con evidencia individual.
  perform public.ace_exam_edit(actor,entry);
  select * into existing from public.exam_questions where id=(entry->>'id')::uuid;
  if existing.status<>entry->>'status' or existing.revision<>(entry->>'revision')::integer+1 or
    (entry->>'status'='published' and (existing.reviewed_by is distinct from actor or existing.reviewed_at is null or not public.ace_exam_prepared(existing))) or
    (entry->>'status'='draft' and (existing.reviewed_by is not null or existing.reviewed_at is not null)) or
    existing.prompt<>entry->>'prompt' or existing.options<>entry->'options' or
    existing.correct_option<>entry->>'correctOption' or existing.sources<>entry->'sources' then
   raise exception 'Verificación posterior fallida';
  end if;
  changed:=changed+1;
 end loop;
 select md5(coalesce(jsonb_agg(to_jsonb(q) order by q.id),'[]'::jsonb)::text) into after_others
 from public.exam_questions q where q.id not in
 (select (x->'input'->>'id')::uuid from jsonb_array_elements(payload->'patches') x);
 select count(*) into after_reviews from public.exam_question_reviews;
 select md5(coalesce(jsonb_agg(to_jsonb(t) order by id),'[]'::jsonb)::text) into after_attempts from public.exam_attempts t;

 if changed<>61 or before_others<>after_others or before_reviews+expected_reviews<>after_reviews or before_attempts<>after_attempts then
  raise exception 'Se alteraron registros fuera del alcance';
 end if;
end $operation$;
commit;
select status,count(*) as total from public.exam_questions group by status order by status;
